// OTOMATİK ÜRETİLDİ — elle düzenleme. `npm run madde:uret` ile yenile.
// Kaynak: D:\JSPS Fabrika ... KANUN_MASTER_DOSYALARI/MUSTEREK/*/​*MASTER*.md (📜 Metin blokları).
// Anahtar = "<etiket> m.<no>" → kart.madde_no ile birebir eşleşir.
// maddeMetni() bu registry'yi el-yazımı MADDE_METINLERI'nden SONRA kontrol eder.

export const KART_MADDE_METINLERI: Record<string, string> = {
  "2521 Tüfekler Yön m.1": "Madde 1 - Bu yönetmeliğin amacı; 2521 sayılı Avda ve Sporda Kullanılan Tüfekler, Nişan Tabancaları ve Av Bıçaklarının Yapımı Alımı, Satımı ve Bulundurulmasına Dair Kanunun uygulama şeklini belirlemektedir. Madde 2 - Bu Yönetmelik; yivsiz av tüfekleri ile sporda kullanılan nişan tüfek ve tabancaları ve bunların aksamını imal eden fabrika ve imalathanelerin kurulması ve işletilmesine izin verilmesi, mamullerinin standardizasyonu ve denetlenmesine ilişkin hükümler ile 2521 sayılı Kanun kapsamına giren tüfeklerin alımı satımı, bulundurulması ve bunlar için düzenlenecek belge ve kayıtların tesisiyle ilgili esas ve usûlleri kapsar. Madde 3 - Bu yönetmelik 2521 sayılı Kanunun 15. Maddesine göre düzenlenmiştir.",
  "2521 Tüfekler Yön m.11": "Madde 11 - Av Bıçağı imal eden fabrika veya imalathaneler, imal ettikleri bıçakların namlusunun kabza ile bağlantılı ön kısmına, imalatçı firma adı ya da rumuzunu ve \"T.M.\" harflerini ihtiva eden damga ile damgalatarak zorundadırlar. (...) Bu yönetmelikte tanımı ve özellikleri belirtilen av bıçaklarının işyeri veya meskende bulundurulması belgeye tabi değildir. Ancak, av tezkereleriyle birlikte avlaklarda üstte taşınabilir. Av bıçakları meskun mahalde veya şehir içinde aşağıda gösterildiği şekilde taşınır. a) Av torbası veya çantasında, b) Ani olaylarda kullanılmayı engelleyecek biçimde kağıt veya bezle sarılıp paketlenmiş şekilde üstte, Bu madde hükmüne aykırı olarak av bıçağı taşıyanlar hakkında gerekli yasal işlem yapılır.",
  "2521 Tüfekler Yön m.12": "Madde 12 - (Değişik:RG-22/4/2009-27208) Bu Yönetmelik hükümlerine göre yivsiz tüfek ruhsatnamesi alan kişiler bu belgelerde kayıtlı yivsiz av tüfeklerini sadece yivsiz tüfek ruhsatnamesi olan kişilere satabilir veya hibe yoluyla devredebilir. Devreden ve devralan kişiler en geç bir ay içinde ruhsatname düzenleyen makamlara başvurarak devrettikleri tüfeği belgelerinden sildirmek ve devraldıkları tüfeği belgelerine işletmek zorundadır. (...) Madde 13 - (...) Bu şekilde satın alınan av tüfeklerinin en geç bir ay içerisinde belgenin alındığı makama müracaatla cins, marka, çap ve seri numarasının kaydettirilmesi zorunludur. Ruhsatname üzerine tüfeklerin kaydedilmesi işlemi esnasında tüfeklerin görülerek tespitinin yapılması esastır.",
  "2521 Tüfekler Yön m.14": "Madde 14 - (Değişik:RG-11/06/1998-23369) Aşağıda belirtilen hallerden birine giren kimselere hiçbir şekilde avda ve sporda kullanılan tüfek, nişan tabancası ve av bıçağı yapımı alımı, satımı, taşınması ve bulundurulması izni ve belgesi verilmez. a) Ateşli silahla işlenen cürümlerden hükümlü bulunanlar, (...) h) Uyuşturucu ve psikotrop maddeleri (...) suçlarından biriyle mahkum olanlar, ı) Kısıtlı olanlar ile Kamu hizmetinden yasaklılar, i) Akıl hastası veya psikolojik ve nörolojik rahatsızlıkları olanlar, j) 18 yaşını bitirmemiş olanlar, Yukarıdaki fıkranın (a), (b), (c), (d), (e), (f), (g) ve (h) bentleri kapsamına girenler, affa uğramış olsalar veya mahkumiyetleri bütün neticeleriyle birlikte ortadan kalksa yada mahkemelerce verilen karar üzerine adli sicilden silinmiş olsa bile, kendilerine hiçbir suretle bu Yönetmelik kapsamına giren belge ve izinler verilmez. (...) Bu madde de belirtilen mahkumiyet, kesinleşmiş mahkumiyettir.",
  "2521 Tüfekler Yön m.18": "Madde 18 - (Değişik ibare:RG-22/4/2009-27208) Yivsiz tüfek ruhsatnamesi alan kişiler ve bunların sahip olduğu silahlar için, belgeyi düzenleyen zabıta makamlarınca (Örnek - 6) deki Silah Kayıt Defteri tutulur. Silah kayıt defteri hiçbir şekilde imha edilemez. Kayıt defterleri görev değişikliklerinde görev devralan yetkiliye tutanakla teslim edilir. Silah kayıt defterinden sahife koparılamaz, silinti ve kazıntı yapılamaz. Yanlışlıklar ve hatalı kayıtlar açıklamalar hanesine gerekli şerh verilmek ve sorumlu amirce imzalanıp mühürlendikten sonra kaydın üstü çizilir.\n\nEk Madde 2 - (Ek:RG-07/12/2000-24253) Bu Yönetmelikle düzenlenen ve Emniyet Genel Müdürlüğünce yerine getirilen yetki ve görevlerden jandarma sorumluluk bölgesinde ikamet eden gerçek ve tüzel kişilere ilişkin olanlar, aynı esaslara göre Jandarma Genel Komutanlığınca yerine getirilir. Jandarma Genel Komutanlığınca yerine getirilecek işlemlere ilişkin olarak, polis laboratuarlarınca yerine getirilen görevler jandarma kriminal laboratuarınca, Türk Polis Teşkilatını Güçlendirme Vakfınca yerine getirilen görevler Jandarma Asayiş Vakfınca yerine getirilir. (...)",
  "2521 Tüfekler Yön m.4": "Madde 4 - Bu yönetmelikte geçen; a) Yivsiz av tüfekleri: Avda ve atıcılık sporunda kullanılan ve namlularında yiv - set bulunmayan tüfekleri, b) Spor ve nişan tüfek ve tabancaları: Hava ve gaz basıncı ile çalışan ateşsiz, namlusu yivli veya yivsiz olan, uluslararası standartlara uygun tüfek ve tabancaları, c) Av Bıçağı: Sadece avda kullanılan, av hayvanlarını kesmeye, yüzmeye, parçalamaya yarayan oluksuz, sırtı küt veya testereli bıçakları, d) (Ek:RG-11/7/2025-32953) Test Merkezi: Bu Yönetmelik kapsamında imal edilen veya ithal edilen yivsiz av tüfekleri ile spor ve nişan tüfek ve tabancalarının ilgili Türk standartlarına uygunluğunu sertifikalandırmak amacıyla muayene ve deneylerin gerçekleştirildiği, İçişleri Bakanlığı veya Sanayi ve Teknoloji Bakanlığınca kurulan merkezi, ifade eder.",
  "2521 Tüfekler Yön m.5": "Fabrika veya imalathane kurmak isteyenler; kuruluş izni almak için (Değişik ibare:RG-11/7/2025-32953) Sanayi ve Teknoloji Bakanlığına aşağıda belirtilen bilgi ve belgeleri kapsayan üç nüsha olarak hazırlanmış dosya ile müracaat eder. (...) Teknik sorumlunun makine mühendisi olma şartı aranır. Bir teknik sorumlu mühendis, yalnızca bir ikamet adresi geçerli olmak şartıyla ikamet etmiş olduğu il sınırları içerisinde en fazla 20 firmanın teknik sorumluluğunu üstlenebilir. (...) Kuruluş izni, fabrika veya imalathanenin yıllık kapasitesi dikkate alınarak ve herhalde iki yılı geçmemek üzere İçişleri Bakanlığınca belirlenecek süre için geçerlidir. Bu süre ancak, (...) bir seneyi geçmemek ve bir defaya mahsus olmak üzere uzatılabilir.",
  "2521 Tüfekler Yön m.7": "Madde 7 - (Değişik:RG-11/7/2025-32953) Yivsiz av tüfeği imal eden fabrika ve imalathanelerde üretilen tüfeklerin ilgili Türk standartlarına uygun imal edilip edilmediği hususundaki denetimler İçişleri Bakanlığı ile Sanayi ve Teknoloji Bakanlığınca ilgili mevzuat çerçevesinde müştereken yapılır. Namlu basınç testlerine ilişkin kriterler TS 870 standardı kapsamında belirlenir. (...) Test Merkezleri, İçişleri Bakanlığı ile Sanayi ve Teknoloji Bakanlığı temsilcilerinden oluşan komisyon tarafından yılda en az bir defa denetlenir. (...) Bu madde kapsamındaki Türk standartlarına uygunluk testleri, sadece izin verilen Test Merkezlerinde yapılır.",
  "2521 Tüfekler Yön m.8": "Madde 8 - Bu yönetmelik kapsamına giren yivsiz av tüfekleri ile nişan tüfek ve tabancası imal eden kişi ve kuruluşlar, o ay içinde imal ettikleri ve sattıkları mamûllerin cins, marka, çap ve seri numaralarını belirtmek koşulu ile miktarını ve satın alan kişi ve kuruluşun ad ve açık adreslerini belirleyecek tarzda iki nüsha olarak düzenleyecekleri (...) listeleri, (...) ertesi ayın sonuna kadar İlçelerde Kaymakamlığa, İl Merkez İlçelerinde Valiliğe vermek zorundadırlar. (...) Polis teşkilatı bulunmayan yerlerde bu görevi Jandarma Komutanlıkları yapar. Madde 9 - (Değişik birinci fıkra:RG-22/4/2009-27208) Fabrika ve İmalathanelerde yivsiz tüfeklerin satışında; satıcıdan (bayilerden) satıcılık belgesi, alıcıdan yivsiz tüfek satın alma belgesi aranır. Hava ve gaz basıncı ile çalışan ateşsiz tüfek ve tabanca satışlarında bu belge aranmaz.",
  "6136 Ateşli Silahlar m.11": "Hatıra teşkil eden veya antika olan ateşli silahlarla bıçakların bulundurulmasına izin verilmesi zorunludur. Ancak, görevleri nedeniyle Devletçe verilen veya kendilerince bu amaçla temin edilen ve bu görevleri sona erdikten sonra meskenlerinde kalan veya kanuni yakınlarına intikal eden kılıç, meç ve benzeri aletler için izin belgesi aranmaz. Antika olan ateşli silahlarla bıçaklar için verilen izin bunların yalnız sahibine bırakılmasına veya nakline müsaadeyi tazammun edip üstte taşımaya cevaz vermez. Antika olan ateşli silahlarla bıçakların izin vesikalarıyla birlikte satışı serbesttir. Bu Kanunun uygulanmasında hatıra silah deyimi: a) Yurt içinde ve yurt dışında yabancı Devlet veya hükümet başkanları ya da hükümet üyeleri tarafından ya da hükümet adına kendilerine hediye edilip, hediye edildiği usulüne göre belgelenmiş olan, b) Devlet Başkanı, Başbakan veya Genelkurmay Başkanı tarafından hediye edilen ve hediye edildiği belgelendirilen (...) ateşli veya ateşsiz silah ve bıçakları ifade eder. Antika silah deyimi; eskiden kalma, değerli belli bir özelliği olan, benzerlerine az rastlanan ve artık imal edilmeyen ateşli, ateşsiz silah ve bıçakları ifade eder.",
  "6136 Ateşli Silahlar m.12": "Her kim bu Kanunun kapsamına giren ateşli silahları, bunlara ait mermileri veya bunlara ait namlu, sürgü, gövde, çerçeve, silindir, mekanizma başı, çıkarıcı, tırnak, ateşleme iğnesinden oluşan ana veya balistik önemi haiz parçaları ülkeye sokar veya sokmaya kalkışır veya bunların ülkeye sokulmasına aracılık eder veya bunları (...) ülkede yapar veya (...) bir yerden diğer bir yere taşır veya yollar veya taşımaya bilerek aracılık eder, satar veya satmaya aracılık ederse veya bu amaçla bulundurursa beş yıldan oniki yıla kadar hapis ve beşyüz günden beşbin güne kadar adlî para cezasıyla cezalandırılır. (...) iki veya daha çok kişinin birlikte işlemeleri halinde (...) sekiz yıldan onbeş yıla kadar hapis ve bin günden onbin güne kadar adlî para cezasına hükmolunur. (...) suç işlemek amacıyla kurulmuş bir örgütün faaliyeti çerçevesinde işlenmesi halinde, verilecek cezalar bir kat artırılır. (...) miktar bakımından vahim olması halinde (...) cezalar yarı oranında artırılarak hükmolunur. (Ek fıkra:21/11/2024-7533/11 md.) Kurusıkı tabir edilen ses veya gaz fişeği ya da benzerlerini atabilen silahı, teknik özelliklerinde değişiklik yaparak bu Kanun hükümlerine tabi silah haline dönüştürmek eylemi (...) üretim olarak kabul edilir ve bu madde hükümlerine göre cezalandırılır.\n\nBu Kanun hükümlerine aykırı olarak ateşli silahları, bunlara ait mermileri veya bunlara ait (...) ana veya balistik önemi haiz parçaları ya da ses veya gaz fişeği atabilen silah iken bu Kanun hükümlerine tabi silah vasfına dönüştürülen silahları satın alan veya taşıyanlar veya bulunduranlar hakkında iki yıldan dört yıla kadar hapis ve yüz günden beşyüz güne kadar adlî para cezasına hükmolunur. Ateşli silahın, (...) 12 nci maddesinin dördüncü fıkrasında sayılanlardan olması ya da (...) sayı veya nitelik bakımından vahim olması halinde beş yıldan sekiz yıla kadar hapis (...). (...) ateşli silahın bir adet olması ve mutat sayıdaki mermilerinin (...) ev veya işyerinde bulundurulması halinde verilecek ceza bir yıldan üç yıla kadar hapis ve yüz günden beşyüz güne kadar adlî para cezasıdır. (...) pek az sayıda bulundurulmasının veya taşınmasının mahkemece vahim olarak takdir edilmemesi durumunda hükmolunacak ceza altı aya kadar hapis ve otuz günden beşyüz güne kadar adlî para cezasıdır. (Değişik beşinci fıkra:21/11/2024-7533/12 md.) Bu madde kapsamındaki bulundurma ve taşıma fiilinin; vefat, sağlık durumu, mahkûmiyet, müsadere, satın alma veya devir nedeniyle yapılan ruhsatlandırma ya da ruhsat yenileme işlemlerinde (...) yükümlülüklere aykırı davranılarak işlenmesi halinde onbin Türk Lirasından yirmibeşbin Türk Lirasına kadar idari para cezasına hükmolunur. (Ek fıkra:21/11/2024-7533/12 md.) Nakil izin belgesi almaksızın, bulundurma izni verilen silahını mesken veya işyeri değişikliği nedeniyle nakledenler hakkında onbin Türk Lirasından yirmibeşbin Türk Lirasına kadar idari para cezasına hükmolunur. (...) idari para cezası vermeye mülki idare amiri yetkilidir.\n\nHer kim bu Kanunun kapsamına giren ateşli silahları, bunlara ait mermileri veya bunlara ait namlu, sürgü, gövde, çerçeve, silindir, mekanizma başı, çıkarıcı, tırnak, ateşleme iğnesinden oluşan ana veya balistik önemi haiz parçaları ülkeye sokar veya sokmaya kalkışır veya bunların ülkeye sokulmasına aracılık eder veya bunları (...) ülkede yapar veya (...) bir yerden diğer bir yere taşır veya yollar veya taşımaya bilerek aracılık eder, satar veya satmaya aracılık ederse veya bu amaçla bulundurursa beş yıldan oniki yıla kadar hapis ve beşyüz günden beşbin güne kadar adlî para cezasıyla cezalandırılır. (...) iki veya daha çok kişinin birlikte işlemeleri halinde (...) sekiz yıldan onbeş yıla kadar hapis (...). (...) suç işlemek amacıyla kurulmuş bir örgütün faaliyeti çerçevesinde işlenmesi halinde, verilecek cezalar bir kat artırılır. (...) miktar bakımından vahim olması halinde (...) cezalar yarı oranında artırılarak hükmolunur.",
  "6136 Ateşli Silahlar m.13": "Bu Kanun hükümlerine aykırı olarak ateşli silahları, bunlara ait mermileri veya bunlara ait namlu, sürgü, gövde, çerçeve, silindir, mekanizma başı, çıkarıcı, tırnak, ateşleme iğnesinden oluşan ana veya balistik önemi haiz parçaları (...) satın alan veya taşıyanlar veya bulunduranlar hakkında iki yıldan dört yıla kadar hapis ve yüz günden beşyüz güne kadar adlî para cezasına hükmolunur. Ateşli silahın, (...) 12 nci maddesinin dördüncü fıkrasında sayılanlardan olması ya da silahın, mermilerin (...) sayı veya nitelik bakımından vahim olması halinde beş yıldan sekiz yıla kadar hapis (...). (...) ateşli silahın bir adet olması ve mutat sayıdaki mermilerinin (...) ev veya işyerinde bulundurulması halinde verilecek ceza bir yıldan üç yıla kadar hapis ve yüz günden beşyüz güne kadar adlî para cezasıdır. Ateşli silahlara ait mermilerin veya bunlara ait (...) parçaların pek az sayıda bulundurulmasının veya taşınmasının mahkemece vahim olarak takdir edilmemesi durumunda hükmolunacak ceza altı aya kadar hapis ve otuz günden beşyüz güne kadar adlî para cezasıdır. (Değişik beşinci fıkra:21/11/2024-7533/12 md.) Bu madde kapsamındaki bulundurma ve taşıma fiilinin; vefat, sağlık durumu, mahkûmiyet, müsadere, satın alma veya devir nedeniyle yapılan ruhsatlandırma ya da ruhsat yenileme işlemlerinde bu Kanunda düzenlenen yükümlülüklere aykırı davranılarak işlenmesi halinde onbin Türk Lirasından yirmibeşbin Türk Lirasına kadar idari para cezasına hükmolunur.",
  "6136 Ateşli Silahlar m.15": "Bu Kanun hükümlerine aykırı olarak 4 üncü maddede yazılı olan bıçak veya diğer aletleri veya benzerlerini satanlar, satmaya aracılık edenler, satın alanlar, taşıyanlar veya bulunduranlar hakkında altı aydan bir yıla kadar hapis ve yirmibeş günden az olmamak üzere adlî para cezasına hükmolunur. Bu madde kapsamına giren bıçak veya diğer aletlerin veya benzerlerinin sayı veya nitelik bakımından vahim olması halinde yukarıdaki fıkraya göre hükmolunacak cezalar yarıdan bir katına kadar artırılır. (...) (Bu Kanunun 4 üncü maddesinin üçüncü fıkrasında yazılı olan yivli ve yivsiz silahlarla bıçak ve diğer aletleri, hal ve şartlara göre sırf saldırıda kullanmak amacıyla taşıyanlar, üç aya kadar hapis veya adlî para cezası ile cezalandırılır.)\n\nA) Duruşmalarda, mahkeme salonlarında, hastanelerin psikiyatri bölümlerinde, akıl hastanelerinde, ceza ve tutukevleri ile her türlü ıslah ve infaz kurumlarında veya bunların eklentilerinde, B) Öğrencilerin toplu olarak oturdukları yurtlarda, eğitim ve öğretim kurumlarında, siyasi partilerin açık hava ve kapalı yer toplantılarında, izinli veya izinsiz yapılan toplantı ve gösteri yürüyüşlerinde, sendikalarda, derneklerde (...), her türlü spor karşılaşma veya yarışmalarının yapıldığı yerlerde, (...) grev ve lokavt yapılmakta olan iş yerlerinde, C) Türkiye Büyük Millet Meclisi ana binaları ile Meclis Başkanlığınca belirlenen yerlerde, Ateşli silahlar taşınamaz. Yukarıda sayılan yerlerde bu Kanuna aykırı olarak ateşli silahları (...) taşıyan veya bulunduranlar hakkında ilgili kanunlarda belli edilen cezaların iki katı hükmolunur. (A) ve (B) bentlerinde sayılan yerlerde 7 nci maddenin 1, 2, 3 ve 4 numaralı bentlerinde belirtilen kişiler ile bu yerlerin güvenliği için görevli bulunan polis ve jandarma personeli, (C) bendinde sayılan yerlerde ise yalnız bu yerlerin güvenliği ile görevli bulunan polis, jandarma ve Türkiye Büyük Millet Meclisi Muhafız Taburu personeli silahlarını taşıyabilirler. (A), (B) ve (C) bentlerinde sayılan yerlere silahla giren veya buralarda silah taşıyan kişiler, fiilleri daha ağır cezayı gerektiren başka bir suç oluşturmadığı takdirde, elli günden az olmamak üzere adlî para cezası ile cezalandırılır. Ayrıca, bu kişilerin silah ruhsatları bulundurmaya çevrilir. (...)\n\nA) Duruşmalarda, mahkeme salonlarında, hastanelerin psikiyatri bölümlerinde, akıl hastanelerinde, ceza ve tutukevleri ile her türlü ıslah ve infaz kurumlarında veya bunların eklentilerinde, B) Öğrencilerin toplu olarak oturdukları yurtlarda, eğitim ve öğretim kurumlarında, siyasi partilerin açık hava ve kapalı yer toplantılarında, izinli veya izinsiz yapılan toplantı ve gösteri yürüyüşlerinde, sendikalarda, derneklerde (...), her türlü spor karşılaşma veya yarışmalarının yapıldığı yerlerde, (...) grev ve lokavt yapılmakta olan iş yerlerinde, C) Türkiye Büyük Millet Meclisi ana binaları ile Meclis Başkanlığınca belirlenen yerlerde, Ateşli silahlar taşınamaz. Yukarıda sayılan yerlerde bu Kanuna aykırı olarak ateşli silahları (...) taşıyan veya bulunduranlar hakkında ilgili kanunlarda belli edilen cezaların iki katı hükmolunur. (A) ve (B) bentlerinde sayılan yerlerde 7 nci maddenin 1, 2, 3 ve 4 numaralı bentlerinde belirtilen kişiler ile bu yerlerin güvenliği için görevli bulunan polis ve jandarma personeli, (C) bendinde sayılan yerlerde ise yalnız bu yerlerin güvenliği ile görevli bulunan polis, jandarma ve Türkiye Büyük Millet Meclisi Muhafız Taburu personeli silahlarını taşıyabilirler. (A), (B) ve (C) bentlerinde sayılan yerlere silahla giren veya buralarda silah taşıyan kişiler, fiilleri daha ağır cezayı gerektiren başka bir suç oluşturmadığı takdirde, elli günden az olmamak üzere adlî para cezası ile cezalandırılır. Ayrıca, bu kişilerin silah ruhsatları bulundurmaya çevrilir. (...) beş yıllık süre geçmediği takdirde, bu kişilere taşıma ruhsatı verilmez.\n\nKara Avcılığı Kanunu esaslarına göre izin alıp turist olarak avcılık yapmak ya da Gençlik ve Spor Bakanlığınca tertip olunacak atıcılık yarışmalarına katılmak üzere yurda gelen yabancılar beraberlerinde getirdikleri miktarı yönetmelikte belirtilen yivli ve yivsiz tüfekler ile nişan tüfek ve tabancalarını ve bunların aksamı ile mermilerini gümrük makamlarına beyan etmek ve giriş kapısı emniyet makamlarından izin almak koşuluyla geçici olarak yurda sokabilirler. Antlaşmalarla yurdumuza görevli olarak gelen yabancılar ile bilimsel araştırmalar yapmak amacıyla gelen kişiler de beraberlerinde getirecekleri yivli veya yivsiz tüfekler ve aksamı ile mermilerini İçişleri Bakanlığı Emniyet Genel Müdürlüğünden izin almak ve gümrük makamlarına beyan etmek şartıyla yurda sokabilirler. (...) yurda sokulmasına izin verilen silah, silah aksamı ve mermileri ilgili kişilerin pasaportuna kaydolunur. Bu kayıt silah, aksamı ve mermileri için taşıma izin vesikası yerine geçer. (...) sarfedilmeyen mermilerin ülkemiz terkedilirken yolcu beraberinde yurt dışına çıkarılması zorunludur.",
  "6136 Ateşli Silahlar m.4": "Ülke içinde kama, hançer, saldırma, şişli baston, sustalı çakı, pala, kılıç, kasatura, süngü, sivri uçlu ve oluklu bıçaklar, topuz, topuzlu kamçı, boğma teli veya zinciri, muşta ile salt saldırı ve savunmada kullanılmak üzere özel nitelikteki benzeri aletlerin yapımı yasaktır. Bunlardan bir sanat veya mesleğin icrası için kullanılması zorunlu bulunanların yapımına İçişleri Bakanlığınca yapılacak bir yönetmelikte belirlenen kurallara göre izin verilir. (...) Yalnız sporda kullanılan yivli ateşsiz silahlar ve mermileri ile yivsiz tüfekler ve mermilerinin, ev gereçlerinden olan veya tababet, sanayi, tarım, spor için kullanılan aletlerle bir meslek veya sanatın icrası için gerekli bıçak, şiş, raspa ve benzerlerinin kullanılması bu Kanun hükümlerine tabi değildir.",
  "6136 Ateşli Silahlar m.5": "Yurda sokulması ve yapımı yasaklanan ve 4 ncü maddenin 1 nci fıkrası kapsamına giren bıçak ve aletlerin satılması, satınalınması, taşınması ve bulundurulması yasaktır. Bir sanat veya mesleğin icrası için kullanılmasına 4 ncü maddeye göre izin verilen bıçaklar bu yasağın dışındadırlar.",
  "6284 Ailenin Korunması m.1": "MADDE 1 – (1) Bu Kanunun amacı; şiddete uğrayan veya şiddete uğrama tehlikesi bulunan kadınların, çocukların, aile bireylerinin ve tek taraflı ısrarlı takip mağduru olan kişilerin korunması ve bu kişilere yönelik şiddetin önlenmesi amacıyla alınacak tedbirlere ilişkin usul ve esasları düzenlemektir. (...) MADDE 2 – (1) Bu Kanunda yer alan; a) Bakanlık: Aile ve Sosyal Politikalar Bakanlığını, c) Hâkim: Aile mahkemesi hâkimini, (...) d) Şiddet: Kişinin, fiziksel, cinsel, psikolojik veya ekonomik açıdan zarar görmesiyle veya acı çekmesiyle sonuçlanan veya sonuçlanması muhtemel hareketleri, buna yönelik tehdit ve baskıyı ya da özgürlüğün keyfî engellenmesini de içeren, toplumsal, kamusal veya özel alanda meydana gelen fiziksel, cinsel, psikolojik, sözlü veya ekonomik her türlü tutum ve davranışı, (...) g) Şiddet uygulayan: Bu Kanunda şiddet olarak tanımlanan tutum ve davranışları uygulayan veya uygulama tehlikesi bulunan kişileri, ğ) Tedbir kararı: Bu Kanun kapsamında, şiddet mağdurları ve şiddet uygulayanlar hakkında hâkim, kolluk görevlileri ve mülkî amirler tarafından, istem üzerine veya resen verilecek tedbir kararlarını, ifade eder.",
  "6284 Ailenin Korunması m.13": "MADDE 13 – (1) Bu Kanun hükümlerine göre hakkında tedbir kararı verilen şiddet uygulayan, bu kararın gereklerine aykırı hareket etmesi hâlinde, fiili bir suç oluştursa bile ihlal edilen tedbirin niteliğine ve aykırılığın ağırlığına göre hâkim kararıyla üç günden on güne kadar zorlama hapsine tabi tutulur. (2) Tedbir kararının gereklerine aykırılığın her tekrarında, ihlal edilen tedbirin niteliğine ve aykırılığın ağırlığına göre zorlama hapsinin süresi onbeş günden otuz güne kadardır. Ancak zorlama hapsinin toplam süresi altı ayı geçemez. (3) Zorlama hapsine ilişkin kararlar, Cumhuriyet başsavcılığınca yerine getirilir. Bu kararlar Bakanlığın ilgili il ve ilçe müdürlüklerine bildirilir.",
  "6284 Ailenin Korunması m.3": "MADDE 3 – (1) Bu Kanun kapsamında korunan kişilerle ilgili olarak aşağıdaki tedbirlerden birine, birkaçına veya uygun görülecek benzer tedbirlere mülkî amir tarafından karar verilebilir: a) Kendisine ve gerekiyorsa beraberindeki çocuklara, bulunduğu yerde veya başka bir yerde uygun barınma yeri sağlanması. b) Diğer kanunlar kapsamında yapılacak yardımlar saklı kalmak üzere, geçici maddi yardım yapılması. c) Psikolojik, meslekî, hukukî ve sosyal bakımdan rehberlik ve danışmanlık hizmeti verilmesi. ç) Hayatî tehlikesinin bulunması hâlinde, ilgilinin talebi üzerine veya resen geçici koruma altına alınması. d) Gerekli olması hâlinde, korunan kişinin çocukları varsa çalışma yaşamına katılımını desteklemek üzere dört ay, kişinin çalışması hâlinde ise iki aylık süre ile sınırlı olmak kaydıyla, on altı yaşından büyükler için her yıl belirlenen aylık net asgari ücret tutarının yarısını geçmemek ve belgelendirilmek kaydıyla Bakanlık bütçesinin ilgili tertibinden karşılanmak suretiyle kreş imkânının sağlanması. (2) Gecikmesinde sakınca bulunan hâllerde birinci fıkranın (a) ve (ç) bentlerinde yer alan tedbirler, ilgili kolluk amirlerince de alınabilir. Kolluk amiri evrakı en geç kararın alındığı tarihi takip eden ilk işgünü içinde mülkî amirin onayına sunar. Mülkî amir tarafından kırksekiz saat içinde onaylanmayan tedbirler kendiliğinden kalkar.",
  "6284 Ailenin Korunması m.4": "MADDE 4 – (1) Bu Kanun kapsamında korunan kişilerle ilgili olarak aşağıdaki koruyucu tedbirlerden birine, birkaçına veya uygun görülecek benzer tedbirlere hâkim tarafından karar verilebilir: a) İşyerinin değiştirilmesi. b) Kişinin evli olması hâlinde müşterek yerleşim yerinden ayrı yerleşim yeri belirlenmesi. c) 22/11/2001 tarihli ve 4721 sayılı Türk Medenî Kanunundaki şartların varlığı hâlinde ve korunan kişinin talebi üzerine tapu kütüğüne aile konutu şerhi konulması. ç) Korunan kişi bakımından hayatî tehlikenin bulunması ve bu tehlikenin önlenmesi için diğer tedbirlerin yeterli olmayacağının anlaşılması hâlinde ve ilgilinin aydınlatılmış rızasına dayalı olarak 27/12/2007 tarihli ve 5726 sayılı Tanık Koruma Kanunu hükümlerine göre kimlik ve ilgili diğer bilgi ve belgelerinin değiştirilmesi.",
  "6284 Ailenin Korunması m.5": "MADDE 5 – (1) Şiddet uygulayanlarla ilgili olarak aşağıdaki önleyici tedbirlerden birine, birkaçına veya uygun görülecek benzer tedbirlere hâkim tarafından karar verilebilir: a) Şiddet mağduruna yönelik olarak şiddet tehdidi, hakaret, aşağılama veya küçük düşürmeyi içeren söz ve davranışlarda bulunmaması. b) Müşterek konuttan veya bulunduğu yerden derhâl uzaklaştırılması ve müşterek konutun korunan kişiye tahsis edilmesi. c) Korunan kişilere, bu kişilerin bulundukları konuta, okula ve işyerine yaklaşmaması. ç) Çocuklarla ilgili daha önce verilmiş bir kişisel ilişki kurma kararı varsa, kişisel ilişkinin refakatçi eşliğinde yapılması, kişisel ilişkinin sınırlanması ya da tümüyle kaldırılması. d) Gerekli görülmesi hâlinde korunan kişinin, şiddete uğramamış olsa bile yakınlarına, tanıklarına ve kişisel ilişki kurulmasına ilişkin hâller saklı kalmak üzere çocuklarına yaklaşmaması. e) Korunan kişinin şahsi eşyalarına ve ev eşyalarına zarar vermemesi. f) Korunan kişiyi iletişim araçlarıyla veya sair surette rahatsız etmemesi. g) Bulundurulması veya taşınmasına kanunen izin verilen silahları kolluğa teslim etmesi. ğ) Silah taşıması zorunlu olan bir kamu görevi ifa etse bile bu görevi nedeniyle zimmetinde bulunan silahı kurumuna teslim etmesi. h) Korunan kişilerin bulundukları yerlerde alkol ya da uyuşturucu veya uyarıcı madde kullanmaması ya da bu maddelerin etkisinde iken korunan kişilere ve bunların bulundukları yerlere yaklaşmaması, bağımlılığının olması hâlinde, hastaneye yatmak dâhil, muayene ve tedavisinin sağlanması. ı) Bir sağlık kuruluşuna muayene veya tedavi için başvurması ve tedavisinin sağlanması. (2) Gecikmesinde sakınca bulunan hâllerde birinci fıkranın (a), (b), (c) ve (d) bentlerinde yer alan tedbirler, ilgili kolluk amirlerince de alınabilir. Kolluk amiri evrakı en geç kararın alındığı tarihi takip eden ilk işgünü içinde hâkimin onayına sunar. Hâkim tarafından yirmidört saat içinde onaylanmayan tedbirler kendiliğinden kalkar.",
  "6284 Ailenin Korunması m.8": "MADDE 8 – (1) Tedbir kararı, ilgilinin talebi, Bakanlık veya kolluk görevlileri ya da Cumhuriyet savcısının başvurusu üzerine verilir. Tedbir kararları en çabuk ve en kolay ulaşılabilecek yer hâkiminden, mülkî amirden ya da kolluk biriminden talep edilebilir. (2) Tedbir kararı ilk defasında en çok altı ay için verilebilir. Ancak şiddet veya şiddet uygulanma tehlikesinin devam edeceğinin anlaşıldığı hâllerde, resen, korunan kişinin ya da Bakanlık veya kolluk görevlilerinin talebi üzerine tedbirlerin süresinin veya şeklinin değiştirilmesine, bu tedbirlerin kaldırılmasına veya aynen devam etmesine karar verilebilir. (3) Koruyucu tedbir kararı verilebilmesi için, şiddetin uygulandığı hususunda delil veya belge aranmaz. Önleyici tedbir kararı, geciktirilmeksizin verilir. (...) (4) Tedbir kararı, korunan kişiye ve şiddet uygulayana tefhim veya tebliğ edilir. (...) (5) Tedbir kararının tefhim ve tebliğ işlemlerinde, tedbir kararına aykırılık hâlinde şiddet uygulayan hakkında zorlama hapsinin uygulanacağı ihtarı yapılır. (6) Gerekli bulunması hâlinde, tedbir kararı ile birlikte talep üzerine veya resen, korunan kişi ve diğer aile bireylerinin kimlik bilgileri veya kimliğini ortaya çıkarabilecek bilgileri ve adresleri ile korumanın etkinliği bakımından önem taşıyan diğer bilgileri, tüm resmi kayıtlarda gizli tutulur. (...)",
  "6284 Ailenin Korunması m.9": "MADDE 9 – (1) Bu Kanun hükümlerine göre verilen kararlara karşı tefhim veya tebliğ tarihinden itibaren iki hafta içinde ilgililer tarafından aile mahkemesine itiraz edilebilir. (2) Hâkim tarafından verilen tedbir kararlarına itiraz üzerine dosya, o yerde aile mahkemesinin birden fazla dairesinin bulunması hâlinde, numara olarak kendisini izleyen daireye, son numaralı daire için birinci daireye, o yerde aile mahkemesinin tek dairesi bulunması hâlinde asliye hukuk mahkemesine, aile mahkemesi hâkimi ile asliye hukuk mahkemesi hâkiminin aynı hâkim olması hâlinde ise en yakın asliye hukuk mahkemesine gecikmeksizin gönderilir. (3) İtiraz mercii kararını bir hafta içinde verir. İtiraz üzerine verilen kararlar kesindir.",
  "6284 Uyg. Yön m.12": "MADDE 12 –(1) Kanun kapsamında korunan kişilerle ilgili olarak hâkim tarafından, (...) şiddetin uygulandığı hususunda delil veya belge aranmaksızın aşağıdaki koruyucu tedbirlerden birine, birkaçına veya olayın özelliğine göre mülki amir tarafından alınabilecek tedbirler de dâhil olmak üzere, uygun görülecek benzer tedbirlere karar verilebilir: a) İş yerinin değiştirilmesi. b) Kişinin evli olması hâlinde müşterek yerleşim yerinden ayrı yerleşim yeri belirlenmesi. c) (...) korunan kişinin talebi üzerine tapu kütüğüne aile konutu şerhi konulması. ç) (...) hayatî tehlikenin bulunması ve (...) diğer tedbirlerin yeterli olmayacağının anlaşılması hâlinde ve ilgilinin aydınlatılmış rızasına dayalı olarak (...) Tanık Koruma Kanununa göre kimlik ve ilgili diğer bilgi ve belgelerinin değiştirilmesi.",
  "6284 Uyg. Yön m.17": "MADDE 17 –(1) Hâkim tarafından şiddet uygulayanlarla ilgili olarak aşağıdaki önleyici tedbirlerden birine, birkaçına veya uygun görülecek benzer tedbirlere karar verilebilir: a) Şiddet mağduruna yönelik olarak şiddet tehdidi, hakaret, aşağılama veya küçük düşürmeyi içeren söz ve davranışlarda bulunmaması. b) Müşterek konuttan veya bulunduğu yerden derhâl uzaklaştırılması ve müşterek konutun korunan kişiye tahsis edilmesi. c) Korunan kişilere, bu kişilerin bulundukları konuta, okula ve işyerine yaklaşmaması. ç) Çocuklarla ilgili daha önce verilmiş bir kişisel ilişki kurma kararı varsa, kişisel ilişkinin refakatçi eşliğinde kurulması, kişisel ilişkinin sınırlanması ya da tümüyle kaldırılması. d) Gerekli görülmesi hâlinde korunan kişinin, şiddete uğramamış olsa bile yakınlarına, tanıklarına ve (...) çocuklarına yaklaşmaması. e) Korunan kişinin şahsi eşyalarına ve ev eşyalarına zarar vermemesi. f) Korunan kişiyi iletişim araçlarıyla veya sair surette rahatsız etmemesi. g) Bulundurulması veya taşınmasına kanunen izin verilen silahları kolluğa teslim etmesi. ğ) Silah taşıması zorunlu olan bir kamu görevi ifa etse bile bu görevi nedeniyle zimmetinde bulunan silahı kurumuna teslim etmesi. h) Korunan kişilerin bulundukları yerlerde alkol ya da uyuşturucu veya uyarıcı madde kullanmaması (...) bağımlılığının olması hâlinde, hastaneye yatmak dâhil, muayene ve tedavisinin sağlanması. ı) Bir sağlık kuruluşuna muayene veya tedavi için başvurması ve tedavisinin sağlanması. (3) Şiddet uygulayan, aynı zamanda ailenin geçimini sağlayan (...) kişi ise hâkim, (...) talep edilmese dahi tedbir nafakasına hükmedebilir. Tedbir nafakasının tahsili 43 üncü maddeye göre yapılır.",
  "6284 Uyg. Yön m.29": "MADDE 29 – (1) Mülkî amir tarafından alınabilecek barınma yeri sağlanmasına ve geçici koruma altına alınmasına ilişkin tedbirler, gecikmesinde sakınca bulunan hâllerde ilgili kolluk amirince de alınabilir. Kolluk amiri, evrakı en geç tedbirin alındığı tarihi takip eden ilk işgünü içinde mülkî amirin onayına sunar. Mülkî amir tarafından kırk sekiz saat içinde onaylanmayan tedbirler kendiliğinden kalkar. (2) 18, 19, 20 ve 22 nci maddelerde belirtilen ve hâkim tarafından karar altına alınabilecek önleyici tedbirler, gecikmesinde sakınca bulunan hâllerde ilgili kolluk amirince alınabilir. Kolluk amiri evrakı en geç tedbirin alındığı tarihi takip eden ilk işgünü içinde hâkimin onayına sunar. Hâkim tarafından yirmi dört saat içinde onaylanmayan tedbirler kendiliğinden kalkar. (3) Tatil günleri sürenin hesabına dâhildir. (...)",
  "6284 Uyg. Yön m.3": "m) Şiddet: Kişinin, fiziksel, cinsel, psikolojik veya ekonomik açıdan zarar görmesiyle veya acı çekmesiyle sonuçlanan veya sonuçlanması muhtemel hareketleri, buna yönelik tehdit ve baskıyı ya da özgürlüğün keyfî engellenmesini de içeren, (...) her türlü tutum ve davranışı, n) Şiddet mağduru: (...) uyruğuna bakılmaksızın, Kanunda şiddet olarak tanımlanan tutum ve davranışlara doğrudan veya dolaylı olarak maruz kalan ya da kalma tehlikesi bulunan kişiyi (...), j) Korunan kişi: Tedbir kararı kapsamında korunan şiddet mağdurunu ve varsa beraberindeki çocukları, aile bireylerini ve tek taraflı ısrarlı takip mağdurunu, ş) Tek taraflı ısrarlı takip: Aralarında aile bağı veya ilişki bulunup bulunmadığına bakılmaksızın, şiddet uygulayanın, şiddet mağduruna yönelik olarak, güvenliğinden endişe edecek şekilde (...) korku ve çaresizlik duygularına sebep olacak biçimde, içeriği ne olursa olsun fiili, sözlü, yazılı olarak ya da her türlü iletişim aracını kullanarak (...) her türlü tutum ve davranışı, ifade eder.\n\ne) Hâkim: Aile mahkemesi hâkimini, h) Kolluk: Polis, jandarma ve sahil güvenlik birimlerini, o) Şiddet Önleme ve İzleme Merkezi (ŞÖNİM): Şiddetin önlenmesi ile koruyucu ve önleyici tedbirlerin etkin bir biçimde uygulanmasına yönelik (...) danışmanlık, rehberlik, yönlendirme ve izleme hizmetlerinin verildiği, (...) tercihen kadın personelin istihdam edildiği, çalışmaların yedi gün yirmidört saat esasına göre yürütüldüğü merkezi, c) Gecikmesinde sakınca bulunan hal: Kolluk tarafından yapılacak tahkikat ve risk değerlendirilmesi sonucunda, derhal işlem yapılmadığı takdirde, şiddet eyleminin önlenememesi, kişinin can güvenliği(nin) (...) tehlikeye girmesi, (...) ve resen veya ilgilinin talebi üzerine mülki amirden ya da hâkimden karar almak için yeterince vakit bulunamaması halini, ifade eder.",
  "6284 Uyg. Yön m.30": "MADDE 30 – (1) Tedbir kararı ilgilinin talebi, müdürlük, ŞÖNİM veya kolluk görevlileri ya da Cumhuriyet savcısının başvurusu üzerine verilir. Tedbir kararları en çabuk ve en kolay ulaşılabilecek yer hâkiminden, mülkî amirden ya da kolluktan talep edilebilir. (2) Tedbir kararı ilk defasında en çok altı ay için verilebilir. Ancak şiddet veya şiddet uygulanma tehlikesinin devam edeceğinin anlaşılması hâlinde, (...) tedbirlerin süresinin veya şeklinin değiştirilmesine ya da aynen devam etmesine karar verilebilir. (3) Koruyucu tedbir kararı verilebilmesi için, şiddetin uygulandığı hususunda delil veya belge aranmaz. (...)",
  "6284 Uyg. Yön m.32": "MADDE 32 –(1) Gerekli bulunması hâlinde, tedbir kararı ile birlikte talep üzerine veya resen, korunan kişi ve diğer aile bireylerinin kimlik bilgileri veya kimliğini ortaya çıkarabilecek bilgileri ve adresleri (...) tüm resmi kayıtlarda gizli tutulur. Bu bilgileri hukuka aykırı olarak başkasına veren, ifşa eden veya açıklayan kişi hakkında (...) Türk Ceza Kanununun ilgili hükümleri uygulanır. (...) (5) Korunan kişi hakkında gizlilik kararı verilmesi halinde, karar ŞÖNİM müdürü aracılığıyla (...) nüfus müdürlüklerinde ilgilinin nüfus kaydına işlenir. (...) Gizlilik kararı verilen kayıtlar sadece elektronik ortamda tutulur. (6) Korunan kişinin nüfus kaydına işlenen gizlilik şerhi, tedbir kararının süresinin sona ermesini takip eden onbeşinci gün MERNİS veri tabanından silinir. (...)",
  "6284 Uyg. Yön m.34": "MADDE 33 –(1) (...) mülki amir tarafından verilen koruyucu tedbir kararına karşı, tefhim veya tebliğ tarihinden itibaren iki hafta içinde, ilgililer tarafından aile mahkemesine itiraz edilebilir. (...) (3) İtiraz hakkında duruşma yapılmaksızın karar verilir. (...) Karar bir hafta içinde verilir. İtiraz üzerine verilen karar kesindir. MADDE 34 –(1) (...) hâkim tarafından verilen koruyucu veya önleyici tedbir kararları ile (...) zorlama hapsi kararlarına karşı, tefhim veya tebliğ tarihinden itibaren iki hafta içinde ilgililer tarafından aile mahkemesine itiraz edilebilir. (...) (7) Karar bir hafta içinde verilir. İtiraz üzerine verilen karar kesindir.",
  "6284 Uyg. Yön m.37": "MADDE 37 –(1) Hâkim, tedbir kararlarının uygulanmasında teknik araç ve yöntemler kullanılmasına karar verebilir. Ancak, teknik araçlar kullanılmak suretiyle, kişilerin ses ve görüntü kaydı alınamaz, kişiler dinlenemez ve izlenemez.",
  "6284 Uyg. Yön m.38": "MADDE 38 –(1) Tedbir kararlarının ihlal edildiğinin (...) aile mahkemesince tespit edilmesi halinde (...) resen zorlama hapsine ilişkin karar verilebilir. (...) (3) Zorlama hapsine karar verilebilmesi için şiddet uygulayana, (...) ihtarın da yer aldığı tedbir kararının tefhim veya tebliğ edilmiş olması gerekir. (...) (5) (...) hakkında tedbir kararlarına aykırı hareket eden şiddet uygulayana, fiili bir suç oluştursa bile, ihlal edilen tedbirin niteliğine ve aykırılığın ağırlığına göre hâkim tarafından üç günden on güne kadar zorlama hapsine tâbi tutulmasına karar verilir. (6) Tedbir kararının gereklerine aykırılığın her tekrarında, (...) zorlama hapsinin süresi onbeş günden otuz güne kadardır. Ancak zorlama hapsinin toplam süresi altı ayı geçemez. (7) Zorlama hapsi kararları tekerrüre esas olmaz, koşullu salıverilme hükümleri uygulanmaz ve adli sicil kayıtlarına işlenmez.",
  "6284 Uyg. Yön m.39": "MADDE 39 –(1) Bakanlık, (...) ŞÖNİM'i kurar. MADDE 40 –(1) Kanun hükümlerinin yerine getirilmesinde kurumlararası ve sivil toplum kuruluşları ile koordinasyon Bakanlık tarafından gerçekleştirilir. (...) (3) (...) Materyaller, (...) televizyon kuruluşları ve radyolar tarafından ayda en az doksan dakika yayınlanır. (...) MADDE 41 –(1) Kanunun etkin bir biçimde uygulanması amacıyla tüm kamu kurum ve kuruluşları ile kamu kurumu niteliğindeki meslek kuruluşları, personel ve üyelerinin (...) eğitim programlarına katılmasını sağlar. (2) İlköğretim ve ortaöğretim müfredatına (...) dersler konulur. (3) (...) öğrencilere mezun oldukları tarihte (...) bir sertifika verilir.",
  "6284 Uyg. Yön m.4": "MADDE 4 –(1) Kişinin, şiddete uğraması veya şiddete uğrama tehlikesi altında bulunması halinde herkes durumu yazılı, sözlü veya başka bir suretle ilgili makam ve mercilere ihbar edebilir. Şiddet veya şiddete uğrama tehlikesinden haberdar olan kamu kurum ve kuruluşları ile kamu kurumu niteliğindeki meslek kuruluşları ise durumu derhal, şikâyet mercilerine bildirmek zorundadır. (2) Şiddet mağduru, (...) durumu şikâyet mercilerine (...) bildirebilir. (3) Şikâyet mercileri Kanun kapsamındaki görevlerini gecikmeksizin yerine getirmekle yükümlüdür. (4) Müdürlük veya ŞÖNİM'e yapılan şikâyet ve ihbarlar, bunlar tarafından olayın özelliğine göre, kolluğa, mülki amire, Cumhuriyet başsavcılığına veya hâkime gecikmeksizin bildirilir. (5) Sözlü yapılan şikâyet ve ihbarlar derhal tutanağa geçirilir.",
  "6284 Uyg. Yön m.42": "MADDE 42 –(1) Geçici maddi yardımlar için yapılan ödemelerin tahsili için, ödeme tutarı (...) tebliğ tarihinden itibaren bir ay içinde ödenmesi hususu şiddet uygulayana tebliğ edilir. Ödemenin süresinde yapılmaması halinde bu tutar, 6183 sayılı (...) Kanun hükümlerine göre (...) takip ve tahsil edilir. MADDE 43 –(1) (...) nafakaya karar verilmesi hâlinde, kararın bir örneği, resen (...) icra müdürlüğüne gönderilir. (...) (4) (...) Ayrıca harç ve benzeri hiçbir ad altında masraf alınmaz. MADDE 44 –(1) Korunan kişinin sağlık giderleri, genel sağlık sigortası kapsamında karşılanır. (...) MADDE 45 –(1) Kanun kapsamındaki başvurular ile verilen kararların icra ve infazı için yapılan işlemlerden yargılama giderleri, harç, posta gideri ve benzeri hiçbir ad altında masraf alınmaz. (2) Kanunun 17 nci maddesi uyarınca yapılan ödemeler, gelir vergisi ile veraset ve intikal vergisinden (...) müstesnadır. MADDE 46 –(1) Bakanlık, gerekli görmesi hâlinde (...) açılan (...) idarî, cezaî, hukukî her tür davaya ve çekişmesiz yargıya müdahil olarak katılabilir.",
  "6284 Uyg. Yön m.5": "MADDE 5 –(1) Kolluk, kendisine yapılan ihbar veya şikâyet üzerine genel hükümler doğrultusunda gerekli işlemleri yapar. Gecikmesinde sakınca bulunan hallerde Kanun kapsamında almış olduğu koruyucu ve önleyici tedbirleri onaylanmak üzere tedbirin niteliğine göre mülki amire veya hâkime sunar. Kolluk, kendisine intikal eden her olay hakkında gecikmeksizin en seri vasıtalarla ŞÖNİM'e bilgi verir. (2) Cumhuriyet başsavcılığı, yapılan ihbar ve şikâyet üzerine evrakın bir örneğini ivedilikle olayın niteliğine göre uygulanabilecek olan koruyucu veya önleyici tedbir hakkında karar verilmek üzere hâkime veya mülki amire gönderir. (3) Mülki amire yapılan ihbar veya şikâyet üzerine (...) koruyucu tedbirlerden (...) karar verilebilir. (...) (4) Hâkim veya mülki amir tarafından verilen kararlar ivedilikle ŞÖNİM'e bildirilir.",
  "6284 Uyg. Yön m.6": "MADDE 6 – (1) Kanun kapsamında korunan kişilerle ilgili olarak aşağıdaki tedbirlerden birine, birkaçına veya uygun görülecek benzer tedbirlere delil veya belge aranmaksızın mülkî amir tarafından ilgilinin talebi, Bakanlık veya kolluk görevlilerinin başvurusu üzerine ya da resen karar verilebilir: a) (...) uygun barınma yeri sağlanması, b) (...) geçici maddi yardım yapılması, c) Psikolojik, meslekî, hukukî ve sosyal bakımdan rehberlik ve danışmanlık hizmeti verilmesi, ç) Hayatî tehlikesinin bulunması hâlinde, ilgilinin talebi üzerine veya resen geçici koruma altına alınması, d) Gerekli olması hâlinde, (...) kreş imkânının sağlanması.",
  "6284 Uyg. Yön m.7": "MADDE 7 –(1) Hakkında barınma yeri sağlanmasına karar verilen kişiler, Bakanlığa ait veya Bakanlığın gözetim ve denetimi altında bulunan yerlerde; (...) güvenli nakli sağlanıncaya kadar geçici olarak barındırılır. (...) (5) Mülki amirin veya kolluk amirinin kararı ile kamu kurum ve kuruluşlarına ait barınma yerlerine getirilen şiddet mağduru, başka herhangi bir karar veya onay aranmaksızın barınma yerine derhal kabul edilir. (...) MADDE 9 –(1) Korunan kişiye, (...) psikolojik destek sağlamak üzere ilgili kamu kurum ve kuruluşları ile işbirliği içerisinde gerekli hizmetler verilir. (2) Korunan kişinin hukuki rehberliğe ihtiyacı olması halinde (...) gerekli destek ve danışmanlık hizmeti verilir. (3) Bu hizmetlerin yerine getirilmesinde koordinasyon ŞÖNİM tarafından sağlanır.",
  "Atatürk Al. Suçlar m.1": "Atatürk'ün hatırasına alenen hakaret eden veya söven kimse bir yıldan üç yıla kadar hapis cezası ile cezalandırılır. Atatürk'ü temsil eden heykel, büst ve abideleri veyahut Atatürk'ün kabrini tahrip eden, kıran, bozan veya kirleten kimseye bir yıldan beş yıla kadar ağır hapis cezası verilir. Yukarki fıkralarda yazılı suçları işlemeye başkalarını teşvik eden kimse asıl fail gibi cezalandırılır.",
  "Atatürk Al. Suçlar m.2": "Birinci maddede yazılı suçlar; iki veya daha fazla kimseler tarafından toplu olarak veya umumi veya umuma açık mahallerde yahut basın vasıtasiyle işlenirse hükmolunacak ceza yarı nispetinde artırılır. Birinci maddenin ikinci fıkrasında yazılı suçlar zor kullanılarak işlenir veya bu suretle işlenmesine teşebbüs olunursa verilecek ceza bir misli artırılır.",
  "Atatürk Al. Suçlar m.3": "Bu kanunda yazılı suçlardan dolayı Cumhuriyet savcılıklarınca re'sen takibat yapılır.",
  "Bilgi Edinme Yön m.10": "Madde 10 - Bilgi edinme başvurusu, kişinin kimliğinin ve imzasının veya yazının kimden neşet ettiğinin tespitine yarayacak başka bilgilerin yasal olarak belirlenebilir olması kaydıyla elektronik ortamda veya diğer iletişim araçlarıyla da yapılabilir. Gerçek kişiler tarafından elektronik posta yoluyla yapılacak başvurular, başvuru sahibinin adı ve soyadı, oturma yeri veya iş adresine ilave olarak kimlik doğrulama amacıyla kullanılacak T.C. kimlik numarası belirtilmek suretiyle, (...) EK-1'de yer alan form doldurulmak suretiyle yapılır. Tüzel kişiler tarafından elektronik posta yoluyla yapılacak başvurular, tüzel kişinin unvanı ve adresi ile yetkili kişinin T.C. kimlik numarası belirtilmek suretiyle ve yetki belgesiyle birlikte, (...) EK-2'de yer alan form doldurulmak suretiyle yapılır. (...) Gerçek veya tüzel kişiler tarafından, 5070 sayılı Elektronik İmza Kanunu gereğince elektronik imza kullanılarak gönderilen başvurularda, T.C. kimlik numarası aranmaz.\n\nElektronik posta yoluyla yapılacak başvurularda, başvuru formunun kurum veya kuruluşun bilgi edinme biriminin elektronik posta adresine ulaştığı tarih, başvuru tarihidir. Elektronik posta yoluyla yapılacak başvurular için, kurum ve kuruluşların bilgi edinme birimleri, bu amaçla kurumsal bir elektronik posta adresi oluşturur ve internet sayfalarında yayımlar. (...) Başvuru dilekçeleri faks yoluyla da, kurum ve kuruluşlara gönderilebilir. Ancak faks yoluyla yapılacak başvurularda ayrıca, gerçek kişiler ile tüzel kişiliği temsile yetkili kişilerin T.C. kimlik numaraları belirtilir. (...) Faks yoluyla gelen başvuru dilekçesinin kurum ve kuruluşların bilgi edinme birimlerine ulaştığı tarih, başvuru tarihidir.",
  "Bilgi Edinme Yön m.13": "Madde 13 - Kurum ve kuruluşlarca yayımlanmış veya kitap, broşür, ilan ve benzeri yollarla kamuya açıklanmış bilgi veya belgeler, bilgi edinme başvurusuna konu olamaz. Ancak birinci fıkrada belirtilen yollarla kamuoyuna açıklanmış veya kurum ve kuruluşlarca elektronik ortamda yayımlanmış kamunun erişimine açık bilgi veya belgelerin ne şekilde, ne zaman ve nerede yayımlandığı veya açıklandığı başvurana bildirilir.",
  "Bilgi Edinme Yön m.14": "Madde 14 - Başvuru dilekçeleri veya formları, kurum ve kuruluşların bilgi edinme birimleri tarafından kabul edilir. Bilgi edinme birimleri, başvuru dilekçeleri veya formlarının 9 uncu maddede belirtilen şekilde verilip verilmediğinin kontrolünü yaptıktan sonra bunların evrak kayıtlarını yaparak hazır bulunmaları koşuluyla başvuru sahiplerine, başvurunun tarih ve sayısını gösteren bir makbuz verir. Kurum ve kuruluşların bilgi edinme birimleri dışındaki herhangi bir birimine ulaşan başvuru dilekçeleri veya formlar, işleme konulmadan derhal bilgi edinme birimlerine gönderilir. (...) Başvuru dilekçesi veya formu kaydedildikten sonra, en geç iki iş günü içinde kurum veya kuruluşun ilgili birimlerine gönderilir. Bu yazıda; başvurunun hangi birim tarafından cevaplanacağı ve başvuru sahibine hangi tarihe kadar cevap verilmesi gerektiği belirtilir.\n\n9 uncu maddede belirtilen unsurları içermeyen başvuru dilekçeleri veya formları ile 10 uncu maddede belirtilen unsurları içermeyen elektronik posta yoluyla gönderilmiş başvuru dilekçeleri veya formları işleme konulmaz ve durum başvuru sahibine bildirilir. Gerçeğe aykırı beyanda bulunduğu sonradan anlaşılan başvuru sahiplerinin dilekçeleri veya formları, bu durumun anlaşıldığı tarihte hiç başvuru yapılmamış sayılarak işleme konulmaz. (...) Gerçeğe aykırı ad ve soyadla yapılan başvurular işleme konulmaz.",
  "Bilgi Edinme Yön m.2": "Madde 2 - Bu Yönetmelik; merkezi idare kapsamındaki kamu idareleri ile bunların bağlı, ilgili veya ilişkili kuruluşlarının, köyler hariç olmak üzere mahalli idareler ve bunların bağlı ve ilgili kuruluşları ile birlik veya şirketlerinin, T.C. Merkez Bankası ve üniversiteler de dahil olmak üzere kamu tüzel kişiliğini haiz olarak enstitü, teşebbüs, teşekkül, fon ve sair adlarla kurulmuş olan bütün kamu kurum ve kuruluşlarının ve kamu kurumu niteliğindeki meslek kuruluşlarının faaliyetlerinde uygulanır.",
  "Bilgi Edinme Yön m.3": "Madde 3 - Bu Yönetmelik, 9/10/2003 tarihli ve 4982 sayılı Bilgi Edinme Hakkı Kanununun 31 inci maddesi uyarınca hazırlanmıştır.",
  "Bilgi Edinme Yön m.4": "Madde 4 - Bu Yönetmelikte geçen; a) Kurum ve kuruluş: 2 nci maddede geçen ve kapsama dahil olan bilgi edinme başvurusu yapılacak tüm makam ve mercileri, b) Başvuru sahibi: 4982 sayılı Kanun ve bu Yönetmelik kapsamında bilgi edinme hakkını kullanarak kurum ve kuruluşlara başvuran gerçek ve tüzel kişileri, c) Bilgi: Kurum ve kuruluşların kayıtlarında yer alan 4982 sayılı Kanun kapsamındaki her türlü veriyi, d) Belge: Kurum ve kuruluşların sahip oldukları 4982 sayılı Kanun kapsamındaki yazılı, basılı veya çoğaltılmış dosya, evrak, kitap, dergi, broşür, etüt, mektup, program, talimat, kroki, plan, film, fotoğraf, teyp ve video kaseti, harita, elektronik ortamda kaydedilen her türlü bilgi, haber ve veri taşıyıcılarını, e) Bilgi veya belgeye erişim: İstenen bilgi veya belgenin niteliğine göre, kurum ve kuruluşlarca, başvuru sahibine söz konusu bilgi veya belgenin bir kopyasının verilmesini, kopya verilmesinin mümkün olmadığı hallerde, başvuru sahibinin bilgi veya belgenin aslını inceleyerek not almasına veya içeriğini görmesine veya işitmesine izin verilmesini, f) Kurul: Bilgi Edinme Değerlendirme Kurulunu, g) Kanun: 9/10/2003 tarihli ve 4982 sayılı Bilgi Edinme Hakkı Kanununu, ifade eder.",
  "Bilgi Edinme Yön m.5": "Madde 5 - Herkes, Kanun ve bu Yönetmelikte belirlenen esas ve usuller çerçevesinde bilgi edinme hakkına sahiptir. Türkiye'de ikamet eden yabancılar ile Türkiye'de faaliyette bulunan yabancı tüzel kişiler, isteyecekleri bilgi kendileriyle veya faaliyet alanlarıyla ilgili olmak kaydıyla ve karşılıklılık ilkesi çerçevesinde, Kanun ve bu Yönetmelik hükümlerinden yararlanırlar. Bu kapsamdaki başvurular Türkçe olarak yapılır. Karşılıklılık ilkesi kapsamında bulunan ülkeler Dışişleri Bakanlığınca Resmi Gazetede ilan edilir. Türkiye'nin taraf olduğu uluslararası sözleşmelerden doğan hak ve yükümlülükleri saklıdır.",
  "Disiplin m.1": "MADDE 1- (1) Bu Kanunun amacı; Emniyet Genel Müdürlüğü, Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı personeline ilişkin disiplinsizlik ve cezaları, disiplin amirlerini ve kurullarını, disiplin soruşturma usulü ile diğer ilgili hususları düzenlemektir. MADDE 2- (1) Bu Kanun; a) Emniyet Genel Müdürlüğü teşkilatında çalışan her sınıftan memurları, b) Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı teşkilatlarında görev yapan subay, astsubay, sözleşmeli subay, sözleşmeli astsubay, uzman jandarma, uzman erbaş, sözleşmeli erbaş ve sözleşmeli erler ile diğer sınıflardaki memurları, kapsar.\n\nMADDE 1- (1) Bu Kanunun amacı; Emniyet Genel Müdürlüğü, Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı personeline ilişkin disiplinsizlik ve cezaları, disiplin amirlerini ve kurullarını, disiplin soruşturma usulü ile diğer ilgili hususları düzenlemektir. MADDE 2- (1) Bu Kanun; a) Emniyet Genel Müdürlüğü teşkilatında çalışan her sınıftan memurları, b) Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı teşkilatlarında görev yapan subay, astsubay, sözleşmeli subay, sözleşmeli astsubay, uzman jandarma, uzman erbaş, sözleşmeli erbaş ve sözleşmeli erler ile diğer sınıflardaki memurları, kapsar. (2) Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı emrine verilen yükümlü erbaş ve erler hakkında 31/1/2013 tarihli ve 6413 sayılı Türk Silahlı Kuvvetleri Disiplin Kanunu hükümleri uygulanır. MADDE 3- (1) Bu Kanunun uygulanmasında; a) Amir: Kadro ve kuruluş yönünden bağlı olunan kimse ile amir olarak yetkilendirilmiş olan diğer kişileri, b) Bakan: İçişleri Bakanını, c) Bakanlık: İçişleri Bakanlığını, ç) Disiplinsizlik: Bu Kanuna göre disiplin cezası ile cezalandırılan fiilleri, d) Disiplin amiri: Bu Kanun ile disiplin cezası vermeye yetkili kılınmış ilk amiri, (...) i) Personel: (...) Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı teşkilatlarında görev yapan subay, astsubay, (...) memurları, j) Üst: Makam, rütbe veya kıdem büyüklüğünü, k) Üst disiplin amirleri: Disiplin amirinin kadro ve kuruluş yönünden bağlı bulunduğu ve disiplin cezası verilecek personelden makam, rütbe veya kıdemce büyük olan yetkili sıralı tüm amirleri, ifade eder.",
  "Disiplin m.10": "MADDE 10- (1) Amirin emrinin yapılmaması fiilinin neticesinde, Devlet ya da kişiler zarara uğratılmış ya da hizmetin gecikmesine ya da durmasına neden olunmuşsa doğan zararın derecesine ya da durumun ağırlığına göre meslekten çıkarma cezası uygulanabilir. (10) Görevin takdir ve yerine getirilmesinde müsamaha veya savsaklama fiili Devleti veya kişileri zarara uğratmış veya hizmetin gecikmesine, durmasına ya da aksamasına neden olmuşsa durumun ağırlığına ve zararın derecesine göre daha ağır cezalardan birisi verilebilir. (13) Bu Kanunda belirlenmiş ve bir disiplin cezasıyla yaptırıma bağlanmış fiillerin sahil güvenlik personelince yurtdışı liman ziyaretlerinde veya Türk karasuları dışında işlenmesi halinde, uyarma ve kınama cezası gerektiren fiillerde (...) aylıktan kesme, kısa veya uzun süreli durdurma cezası; aylıktan kesme, kısa veya uzun süreli durdurma cezası gerektiren fiillerde ise (...) meslekten çıkarma cezası verilebilir.",
  "Disiplin m.11": "MADDE 11- (1) Jandarma Genel Komutanlığının terörle mücadele harekatı kapsamındaki operasyonlarında ve Sahil Güvenlik Komutanlığının seyir halindeki gemi ve botlarında, bunların komutanları, diğer kanunlar ile verilmiş yakalama yetkisi haricinde aşağıdaki durumlardan birisi bulunduğunda veya benzer bir amaçla emri altındakileri geçici olarak kontrol altına almaya veya aldırmaya yetkilidir. a) Kendisine, başkalarına veya çevresine ya da hizmete ait bir eşyaya zarar vereceği açık bir şekilde belli olanların bu durumunun engellenmesi. b) Ciddi şekilde bozulan disiplinin yeniden tesis edilmesi. c) Sarhoşluk süresince kişinin kontrol altında tutulması. (2) Kontrol altında bulundurma, bu amaç için hazırlanacak mahallerde, Jandarma Genel Komutanlığı için operasyon komutanının uygun gördüğü mahallerde ve yirmidört saati geçmeyecek şekilde uygulanır. Tedbir süresinin oniki saati geçmesi halinde, personelin yakınlarına ve tedbiri uygulayan komutanın üstüne en kısa sürede bilgi verilir. (3) Kontrol altına alınanlarla ilgili olarak durumun gerektirdiği tedbirler, disiplin amirlerince alınır veya alınması sağlanır. Bunlar hakkında disiplin cezası uygulamasında, eyleminin karşılığı olan cezanın üst sınırı, ceza üst sınırdaysa veya cezanın üst sınırı yok ise bir üst ceza uygulanır.",
  "Disiplin m.12": "MADDE 12- (1) Aşağıda belirtilen durumlar disiplinsizliği alışkanlık haline getirme olarak kabul edilir ve personel hakkında meslekten çıkarma cezası yetkili disiplin kurullarınca verilir: a) En son alınan disiplin cezasının kesinleştiği tarihten geriye doğru son bir yıl içinde yirmi disiplin cezası puanı veya en az iki farklı disiplin amirinden toplam oniki defa veya daha fazla disiplin cezası almak. b) En son alınan disiplin cezasının kesinleştiği tarihten geriye doğru son beş yıl içinde kırk disiplin cezası puanı veya en az iki farklı disiplin amirinden toplam yirmibeş defa veya daha fazla disiplin cezası almak. (2) Aynı disiplin dosyası kapsamında birden fazla disiplin cezası verilmesi halinde en yüksek olanın puanı değerlendirmeye esas alınır.",
  "Disiplin m.13": "MADDE 13- (1) Disiplin amirinin, disiplin cezası verilecek personelden makam, rütbe veya kıdemce büyük olması ve amir konumunda bulunması gerekir. (3) Kaymakamlar ilçe, valiler il teşkilatındaki diğer disiplin amirlerine göre en üst disiplin amiridir. Valiler kaymakamlara, Bakan ise Emniyet Genel Müdürü, Jandarma Genel Komutanı ve Sahil Güvenlik Komutanı ile valilere göre bir üst disiplin amiridir. (5) Disiplin soruşturması yapma ve disiplin cezası verme görev ve yetkisi üst disiplin amirleri tarafından da kullanılabilir.",
  "Disiplin m.14": "MADDE 14- (1) Maiyetinden birinin disiplinsizlik teşkil eden bir fiilini veya mesleğe aykırı tutum ve davranışını herhangi bir şekilde öğrenen disiplin amirleri, olayın araştırılmasının gerektiğine kanaat getirirse bizzat ya da yazılı olarak görevlendireceği soruşturmacılar vasıtasıyla disiplin soruşturması yapar. (2) Disiplin soruşturmacısı olarak hakkında disiplin soruşturması yapılacak kişinin üstü konumundaki bir veya birden fazla kişi ya da Bakanlık ve/veya ilgisine göre Emniyet Genel Müdürlüğü, Jandarma Genel Komutanlığı ya da Sahil Güvenlik Komutanlığı müfettişi görevlendirilebilir. Ancak gerek görülmesi halinde, heyet başkanı hariç olmak üzere hakkında disiplin soruşturması yapılacak kişinin astı konumunda heyet üyeleri görevlendirilebilir. (...) (3) Disiplin soruşturmacıları ve heyeti, kendilerini görevlendiren disiplin amiri adına disiplin soruşturmasıyla ilgili bilgi ve belgeleri toplama, ifade alma, tanık dinleme, bilirkişi görevlendirme, keşif yapma, hâkim veya savcı kararı gerektirmeyen durumlarda kriminal inceleme yaptırma da dahil olmak üzere her türlü inceleme yapma ve ilgili makamlarla yazışma yetkisini haizdir. (...) (4) Disiplin soruşturmacısı olarak görevlendirilebileceği belirtilenler, boşanmış olsalar dahi eşleri veya ikinci dereceye kadar kan ve kayın hısımları olan personel hakkında yürütülen soruşturmalarda görevlendirilemez.",
  "Disiplin m.15": "MADDE 15- (2) Disiplin amiri olarak tayin edilen unvanlara ait görevleri vekâleten, ikinci görevle, geçici görevle veya kanunlarda yazılı diğer hallerde yetkili olarak yürütenler de bu görevi yürüttükleri sürece disiplin amirlerine tanınan yetkileri kullanabilirler. (3) Disiplin amirleri boşanmış olsalar dahi eşleri veya ikinci dereceye kadar kan ve kayın hısımları olan personel hakkında, bu sıfatlarından doğan yetkilerini kullanamazlar. Bu hallerde, disiplin amirliği yetkisi, üst konumdaki disiplin amiri tarafından kullanılır. (4) Disiplin amirliği yetkisi devredilemez.",
  "Disiplin m.19": "MADDE 19- (1) Jandarma Genel Komutanlığı merkez ve taşra teşkilatlarında aşağıdaki disiplin kurulları bulunur. a) İl jandarma disiplin kurulu, vali yardımcısının başkanlığında, 1) İl hukuk işleri müdürü (...), 2) İl jandarma komutanı veya görevlendireceği yardımcılarından biri (...), 3) Personel şube müdürü (...), 4) Asayiş şube müdürü (...) oluşur. (...) ç) (...) Jandarma Genel Komutanlığı Merkez Disiplin Kurulu; Jandarma Genel Komutanının görevlendireceği en az tuğgeneral rütbesini taşıyan bir subayın başkanlığında (...) oluşur. d) (...) Jandarma Genel Komutanlığı Yüksek Disiplin Kurulu; Jandarma Genel Komutanının veya görevlendireceği jandarma genel komutan yardımcısının başkanlığında (...) oluşur. (2) Astsubayların disiplin işlerinin görüşülmesinde ve karara bağlanmasında; Bakanlık Yüksek Disiplin Kurulu ve Jandarma Genel Komutanlığı Yüksek Disiplin Kurulu hariç olmak üzere diğer disiplin kurullarında, hakkında disiplin soruşturması yapılandan daha kıdemli bir astsubay üyeye de yer verilir.",
  "Disiplin m.2": "MADDE 2- (2) Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı emrine verilen yükümlü erbaş ve erler hakkında 31/1/2013 tarihli ve 6413 sayılı Türk Silahlı Kuvvetleri Disiplin Kanunu hükümleri uygulanır.",
  "Disiplin m.20": "MADDE 20- (1) a) İl jandarma disiplin kurulu (...) 1) Yüzbaşı ve altı rütbelerdeki subay, astsubay, uzman jandarma ve diğer sınıflardaki memurlara meslekten çıkarma ve Devlet memurluğundan çıkarma cezası dışında kalan diğer disiplin cezalarını, verebilir. (2) (...) a) Albay rütbesindeki personele meslekten çıkarma cezasını, b) Generaller hakkında tüm disiplin cezalarını, vermeye Bakanlık Yüksek Disiplin Kurulu yetkilidir. MADDE 21- (1) a) İl jandarma disiplin kurulunun meslekten çıkarma cezası dışındaki kararları valinin onayıyla; meslekten çıkarma cezası kararları valinin önerisi, Jandarma Genel Komutanlığı Yüksek Disiplin Kurulunun uygun görüşü ve Bakanın onayıyla, b) Asayiş kolordu komutanlıkları, komando tugay/alay komutanlıkları, (...) eğitim tugay ve birlik komutanlıkları disiplin kurulu, Genel Komutanlık Merkez Disiplin Kurulu ile eğitim ve öğretim kurumlarındaki disiplin kurullarının meslekten çıkarma cezası dışındaki kararları Jandarma Genel Komutanının onayıyla, meslekten çıkarma cezası kararları JGnK Yüksek Disiplin Kurulunun uygun görüşü ve Bakanın onayıyla, c) Genel Komutanlık Yüksek Disiplin Kurulunun kararları Bakanın onayıyla, kesinleşir.",
  "Disiplin m.25": "MADDE 25- (1) Emniyet Genel Müdürü, Jandarma Genel Komutanı ve Sahil Güvenlik Komutanının disiplin cezasını gerektiren fiilleri öğrenildiğinde haklarında Bakan onayıyla Bakanlık müfettişleri görevlendirilir. (2) Soruşturma sonucunda Bakanın resen verebileceği cezalardan daha ağır bir cezayı gerektiren disiplinsizlik tespit edilmesi halinde, dosya Bakanlık Yüksek Disiplin Kurulunca karara bağlanır. (3) Bakanlık Yüksek Disiplin Kurulunun bu maddedeki görevlerine ilişkin sekretarya hizmetleri Bakanlık Personel Genel Müdürlüğü tarafından yerine getirilir. (4) (...) Emniyet Genel Müdürlüğü, Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığından gelen üyeler katılamazlar. MADDE 26- (1) (Değişik:18/10/2018-7148/42 md.) Disiplin soruşturmasının açılmasında ve disiplin amiri veya disiplin kurulunun saptanmasında disiplinsizlik yaptığı iddia edilen personelin fiili işlediği tarihte çalıştığı yer esas alınır. (...) Ast memur ile üst memurun aynı fiile iştiraki halinde yetkili disiplin kurulu, üst memur hakkında disiplin cezası vermeye yetkili disiplin kuruludur. (...) (8) Disiplin kurulları salt çoğunlukla toplanır. Kararlar oy çokluğu ile alınır. Çekimser oy kullanılamaz. Oyların eşitliği halinde başkanın oyu yönünde karar alınmış sayılır. (9) Disiplin kurulları; (...) hâkim veya savcı kararı gerektirmeyen durumlarda kriminal inceleme yaptırma da dahil olmak üzere her türlü inceleme yapma ve ilgili makamlarla yazışma yetkisini haizdir.",
  "Disiplin m.29": "MADDE 29- (1) Bu Kanunda sayılan fiilleri işleyenler hakkında bu fiillerin işlendiğinin disiplin amiri tarafından öğrenildiği tarihten itibaren; a) Uyarma, kınama, aylıktan kesme ve kısa ve uzun süreli durdurma cezalarında bir ay içinde, b) Meslekten çıkarma cezası ve Devlet memurluğundan çıkarma cezasında altı ay içinde, disiplin soruşturmasına başlanmadığı takdirde disiplin cezası verme yetkisi zamanaşımına uğrar. (2) Disiplin cezasını gerektiren fiillerin işlendiği tarihten itibaren iki yıl içinde disiplin cezası verilmediği takdirde ceza verme yetkisi zamanaşımına uğrar. (3) Zamanaşımı, tamamlanmış suçlarda suçun işlendiği, kesintisiz suçlarda kesintinin gerçekleştiği, zincirleme suçlarda ise son suçun işlendiği tarihten itibaren işlemeye başlar.",
  "Disiplin m.3": "MADDE 3- (1) Bu Kanunun uygulanmasında; d) Disiplin amiri: Bu Kanun ile disiplin cezası vermeye yetkili kılınmış ilk amiri, e) Disiplin amirleri: Disiplin amiri ile üst disiplin amirlerini, j) Üst: Makam, rütbe veya kıdem büyüklüğünü, k) Üst disiplin amirleri: Disiplin amirinin kadro ve kuruluş yönünden bağlı bulunduğu ve disiplin cezası verilecek personelden makam, rütbe veya kıdemce büyük olan yetkili sıralı tüm amirleri, ifade eder.",
  "Disiplin m.30": "MADDE 30- (1) Disiplin amirleri tarafından verilen disiplin cezalarına karşı, cezanın tebliğ edilmesinden itibaren on gün içinde itiraz edilebilir. İtiraz, bir üst disiplin amirine yazılı olarak yapılır. Ancak vali, Emniyet Genel Müdürü, Jandarma Genel Komutanı veya Sahil Güvenlik Komutanının doğrudan verdikleri disiplin cezalarına karşı Bakanlık Yüksek Disiplin Kuruluna itiraz edilir. İtiraz üzerine Kurulun verdiği karar kesindir. Kaymakamın doğrudan verdiği disiplin cezalarına karşı ise valiye itiraz edilir. Süresi içinde itiraz edilmeyen cezalar kesinleşir. (2) İtiraz, yetkili merci tarafından otuz gün içinde karara bağlanır. (3) İtiraz haklı görülürse itirazı inceleyen merci verilen cezayı hafifletebilir veya tamamen kaldırabilir. (...) (4) İtiraz üzerine önceki cezadan daha ağır ceza verilemez. (5) Bakan ile disiplin kurullarının verdiği disiplin cezalarına karşı ancak idari yargı yoluna başvurulabilir.",
  "Disiplin m.31": "MADDE 31- (1) Disiplin amirleri veya disiplin kurulları tarafından savunma alınmadan disiplin cezası verilemez. (2) Disiplin amirince veya yetkili disiplin kurulu başkanı ya da görevlendireceği kurul üyelerinden biri tarafından ilgiliden savunma istenir. Savunma için verilen süre yedi günden az olamaz. Süresi içinde savunmasını yapmayan personel, savunma hakkından vazgeçmiş sayılır. (3) Hakkında disiplin soruşturması yapılan personel, ikinci fıkra gereğince kendisinden savunma istenmesinden itibaren soruşturma evrakını inceleme hakkına sahiptir. (4) Hakkında meslekten çıkarma cezası veya Devlet memurluğundan çıkarma cezası istenen personel, soruşturma evrakını incelemeye, tanık dinletmeye, disiplin kurulunda sözlü veya yazılı olarak kendisi veya vekili vasıtasıyla savunma yapma hakkına sahiptir.",
  "Disiplin m.32": "MADDE 32- (1) Kesinleşen disiplin cezalarına karşı iptal davası açılabilir. (2) Dava açma süresi, kesinleşen cezanın personele tebliğinden itibaren başlar. Ancak Sahil Güvenlik Komutanlığının seyir halindeki gemi ve botlarında verilen cezalarda dava açma süresi, geminin bağlı bulunduğu üsse veya limana dönmesiyle başlar.",
  "Disiplin m.33": "MADDE 33- (1) Disiplin cezaları, kesinleşmesini müteakip yerine getirilir. (2) Aylıktan kesme cezası, kesinleşme tarihini takip eden aybaşında uygulanır. (3) Verilen disiplin cezaları üst disiplin amirine, meslekten çıkarma cezası ve Devlet memurluğundan çıkarma cezası ayrıca Devlet Personel Başkanlığına bildirilir.",
  "Disiplin m.4": "MADDE 4- (1) Disiplinsizlik kasten veya taksirle oluşabilir.\n\nMADDE 4- (2) Aynı fiil nedeniyle bu Kanunda yazılı disiplin cezalarından birden fazlası verilemez. (3) Bir fiilin birden fazla disiplinsizlik teşkil etmesi halinde ağır olan disiplin cezası verilir. (4) Bir fiilin diğer kanunlar kapsamında idari yaptırıma bağlanmış olması, aynı fiile bu Kanun kapsamında disiplin cezası verilmesine engel teşkil etmez.",
  "Disiplin m.5": "MADDE 5- (1) Herhangi bir fiilden dolayı ilgili hakkında yapılan adli soruşturma veya kovuşturma, aynı fiilden dolayı ayrıca disiplin soruşturması ve tahkikat yapılmasını, disiplin cezası verilmesini ve bu cezanın yerine getirilmesini engellemez.",
  "Disiplin m.6": "MADDE 6- (1) Bu Kanun ile disiplin cezası vermeye yetkilendirilen disiplin amirleri veya kurulları, disiplin cezası uygulanması ile ilgili takdir haklarını ölçülü, adaletli ve hakkaniyetli bir şekilde kullanırlar. (2) Takdir hakkı mutlaka gerekçeli olarak kullanılır. (3) Takdir hakkı kullanılırken; a) Disiplinsizliğin işleniş biçimi, b) Disiplinsizliğin işlendiği zaman ve yer, c) Disiplinsizliğin hizmete olumsuz etkisinin ağırlığı, ç) Meydana gelen zarar veya tehlikenin ağırlığı, d) Disiplinsizlik yapan personelin kast veya taksire dayalı kusurunun ağırlığı, e) Disiplinsizlik yapan personelin daha önceki disiplin durumu, f) Disiplinsizlik yapan personelin samimi ikrarı ve gösterdiği pişmanlık, gözönüne alınır. (4) İtiraz üzerine yetkili makamlar tarafından verilen kararlar hariç olmak üzere, hiçbir idari makam tarafından, disiplin cezası ile ilgili takdir hakkının kaldırılması sonucunu doğuran bir karar verilemez veya uygulama yapılamaz.",
  "Disiplin m.7": "MADDE 7- (1) Personele verilecek disiplin cezaları şunlardır: a) Uyarma cezası: (...) yazı ile bildirilmesidir. b) Kınama cezası: (...) kusurlu olduğunun yazı ile bildirilmesidir. c) Aylıktan kesme cezası: (...) zam ve tazminatlar hariç brüt aylığından onbeş günlüğe kadar kesinti yapılmasıdır. ç) Kısa süreli durdurma: Personelin bulunduğu kademede ilerlemesinin dört, altı veya on ay süre ile durdurulmasıdır. d) Uzun süreli durdurma: (...) oniki, onaltı, yirmi veya yirmidört ay süre ile durdurulmasıdır. e) Meslekten çıkarma: Personelin emniyet, jandarma ve sahil güvenlik teşkilatlarında bir daha çalıştırılmamak üzere meslekten çıkarılmasıdır. f) Devlet memurluğundan çıkarma: Personelin bir daha Devlet memurluğuna atanmamak üzere memurluktan çıkarılmasıdır.\n\nMADDE 7- (1) c) Aylıktan kesme cezası: (...) brüt aylığından onbeş günlüğe kadar kesinti yapılmasıdır. ç) Kısa süreli durdurma: Personelin bulunduğu kademede ilerlemesinin dört, altı veya on ay süre ile durdurulmasıdır. d) Uzun süreli durdurma: Personelin bulunduğu kademede ilerlemesinin oniki, onaltı, yirmi veya yirmidört ay süre ile durdurulmasıdır.\n\nMADDE 7- (5) Devlet memurluğundan çıkarma ya da meslekten çıkarma cezalarından başka bir disiplin cezasına çarptırılmış olanlar, uyarma ve kınama cezalarının uygulanmasından başlayarak beş yıl, diğer cezaların uygulanmasından başlayarak on yıl geçtikten sonra, atamaya yetkili amire başvurarak verilmiş olan disiplin cezalarının özlük dosyasından silinmesini isteyebilir. İlgilinin bu süreler içerisindeki davranışları, bu isteğini haklı kılacak nitelikte görülürse söz konusu ceza özlük dosyasından silinir.\n\nMADDE 7- (1) e) Meslekten çıkarma: Personelin emniyet, jandarma ve sahil güvenlik teşkilatlarında bir daha çalıştırılmamak üzere meslekten çıkarılmasıdır. f) Devlet memurluğundan çıkarma: Personelin bir daha Devlet memurluğuna atanmamak üzere memurluktan çıkarılmasıdır.\n\nMADDE 7- (2) Kurumda geçmiş hizmetleri sırasında çalışmaları olumlu bulunan ve iyi veya çok iyi derecede değerlendirme puanı alan personel için verilecek cezalarda bir derece hafif olanı uygulanabilir. (3) Birinci fıkranın (c), (ç) ve (d) bentlerinin uygulanmasında, cezanın üst ve alt kademeleri ağır ya da hafif ceza sayılmaz.",
  "Disiplin m.8": "MADDE 8- (7) (...) Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığında, terfileri (...) 926 sayılı (...), 3466 sayılı (...), 3269 sayılı (...) ve (...) 6191 sayılı (...) Kanunu hükümlerine tabi olan personelin; a) Kısa süreli durdurma cezası verilmesini gerektiren hallerde brüt aylıklarının 1/5'i ila 1/4'ü, b) Uzun süreli durdurma cezası verilmesini gerektiren hallerde brüt aylıklarının 1/3'ü ila 1/2'si, kesilir. (8) Yedinci fıkrada yer alan cezalar yetkili disiplin kurullarınca verilir.\n\nMADDE 8- (1) Uyarma cezasını gerektiren fiiller şunlardır: a) Silahını, araç ve gerecini, giyim ve kuşamını temiz tutmamak, çalıştığı yerin temizliğine özen göstermemek. b) Yetkili makamlarca belirlenmiş tasarruf tedbirlerine riayet etmemek veya kullanımına sunulan kamu kaynaklarının kullanılmasında gösterilmesi gereken makul seviyedeki özeni göstermemek. c) İzinsiz veya kurumunca kabul edilebilir özrü olmaksızın belirli zamanda yapılması gereken faaliyetlere geç kalmak. ç) (Mülga). d) Özürsüz veya izinsiz olarak mesaiye geç gelmek veya erken ayrılmak ya da günlük mesai saatlerine riayet etmemek. e) Nezaket kurallarına aykırı tavır ve davranışlarda bulunmak. f) Emrin icrası veya sonuçları ile katılım sağlanan toplantılarla ilgili olarak görevlendirme yapan amire bilgi vermemek. g) Usulüne uygun olarak kendisine verilmiş olan bir emir üzerine; emrin uygun olmadığı, yanlış verildiği, yapılamayacağı ve benzeri şekillerde amirini alenen eleştirmek veya amire karşı itirazda bulunmak (Amir tarafından karar verilene kadar astın fikrini savunması veya emrin kanunsuz olduğu hususundaki kanaatini belirtmek için amire yaptığı itiraz bu kapsamda disiplinsizlik teşkil etmez.).\n\nMADDE 8- (2) Kınama cezasını gerektiren fiiller şunlardır: a) Görev sırasında, mevzuat veya talimatlarla yasaklanan davranışlarda bulunmak. b) Mevzuatta belirlenmiş usul ve kurallara riayet etmeden sözlü, yazılı veya elektronik olarak müracaat veya şikâyette bulunmak. c) Nöbeti teslimden sonra görev yerine özürsüz olarak geç dönmek. ç) Bildirimleri süresi içerisinde yerine ulaştırmamak. d) Mevzuat veya talimatlarla taşınmasına veya bulundurulmasına izin verilmiş olanlar dışında, mesleğin ciddiyeti ile bağdaşmayacak biçimde yüzük, bilezik, kolye, madalyon, rozet ve benzeri şeyleri takmak. e) Görev sırasında veya dışında kendisi ile aynı rütbede çalışanlara veya mesai arkadaşlarına karşı saygısız davranmak. f) Mevzuat ve talimatlarla kendisine tevdi edilmiş görevlerin gerektirdiği sorumluluğu üstlenmekten imtina ettiğini gösterecek tavır ve davranışlarda bulunmak. g) Amirleri, üstleri, aynı rütbedeki veya çalışma arkadaşları hakkında ve onların bulunmadığı ortamlarda, onların kişilikleri hakkında kötüleyici veya konuştuğu kişilerde kötü intiba bırakacak tarzda olumsuz sözler söylemek. ğ) Zati demirbaş tabanca veya geçici olarak verilen demirbaş tabancanın üzerinde orijinalliğini bozacak boya, kaplama, gravür veya ciddiyetle bağdaşmayacak şekil, desen, resim ve karakter gibi değişiklikler yapmak. h) Mevzuata veya mesleki teamüllere aykırı hitaplarda bulunmak. ı) Bu fıkrada disiplinsizlik olarak saptanan eylem, işlem, tutum ve davranışlar dışında herhangi bir biçimde görevin takdir ve yerine getirilmesinde müsamaha ve savsaklama göstermek. i) (Mülga).\n\nMADDE 8- (3) a) Üç günlüğe kadar aylıktan kesme cezasını gerektiren fiiller; 1) Mevzuat veya talimata aykırı olarak eksik kuşam ve teçhizatla göreve çıkmak. 2) Amir ve üstlerinin, görev ve mesleki konulara veya tutum ve davranışlarına ilişkin uyarılarına uymamak ya da bu uyarılara kayıtsız kalmak, amir ve üstleri tarafından sorulan soruları gereken süre içinde yanıtlamamak. 3) Özlük hakları ile ilgili veya başka bir kişisel menfaat temini için başkalarını aracı koyup öncelik ve ayrıcalık talep etmek. 4) İzinsiz veya kurumunca kabul edilebilir bir özrü olmaksızın yirmidört saate kadar göreve gelmemek. 5) Görev dışında amir veya üstlerine saygısız davranmak. 6) Nöbet görevine gelmemek veya nöbet ya da nokta görevinde mevzuatla ve/veya talimatlarla belirlenen kurallara aykırı hareket etmek. 7) Görevli bulunduğu sırada görev gereği olmaksızın veya amirin izni olmadan resmi kıyafet ile kahvehane, kıraathane, lokal, kulüp ve benzeri yerlerde oturmak. 8) Amirinden izin almaksızın görevli bulunduğu il sınırları dışına çıkmak. 9) Emrinde çalışanları veya Devletin araç ve gereçlerini idarece kabul edilebilir bir mazereti olmaksızın özel işlerinde kullanmak. 10) Kendisine verilmiş olan personel kimlik kartını kabul edilebilir bir neden olmaksızın kaybetmek. 11) Bazı isteklerini yerine getirmek, kişisel bir menfaat sağlamak, görev veya sorumluluktan kaçmak gibi amaçlarla hastalığını abartmak veya olmadığı halde bir rahatsızlığı varmış gibi göstererek günlük mesainin bir kısmına katılmamayı alışkanlık haline getirmek. 12) Herhangi bir yolu, yeri veya kişiyi arayıp soranlara cevap vermemek, baştan savmak. 13) Görevde kayıtsızlık göstermek, görevi savsaklamak veya geçerli bir özrü olmaksızın belirtilen sürede bitirmemek. 14) Haklı bir neden olmadan kişileri bekletmek. 15) Selamlama ile ilgili olarak belirlenmiş kurallara riayet etmemek. 16) Resmi protokol kurallarına aykırı tavır ve davranışlarda bulunmak. 17) Görevdeyken, yetkili makamlar tarafından izin verilen durumlar haricinde görev veya hizmetle ilgisi olmayan işlerle uğraşmak. 18) Kılık ve kıyafet ile ilgili olarak mevzuatta belirlenmiş kurallara uymamak.\n\nMADDE 8- (3) b) Dört ila on günlüğe kadar aylıktan kesme cezasını gerektiren fiiller; 1) Kendisi ile aynı rütbede çalışanlara, astlarına veya mesai arkadaşlarına karşı onur kırıcı söz söylemek, davranışta bulunmak veya söz, yazı ya da eylemle hakaret etmek. 2) Resmi belge veya göreve ilişkin evrakı kaybetmek. 3) Önlem almamak veya tedbirli davranmamak yüzünden Devlet malı eşyanın hasar görmesine veya kaybolmasına neden olmak. 4) İzinli olduğu zamanlarda resmi kıyafetle, izinli olmadığı zamanlarda görevli olmaksızın resmi veya sivil kıyafetle, personelin girmesine veya oturup eğlenmesine izin verilen yerler dışındaki kahvehane, lokal, kulüp veya benzeri yerlerde oyun oynamak. 5) İzinsiz veya kurumunca kabul edilebilir bir özrü olmaksızın yirmidört saatten fazla ve iki güne kadar (ikinci gün dahil) göreve gelmemek. 6) Mühür veya beratını kabul edilebilir bir neden olmaksızın kaybetmek. 7) Yükümlü bulunduğu devir ve teslim işlemlerini tamamlamadan ya da devir ve teslim işleri tamamlanamadığı takdirde ilgili mevzuatında belirtilen süre dolmadan görev yerinden ayrılmak. 8) Görevle ilgili resmi belge, araç ve gereçleri görevin sona ermesine ya da kurumca istenmesine rağmen geri vermemek. 9) İzin verilen haller dışında üniforma giymemek.\n\nMADDE 8- (3) c) Onbir ila onbeş günlüğe kadar aylıktan kesme cezasını gerektiren fiiller; 1) İzinsiz veya kurumunca kabul edilebilir bir özrü olmaksızın iki günden fazla ve üç güne kadar (üçüncü gün dahil) görevine gelmemek. 2) İzinli bulunduğu sürede, hizmet ve görevin gerektirdiği durumlarda, görevine derhal dönmesi kendisine sözlü, yazılı ya da herhangi bir iletişim vasıtasıyla duyurulduğu halde, kabul edilebilir özrü bulunmaksızın görevine makul sürede dönmemek. 3) Amir ve üstlerine iletilmesi gereken olay, bilgi ve emirleri zamanında iletmemek. 4) Görev sırasında kişilere karşı onur kırıcı söz söylemek veya davranışta bulunmak. 5) Denetleme ve soruşturmaları uzatmak, denetleme raporları ve soruşturma raporlarını süresinde ilgili yerlere vermemek veya göndermemek ya da kabul edilebilir bir neden olmadan soruşturmayı eksik bırakmak.\n\nMADDE 8- (4) a) Dört ay kısa süreli durdurma cezasını gerektiren fiiller; 1) Amir ve memurlara görevle ilgili olarak yalan söylemek. 2) Denetim görevini yerine getirmemek. 3) İzinsiz ya da kurumca kabul edilebilir özrü olmaksızın kesintisiz olarak üç günden fazla ve beş güne kadar (beşinci gün dahil) göreve gelmemek. 4) Amirlerini, üstlerini, aynı rütbedeki arkadaşlarını, astlarını veya diğer mesai arkadaşlarını haksız yere şikâyet etmek. 5) Astlarını, aynı rütbedeki arkadaşlarını ve diğer mesai arkadaşlarını dövme girişiminde bulunmak. 6) Toplu olarak sözlü veya yazılı şikâyette bulunmak. 7) Görev sırasında amir veya üstlerine saygısız davranmak. 8) Bu Kanunda ayrıca disiplinsizlik olarak tanımlanmamış olmak kaydıyla astları veya mesai arkadaşlarına yönelik olarak sürekli ve sistemli her türlü baskı ve taciz uygulamak.\n\nMADDE 8- (4) b) Altı ay kısa süreli durdurma cezasını gerektiren fiiller; 1) Doğrudan veya aracı eliyle astlarından ya da iş sahiplerinden hediye veya borç almak. 2) Kabul edilebilir mücbir sebepler haricinde borçlanıp ödememeyi alışkanlık haline getirmek. 3) Görevde kullanılan telsiz haberleşme araçlarıyla görevle ilgili olmayan veya saygısızca konuşmalar yapmak ya da anlaşılmaz sesler çıkarmak. 4) Teslim aldığı her çeşit motorlu araç, makine, cihaz ve teçhizatta ağır kusur veya hizmetten ayrılabilen kişisel kusurla hasara sebep olmak. 5) Görev sırasında veya dışında kurumun hiyerarşik düzenini bozacak veya amirin ya da üstlerinin otoritesini zedeleyecek şekilde amir ya da üstlerinin eylem veya işlemlerini olumsuz yönde eleştirici nitelikte söz söylemek ya da yazı yazmak. 6) Hizmet dışında resmi sıfatının gerektirdiği saygınlığı ve güven duygusunu sarsacak eylem ve davranışlarda bulunmak. 7) Bir görevin kendisine tevdi edildiğini öğrendikten sonra mazeretler ileri sürmek suretiyle göreve başlamayı geciktirmek.\n\nMADDE 8- (4) c) On ay kısa süreli durdurma cezasını gerektiren fiiller; 1) Amir ve üstlerine iletilmesi gereken olayları ve bunlarla ilgili bilgileri amirlerinden ve resmen istenmesi halinde görevli ve yetkili kuruluş ve kişilerden gizlemek. 2) Yetkili olmadığı halde basın, haber ajansları, radyo ve televizyon kurumları veya diğer iletişim kanalları vasıtasıyla kamuoyuna bilgi ya da demeç vermek. 3) Silahla dikkatsizlik, tedbirsizlik veya ihmal sonucu yaralamaya sebebiyet vermek, kendisini yaralamak ya da bu fiillerin başkaları tarafından işlenmesine neden olmak. 4) Hizmet aracıyla ağır kusuru veya hizmetten ayrılabilen kişisel kusuruyla trafik kazası sonucu yaralamaya sebebiyet vermek. 5) Aynı rütbedeki meslektaşları ile diğer mesai arkadaşlarını tehdit etmek.\n\nMADDE 8- (5) a) Oniki ay uzun süreli durdurma cezasını gerektiren fiiller; 1) Belirlenen durum ve sürelerde mal bildiriminde bulunmamak veya gerçeğe aykırı bildirimde bulunmak. 2) Görev sırasında kişilere veya herhangi bir nedenle kurum binalarına gelen ya da getirilenlere hakaret etmek.\n\nMADDE 8- (5) b) Onaltı ay uzun süreli durdurma cezasını gerektiren fiiller; 1) Devlet malı motorlu araçları, muhabere araçlarını, silah veya mühimmatı ihmal nedeniyle kaybetmek. 2) Hizmet içinde resmi sıfatının gerektirdiği saygınlığı ve güven duygusunu sarsacak eylem ve davranışlarda bulunmak. 3) Görev sırasında herhangi bir şekilde uyumak veya uyuklamak.\n\nMADDE 8- (5) c) Yirmi ay uzun süreli durdurma cezasını gerektiren fiiller; 1) İzinsiz veya kurumca kabul edilebilir özrü olmaksızın kesintisiz olarak beş günden fazla ve dokuz güne kadar (dokuzuncu gün dahil) görevine gelmemek. 2) Muhafazası veya sevkiyle yükümlü bulunduğu şüpheli, sanık, tutuklu veya hükümlünün uyanık davranmamak ya da önlem almamak yüzünden kaçmasına neden olmak ya da yakalama görevini savsaklamak. 3) Kanunun verdiği yetkiye dayalı olmaksızın spor müsabakalarına dayalı sabit ihtimalli veya müşterek bahis veya şans oyunlarını oynamak.\n\nMADDE 8- (5) ç) Yirmidört ay uzun süreli durdurma cezasını gerektiren fiiller; 1) Silahla dikkatsizlik, tedbirsizlik veya ihmal sonucu ölüme sebebiyet vermek ya da bu fiilin başkaları tarafından işlenmesine neden olmak. 2) Silahla yaralama suçunu kasten işlemek. 3) Meskûn yerlerde, binalarda, herkesin dolaşıp gezebileceği veya oturabileceği yerlerde silah atmak. 4) Amirin usulüne göre verdiği emri yerine getirmemek. 5) Amirin izni olmaksızın görev yerini terk etmek. 6) Kişinin iffetine yönelik söz söylemek, fiil veya harekette bulunmak. 7) Amir veya üste hakaret etmek. 8) Amir veya üstlerini söz, yazı, tutum veya davranışlarıyla küçümsemek. 9) Amir veya üstlerini dövmeye teşebbüs etmek. 10) Amir veya üstlerini sözlü veya fiili olarak tehdit etmek. 11) Göreve ilişkin her türlü yazılı kağıt, belge, mikrofilm aslı veya kopyalarını kasıtlı olarak yok etmek, ortadan kaldırmak ya da belge niteliği taşıyan bilgisayar programlarını, dosyalarını, verilerini hukuka aykırı olarak ele geçirmek, başkasına zarar vermek üzere kullanmak, tahrip etmek, değiştirmek, silmek, sistemin işlemesine engel olmak ya da yanlış biçimde işlemesini sağlamak. 12) Kriptolu telsiz cihazının ve her türlü kriptolu cihazın kaybını veya çalındığını, idarece kabul edilebilir bir mazereti olmaksızın ilgili birime derhal bildirmemek. 13) Hizmet aracıyla ağır kusuru veya hizmetten ayrılabilen kişisel kusuruyla trafik kazası sonucu ölüme sebebiyet vermek.\n\nMADDE 8- (6) Meslekten çıkarma cezasını gerektiren fiiller şunlardır: a) Görevin yerine getirilmesinde dil, ırk, cinsiyet, siyasi düşünce, felsefi inanç, din ve mezhep ayrımı yapmak veya personel arasında bu yolda ayrım yapıcı tutum ve davranışlarda bulunmak. b) Göreve çıkılmaması için propaganda yapmak, kışkırtmak, zorlamak, karar alınmasını sağlamak, alınan bu karara katılmak veya karar uyarınca göreve çıkmamak. c) Amir ya da üstlerinin icraatına karşı çıkmak ve bu hareketi toplu hale dönüştürerek görev yapılmasını ya da göreve çıkılmasını engellemek, buna katılmak, katılmaya tahrik ya da teşvik etmek. ç) Yetkisini veya nüfuzunu kendisine veya başkalarına çıkar sağlamak amacıyla ya da kin ve dostluk gibi nedenlerle kötüye kullanmak. d) Hizmetle ilgili her türlü dosya, kayıt, resmi evrak veya belgeyi ya da örneklerini yetkisiz kişilere vermek, verilmesini emretmek, verilmesine göz yummak. e) Gizli tutulması zorunlu olan ve görev ile ilgili bulunan bilgi ve belgeleri görevli veya yetkili olmayan kişilere açıklamak. f) Muhafazası veya sevkiyle görevli olduğu şüpheli, sanık, tutuklu veya hükümlünün kaçmasına bilerek ve isteyerek imkân vermek. g) Bilerek ve isteyerek suç kanıtlarını yok etmek veya bunların yok olmasına neden olmak, kanıtları silmek, gizlemek, değiştirmek, bozmak veya bu fiillere yardımcı olmak. ğ) Devlet malı araç, gereç, hayvan, silah, mermi ve mühimmatı satmak veya mal edinmek, personel kimlik kartını, araç, gereç, hayvan, silah ve mühimmatı başkalarının kullanımına vermek. h) Kasıtlı olarak gerçek dışı rapor vermek veya tutanak düzenleyip imza etmek veya ettirmek. ı) Görev sırasında yardım isteyen güvenlik görevlilerine haklı bir neden yokken yardımdan kaçınmak veya bildiği ya da gördüğü bir suçun izlenmesi ve suçlunun yakalanması için gerekli girişimde bulunmamak. i) Mesleğin saygınlığını zedeleyecek şekilde uygunsuz yerlere gitmek. j) Görev mahallinde veya görevli bulunduğu sırada alkollü içki içmek veya içilmesine göz yummak. k) Göreve sarhoş veya alkollü içki içtiği belli olacak biçimde gelmek. l) Resmi kıyafetle umuma açık yerlerde alkollü içki içmek veya resmi kıyafetli olarak gizlenemeyecek derecede sarhoş görünmek. m) Uyuşturucu maddeleri yapmak veya kullanmak, bunların yapılmasına, kullanılmasına, saklanmasına, nakledilmesine, yakalanacağı sırada ortadan kaldırılmasına, satılmasına veya satın alınmasına aracı olmak, kullanılmasını kolaylaştırmak ya da özendirmek. n) Kumar oynamak veya oynatmak, kumar oynatanlarla ilişki kurmak. o) Kaçakçılık yapmak veya kaçakçılarla ilişki kurmak. ö) Geliri ile uygun sayılmayacak biçimde yaşadığı ve aşırı harcamada bulunduğu kanıtlanmış olmak ve bunun haklı kaynağını gösterememek. p) 657 sayılı Devlet Memurları Kanunu ile öngörülen grev yasağı kapsamına giren eylemlerde bulunmak. r) Devlet memurları tarafından yapılamayacağı 657 sayılı Kanunda belirtilen kazanç getirici faaliyetlerde bulunmak. s) Siyasi partilerin yararına veya zararına çalışmak ya da siyasal eylemlerde bulunmak, görevli olmaksızın siyasal amaçla yapılacak açık veya kapalı yer toplantılarına ya da gösteri yürüyüşlerine katılmak. ş) İffetsizliği bilinen veya anlaşılmış olan bir kimse ile bilerek evlenmek ya da evlilik bağını devam ettirmek veya böyle bir kimseyi yanında bulundurmak ya da nikahsız olarak devamlı surette yaşamakta ısrar etmek. t) Kanuna aykırı olarak sendikalara üye olmak, sendikaların veya üyesi bulunmadıkları derneklerin yapacakları bilimsel, kültürel ve teknik nitelik taşımayan açık veya kapalı yer toplantılarına ya da gösteri yürüyüşlerine görevli olmaksızın katılmak, açık yer toplantı ve gösteri yürüyüşlerine resmi kıyafetli veya silahlı olarak katılmak ya da üyesi bulundukları derneklerin tüzüklerinde belirtilen amaçları dışındaki çalışmalarını veya bu nitelikteki toplantı ya da gösteri yürüyüşlerini düzenlemek veya bunlara katılmak. u) Görevde kullanılan telsiz, telefon haberleşmesini veya kurum içi iletişim sistemlerini kasıtlı olarak engellemek. ü) Mesleğin onur ve saygınlığını zedeleyici veya amir ya da üstlerinin eylem ve işlemlerini olumsuz yönde eleştirici nitelikte tek başına veya topluca bildiri dağıtmak ya da basın, haber ajansları, radyo ve televizyon kurumları ve diğer iletişim kanalları vasıtasıyla kamuoyuna yönelik bilgi, yazı ve demeç vermek. v) Amir ya da üste karşı itaatsizliğe, mukavemete ya da fiilen taarruza tahrik ya da teşvik etmek. y) Menşei belli olmayan, bulundurulması ve taşınması yasak olan her çeşit silah, mühimmat ve benzerlerini bulundurmak. z) Hukuka aykırı olarak kişiler arasındaki haberleşmenin gizliliğini ihlal etmek, ... kişilerin özel hayatının gizliliğini ihlal etmek, ... kişisel verileri kaydetmek, kişisel verileri bir başkasına vermek, yaymak veya ele geçirmek, ... gerçeğin meydana çıkmasını engellemek amacıyla suç delillerini yok etmek, silmek, gizlemek, değiştirmek veya bozmak, sayılan fiilleri emir vererek yaptırmak. aa) Yetkili olmadığı halde hukuka aykırı olarak elektronik ortamda veya bilgisayar loglarında kişisel verilerle ilgili sorgulama yapmak, bu şekilde elde edilen bilgileri paylaşmak veya yayın yoluyla duyurmak, log kayıtlarını değiştirmek veya silmek. bb) Görevi gereği öğrendiği veya edindiği kişisel bilgi veya belgeleri yetkisiz kişilerle paylaşmak ya da basın ve yayın kuruluşlarına veya diğer iletişim kanallarına vermek. cc) Bir kimseyle gayri tabii mukarenette bulunmak yahut bu fiili kendisine rızasıyla yaptırmak. çç) Görevine, sosyal ve aile yaşantısına zarar verecek derecede menfaatine, içkiye, kumara ve benzeri kötü alışkanlıklara düşkün olmak. dd) Üstlerine, aynı rütbedeki meslektaşları ile diğer mesai arkadaşlarına fiili tecavüzde bulunmak. ee) Görevde kullanılan telsiz haberleşme araçlarıyla amir ya da üstleri hakkında olumsuz yönde eleştirici nitelikte konuşmalar yapmak. ff) Dernek kurmak ya da spor dernekleri dışındaki derneklere üye olmak. gg) Vakıf kurmak veya Bakanlıkça belirlenmiş vakıflardan başka vakıfların organlarında görev almak. hh) Fuhşa teşvik eden, bunun yolunu kolaylaştıran ya da fuhuş için aracılık eden veya yer temin eden kişilerle bilerek ilişki kurmak.",
  "Disiplin m.9": "MADDE 9- (1) Devlet memurluğundan çıkarma cezası uygulanacak fiiller ve bu cezayı verme yetkisi ile ilgili olarak 657 sayılı Kanun hükümleri uygulanır. Ayrıca, aşağıdaki filleri işleyen personel de Devlet memurluğundan çıkarma cezası ile cezalandırılır; a) Ülkenin bağımsızlığını zedelemeye, bütünlüğünü bozmaya ve milli güvenliği tehlikeye düşürmeye yönelik herhangi bir faaliyette bulunmak veya aynı nitelikte faaliyet gösteren herhangi bir harekete, gruplaşmaya, vakıf, dernek ve benzeri teşekküle katılmak, bunlara yardım etmek veya bu yapılarla ilişki içerisinde bulunmak. b) İşkence yapmak.",
  "E-İmza m.3": "Bu Kanunda geçen; a) Elektronik veri: Elektronik, optik veya benzeri yollarla üretilen, taşınan veya saklanan kayıtları, b) Elektronik imza: Başka bir elektronik veriye eklenen veya elektronik veriyle mantıksal bağlantısı bulunan ve kimlik doğrulama amacıyla kullanılan elektronik veriyi, c) İmza sahibi: Elektronik imza oluşturmak amacıyla bir imza oluşturma aracını kullanan gerçek kişiyi, (...) ifade eder.\n\n(...) d) İmza oluşturma verisi: İmza sahibine ait olan, imza sahibi tarafından elektronik imza oluşturmak amacıyla kullanılan ve bir eşi daha olmayan şifreler, kriptografik gizli anahtarlar gibi verileri, (...) f) İmza doğrulama verisi: Elektronik imzayı doğrulamak için kullanılan şifreler, kriptografik açık anahtarlar gibi verileri, (...) h) Zaman damgası: Bir elektronik verinin, üretildiği, değiştirildiği, gönderildiği, alındığı ve / veya kaydedildiği zamanın tespit edilmesi amacıyla, elektronik sertifika hizmet sağlayıcısı tarafından elektronik imzayla doğrulanan kaydı, ı) Elektronik sertifika: İmza sahibinin imza doğrulama verisini ve kimlik bilgilerini birbirine bağlayan elektronik kaydı, j) Kurum: Telekomünikasyon Kurumunu, ifade eder.\" **[GÜNCEL NOT — mevzuat.gov.tr dipnot 1:** 5809 s. Kanun m.65/3 gereği \"Telekomünikasyon Kurumu\" ibaresi bugün **Bilgi Teknolojileri ve İletişim Kurumu (BTK)** olarak anlaşılır; yürürlükteki makam BTK'dır.]",
  "E-İmza m.4": "Güvenli elektronik imza; a) Münhasıran imza sahibine bağlı olan, b) Sadece imza sahibinin tasarrufunda bulunan güvenli elektronik imza oluşturma aracı ile oluşturulan, c) Nitelikli elektronik sertifikaya dayanarak imza sahibinin kimliğinin tespitini sağlayan, d) İmzalanmış elektronik veride sonradan herhangi bir değişiklik yapılıp yapılmadığının tespitini sağlayan, elektronik imzadır.",
  "E-İmza m.5": "Güvenli elektronik imza, elle atılan imza ile aynı hukukî sonucu doğurur. Kanunların resmî şekle veya özel bir merasime tabi tuttuğu hukukî işlemler ile banka teminat mektupları ve Türkiye'de yerleşik sigorta şirketleri tarafından düzenlenen kefalet senetleri dışındaki teminat sözleşmeleri, güvenli elektronik imza ile gerçekleştirilemez.",
  "Hizmet Esasları Yön m.1": "MADDE 1 - (1) Bu Yönetmeliğin amacı; yürütülen görevlerin icrası esnasında ve görev dışı zamanlarda Jandarma Genel Komutanlığı, Sahil Güvenlik Komutanlığı, Jandarma ve Sahil Güvenlik Akademisi personelinin uyması gereken kuralları, sahip olması gereken vasıfları ve muhtelif görevlerin icra tarzını belirlemektir. MADDE 2 - (1) Bu Yönetmelik, Jandarma Genel Komutanlığı, Sahil Güvenlik Komutanlığı, Jandarma ve Sahil Güvenlik Akademisindeki karargâh, birlik ve kurumlar ile buralarda görev yapan personeli kapsar. (...) MADDE 3 - (1) Bu Yönetmelik, 10/3/1983 tarihli ve 2803 sayılı Jandarma Teşkilat, Görev ve Yetkileri Kanununun 24'üncü maddesine ve 9/7/1982 tarihli ve 2692 sayılı Sahil Güvenlik Komutanlığı Kanununun 23'üncü maddesine dayanılarak hazırlanmıştır.",
  "Hizmet Esasları Yön m.10": "(1) Emir tüm görevlerin düzenleyicisidir. (2) Emirlerin, göreve ilişkin ve mevzuata uygun olması şarttır. (3) Ast emri; Anayasa ve mevzuat hükümlerine aykırı görürse, yerine getirmez ve bu aykırılığı o emri verene bildirilir. Ancak, âmir emrinde ısrar ederse ve bu emrini yazı ile yinelerse, emir yerine getirilir. Emrin yerine getirilmesinden doğacak sorumluluk emri verene aittir. Ancak, durum emri veren âmirin bir üst âmirine bildirilir. (4) Konusu suç teşkil eden emir hiçbir surette yerine getirilmez; yerine getiren kimse sorumluluktan kurtulamaz.\n\n(5) Emrin yazılı, sözlü veya sair usullerle verilme takdiri, âmire aittir. (...) (7) Emirler, kural olarak birbirine bağlı âmirler tarafından, silsile ile verilir. Ancak, acele ve zorunlu hallerde bu sıraya riayet edilmeden de emir verilebilir. Bu takdirde emri veren âmir, atlanan kademelere en kısa zamanda bilgi verir. Böyle bir emri alan maiyet de âmirini haberdar eder. (...) (9) Emir, net ve anlaşılır olmalıdır. (...) (11) Emirde kararlılık esastır. Verilen emir, mecburi sebepler oluşmadıkça veya gerekliliği ortadan kalkmadıkça değiştirilemez veya yok sayılamaz.",
  "Hizmet Esasları Yön m.11": "(1) Personel, kurumlarıyla ilgili resmi ve şahsi işlerinden dolayı müracaat; amirleri veya kurumları tarafından kendilerine uygulanan idari eylem ve işlemlerden dolayı şikâyet ve dava açma hakkına sahiptir. (2) Personelin, aynı konu ve şahısla ilgili, toplu olarak söz veya yazı ile müracaatı yasaktır. Aynı olay birden fazla personelin şikâyetine sebep veya konu olursa bunların her biri ayrı ayrı veya yalnız başına şikâyet hakkını kullanabilir. (3) Şikâyetleri incelemeye yetkili olan âmirler, bizzat şikâyeti neticelendirirler. (...) (4) Âmirin yüzüne karşı kendisini şikâyet etmek, âmirinden şikâyetçi olacağını söyleyerek dedikodu yapmak cezayı muciptir.",
  "Hizmet Esasları Yön m.14": "(1) İznin maksadı, personelin dinlenmesi, gücünü toplaması, yenilenmiş güçle göreve tekrar dönmesinin sağlanması ve bazı şahsi ihtiyaçlarını görmesidir. (2) İzinler; göreve ve mümkün olduğunca personelin talep edeceği aylara göre önceden planlanmalı (...). (3) Âmir, açıkça olmasa da, personelin izin hakkından gönüllü olarak feragat etmesine yönelik tavır, davranış ve imada bulunmamalıdır. (...) (5) İzne giden her personel, ayrılmadan evvel kendi birlik veya kurum âmirine gideceği yerdeki adresini ve iletişim araçlarını bildirmeli, izinden çağrılmayı gerektirecek hallerin varlığı halinde ise kendisini ulaşılabilir kılmalıdır. (6) İzin yılı, her senenin ilk ayından itibaren başlar (...).",
  "Hizmet Esasları Yön m.15": "(1) Personelin kılık ve kıyafetlerinin uygun olması kendilerine, ait olduğu kuruma, mesleklerine ve topluma saygılarının bir ifadesidir. (2) Rütbeli personel ve erlerin görev sırasında resmî kıyafetli olması esastır. (...) (7) Rütbeli personel ve erlerin hangi görevlerde sivil kıyafet giyebileceği, görevin mahiyetine göre yetkili makamlarca tespit edilir. (8) Rütbeli personel ve erler; tanıklık veya bilirkişilik dışında, adlî yargı makam ve mercilerine çağrıldığında, tutuklu veya hükümlü iken veya görevden uzaklaştırıldıkları süre içerisinde resmî kıyafet giyemez. (...) (10) Kimlik kartı, kişinin jandarma veya sahil güvenlik personeli olduğunu gösteren resmî bir belgedir. Personel, (...) çeşitli istisnai durumlar dışında, kimlik kartını resmî ve sivil olarak her zaman üzerinde bulundurmak zorundadır.\n\n(9) Kılık ve resmî kıyafet konusunda dikkat edilecek hususlar şunlardır: a) Resmi kıyafet ile görev amacı saklı kalmak üzere toplumun genel ahlak anlayışı ile örtüşmeyen yer ve alkollü mekânlara gidilmez. b) Resmî kıyafet ile sakız çiğnenmez, poşet taşınmaz, şapka çıkarılmaz, kol kola girilmez, el ele tutuşulmaz, ağızda sigara veya eller cepte dolaşılmaz. (...) c) (...) Hak sahibi olunmayan veya mevzuatta belirtilen özelliklere uymayan şerit rozet ve bröveler takılmaz. ç) Resmî kıyafet ile nişan, evlilik ve devre yüzüğü dışında yüzük, bileklik ve kolye kullanılmaz. d) Pantolon kemerine veya palaskaya cep telefonu, gözlük, çakı takımı, sigaralık vb. aksesuar/malzeme takılmaz. (...) e) Bina ve müştemilatı ile araç dışında, görevin özelliğine göre şapka, kep, bere veya örgü başlık giyilmesi zorunludur. (...) f) Araç içinde resmî kıyafetli olarak yolculuk yaparken şapka çıkarılabilir. g) Resmî kıyafet ütülü, gömlek üst düğmesi ilikli ve kravat (...) ortalamış şekilde kullanılır. (...) ı) (...) resmî kıyafetler sivil kıyafete dönüştürülerek kullanılamaz. (...) m) Kadın rütbeli personel, hamileliğini belgelediği takdirde sivil kıyafet ile görev yapabilir. (...) o) (...) ilişiği kesildiği tarihten itibaren resmî kıyafetini çıkarmaya mecburdur. ö) El, yüz ve saç tuvaletlerinde sadelik esastır. (...)",
  "Hizmet Esasları Yön m.17": "(1) Esas duruş, rütbeli personel ve erlerin ruhen ve bedenen olgunluk ve göreve hazırlık derecesini gösterir ve günlük görevlerin her safhasında aranır. (2) Âmir veya üst, astın veya astların bulunduğu yere gelir ise derhal ayağa kalkılır ve esas duruşa geçilir. Âmir otur veya rahat komutunu vermeden esas duruş bozulmaz. (...) (5) Esas duruşta sessiz kalınır ve aksi emredilmedikçe kımıldanılmaz. (...) (7) Devlet memurları esas duruşa geçmez. Ancak amirleri karşısında saygılı bir duruş sergilemek zorundadır.",
  "Hizmet Esasları Yön m.18": "(1) Selam ve selamlama; saygının, sevginin, birlik ve beraberliğin, aidiyet duygusunun, içtenlik ve bağlılığın bir sembolü ve göstergesidir. Küçüğün büyüğü selamlaması saygının, büyüğün küçüğü selamlaması sevginin, aynı seviyede olanların birbirini selamlaması ise nezaket ve muhabbetin belirtisidir. (...) (3) Astlar, üstlerden önce selam vermek zorundadır. (...) Üst veya âmir selamlamayı bitirmeden ast selamlamayı bitiremez. (...) (5) Selamlama gecikmiş bile olsa yapılır, görmemek mazeret teşkil etmez. (...) (8) Elle selamlama, başta şapka, kayık kep, bere, kar başlığı, çelik/fiber başlık bulunduğunda ve sağ el ile yapılır. (...) (16) Devlet memurları selamlama ile ilgili hususlardan muaftır. Ancak, amirlerine karşı saygılı duruşunu muhafaza etmekle mükelleftir.",
  "Hizmet Esasları Yön m.19": "(4) Her personelde bulunması lazım gelen ahlaki ve manevi vasıflar şunlardır: a) Cumhuriyete, yurda ve millete karşı sevgi ve bağlılık (...) b) İtaat: Mevzuat ile emirlerin gösterdiğinden dışarı çıkmamak ve yasak edilen şeyleri yapmamaktır. c) Sebat ve mukavemet (...) ç) Cesaret ve şecaat (...) Korkaklık; personel için en büyük ve affedilmeyecek kusurdur. d) Canını esirgememek (...) e) Göreve hazırlık (...) f) İyi geçinmek (...) g) İyi ahlâk sahibi olmak (...) ğ) Sır saklamak (...) h) Emel ve fikir birliği (...) ı) Birbirine yardım (...) i) Tavır ve hareket (...) j) İntizam severlik: Personel, görevini muntazam işleyen bir saat gibi dakikası dakikasına yapmayı adet haline getirmelidir. k) Temsil ve tanıtım (...)",
  "Hizmet Esasları Yön m.22": "(1) Personel, tek başına veya topluca bildiri dağıtamaz, kamu görevleri hakkında basına, haber ajanslarına, radyo ve televizyon kurumlarına veya diğer iletişim kanallarına bilgi, yazı ve demeç veremez. Bu konuda gerekli bilgi ancak illerde valiler ve Bakanın yetkili kılacağı görevli tarafından verilebilir. (2) Personel, görevi gereği öğrendiği veya edindiği kişisel bilgi veya belgeleri yetkisiz kişilerle paylaşamaz (...). (4) Personel, gazete ve dergilere, internet ve sosyal medya vasıtalarına iç ve dış siyaset hakkında yazı yazamaz, Hükümet ve meslek aleyhinde tenkitte bulunamaz (...). (5) Personel, siyaset hariç olmak üzere, özellikle bilimsel, tarihi, iktisadi, içtimai, edebi bir zemin üzerinde gazete ve dergilere makaleler göndermekte (...) serbesttir.",
  "Hizmet Esasları Yön m.23": "(1) Birden fazla birliğin aynı kışla içinde bulunduğu yerlerde en kıdemli birlik komutanı, karargâh veya kurum âmiri kışla komutanıdır. (2) Kışla Komutanının görevleri şunlardır: a) Birliklerin sınırlarını ve sorumluluk alanlarını ayırır ve birliklere bildirir. (...) b) Emniyet, intizam ve disiplin bakımından gereken tedbirleri alır. (...) c) Yasak edilen malzemelerin kışlaya sokulmasını engeller. ç) Müşterek görevlerin icrasını planlar ve uygular. (...) ğ) Kışlaya giriş ve çıkışların kontrollü yapılmasını sağlar. (...)",
  "Hizmet Esasları Yön m.24": "(1) Jandarma Genel Komutanlığı, Sahil Güvenlik Komutanlığı, Jandarma ve Sahil Güvenlik Akademisinde görevli subay, sözleşmeli subay, astsubay, sözleşmeli astsubay ve uzman jandarmaların haftalık çalışma süresi genel olarak 40 saattir. Bu durum, görevin gerektirdiği durumlarda, rütbeli personelin görev yerine çağrılmasına veya görev yerinden ayrılmamasına engel teşkil etmez. (2) Günün yirmi dört saatinde devamlılık gösteren görevlerde çalışan rütbeli personelin çalışma saat ve şekilleri birlik komutanları veya birim âmirlerince belirlenir. (3) Nöbetçi ve görevli olmayan (...) günlük mesai veya eğitimin bitiminde görev yerinden ayrılabilir. Ancak nöbete ilişkin hükümler saklıdır.",
  "Hizmet Esasları Yön m.26": "MADDE 26 - (1) Birliklerdeki müşterek görevlerin yapılmasını ve devamını, bu görevlerin belli bir sıra ve süreyle; personel tarafından yerine getirilmesini sağlamak maksadıyla nöbet görevi ihdas edilir. (...) MADDE 27 - (1) Hâl ve vaziyetin gerektirdiği zamanlarda, birlik emniyetini sağlamak amacıyla, her birlik ve karargâhta derhal kullanılmak üzere rütbeli personel ve erlerden oluşan bir hazır kıt'a bulundurulur. (2) Hazır kıt'a kendisine gösterilen yerde gece dahi tam teçhizatlı, silahlı ve giyimli olarak harekete hazır bulunur. (...) (3) Hazır kıt'anın teşkil edileceği zaman ve kuvveti ihtiyaca göre birlik komutanı belirler. Bu kıt'anın kuvveti en az üç kişiden birliğin tamamına kadar olabilir. (...)",
  "Hizmet Esasları Yön m.34": "MADDE 34 - (1) Bu Yönetmelik onaylandığı tarihte yürürlüğe girer. MADDE 35 - (1) Bu Yönetmelik hükümleri Bakan tarafından yürütülür.",
  "Hizmet Esasları Yön m.5": "(1) Personel, her durumda Devletin menfaatlerini korumak mecburiyetindedir. Türkiye Cumhuriyeti Anayasasına ve kanunlarına aykırı olan, memleketin bağımsızlığını ve bütünlüğünü bozan, Türkiye Cumhuriyetinin güvenliğini tehlikeye düşüren herhangi bir faaliyette bulunamaz. (2) Personel, ettiği yemine uygun hareket etmek zorundadır. Personel, yetkili âmirlerin huzurunda mevzuatta belirtildiği şekilde ant içerek göreve başlar. (...)",
  "Hizmet Esasları Yön m.6": "(1) Subaylar, diğer rütbeli personelin üstüdür. (2) Astsubaylar, subayların astı diğer rütbeli personelin üstüdür. (3) Uzman jandarmalar, subay ve astsubayların astı, diğer rütbeli personelin üstüdür. (4) Uzman erbaşlar, subay, astsubay ve uzman jandarmaların astı, emsal rütbedeki sözleşmeli erbaşların ve 7179 sayılı Kanuna göre askerlik yükümlüsü olan emsal rütbedeki erbaşların üstüdür. (5) Sözleşmeli erbaşlar, (...) emsal rütbedeki uzman erbaşların astı, 7179 sayılı Kanuna göre askerlik yükümlüsü olan emsal rütbedeki erbaşların üstüdür. (6) Devlet memurları ile rütbeli personel arasında bir astlık-üstlük ilişkisi bulunmamakla birlikte (...) amir-maiyet ilişkisi vardır.",
  "Hizmet Esasları Yön m.7": "(1) Disiplin, Jandarma Genel Komutanlığı, Sahil Güvenlik Komutanlığı, Jandarma ve Sahil Güvenlik Akademisinin temelidir ve hiçbir suretle disiplinden taviz verilemez. (2) Personel görevini yerine getirirken ast-üst ve amir-maiyet ilişkisi içerisinde hareket etmekten, görev, nöbet, selamlama, kılık ve kıyafet gibi disiplinin ayrılmaz unsurlarına ilişkin mevzuat hükümlerine, disiplin kurallarına ve emirlere uymak zorundadır. (...) (7) Disiplin, en zor zamanlarda bile uygulanacak şekilde tesis edilmelidir. (...) (10) Sevk ve idarede otoritenin, öncelikle bilgi, yetenek ve yüksek bir karakter ile sağlanması esastır.",
  "Hizmet Esasları Yön m.8": "(1) Ast, âmir ve üstlerine genel görgü ve disiplin kurallarına uygun tam bir saygı göstermekle, resmî kıyafetli olsun veya olmasın âmirlerinin, usulüne uygun emirlerini tam, zamanında, değiştirmeden ve eksiksiz olarak yerine getirmekle, görevini kusursuz icra etmekle (...) yükümlüdür. (2) Görevini; korku ile değil, sevgi ve üstün görev anlayışı ile icra eder. Âmirin mevzuata uygun şekilde verdiği her emri mutlak itaat anlayışıyla, bütün tahammül kuvvetini sarf ederek yapar. (...) (5) Aldığı bir emirden dolayı âmirine mütalâada bulunmaz. Bir emri alırken veya aldıktan sonra mırıldanmaz, doğru bulmadığını sezdirecek hal ve harekette bulunmaz. (...) (14) Devlet memurları bu maddede maiyete yüklenen görevleri yapar.",
  "Hizmet Esasları Yön m.9": "(1) Tüm görevleri mevzuata uygun, zamanında ve eksiksiz yapar veya yaptırır, disiplini tesis ve idame eder, maiyetini yetiştirir, hal ve hareketlerini takip ve kontrol eder. (2) Maiyetinin sağlık, özlük ve sosyal haklarını sürekli gözetir. (...) (5) Astlarına karşı adil ve hakkaniyetli hareket eder. Hiçbir mazeret, hukuk ve adaletten ayrılmaya gerekçe gösterilemez. (...) (7) Görevine sadakati, gayreti, dürüstlüğü, güzel ahlâkı, tecrübesi ve hukuk kurallarına riayeti ile astlarına örnek olur. (...) (10) Maiyetinin katlandığı her türlü zahmet ve mahrumiyete, fiziki imkân nispetinde beraber katlanır, bir kolaylık çıkınca bunlardan istifade için nefsini sona bırakır ve bir zorluk çıkınca bilâkis öne atılmayı şerefli bir görev kabul eder.",
  "İl İdaresi m.11": "A) Vali, il sınırları içinde bulunan genel ve özel bütün kolluk kuvvet ve teşkilatının amiridir. Suç işlenmesini önlemek, kamu düzen ve güvenini korumak için gereken tedbirleri alır. Bu maksatla Devletin genel ve özel kolluk kuvvetlerini istihdam eder, bu teşkilat amir ve memurları vali tarafından verilen emirleri derhal yerine getirmekle yükümlüdür.\n\nVali, kamu düzeni veya güvenliğinin olağan hayatı durduracak veya kesintiye uğratacak şekilde bozulduğu ya da bozulacağına ilişkin ciddi belirtilerin bulunduğu hâllerde on beş günü geçmemek üzere ildeki belirli yerlere girişi ve çıkışı kamu düzeni ya da kamu güvenliğini bozabileceği şüphesi bulunan kişiler için sınırlayabilir; belli yerlerde veya saatlerde kişilerin dolaşmalarını, toplanmalarını, araçların seyirlerini düzenleyebilir veya kısıtlayabilir ve ruhsatlı da olsa her çeşit silah ve merminin taşınması ve naklini yasaklayabilir.\n\nD) Valiler, ilde çıkabilecek veya çıkan olayların, emrindeki kuvvetlerle önlenmesini mümkün görmedikleri veya önleyemedikleri; aldıkları tedbirlerin bu kuvvetlerle uygulanmasını mümkün görmedikleri veya uygulayamadıkları takdirde, diğer illerin kolluk kuvvetleriyle bu iş için tahsis edilen diğer kuvvetlerden yararlanmak amacıyla, İçişleri Bakanlığından ve gerekirse (…) Kara Kuvvetleri Komutanlığının sınır birlikleri dahil olmak üzere en yakın kara, deniz ve hava birlik komutanlığından mümkün olan en hızlı vasıtalar ile müracaat ederek yardım isterler. (...) Valinin yaptığı yardım istemi geciktirilmeksizin yerine getirilir. Acil durumlarda bu istek sonradan yazılı şekle dönüştürülmek kaydıyla sözlü olarak yapılabilir.\n\nF) Valiler, halkın askerlik muameleleri hakkındaki müracaat ve şikayetlerini kabul ederler. Askerlik şubelerine ve dairelerine yazarlar. Cevabı kafi görmedikleri takdirde askerlik şubelerinin bağlı bulunduğu bölge, tümen veya korkomutanlıklarına ve Milli Savunma Bakanlığına müracaat ederler. Bu makamlar tarafından lazımgelen soruşturma yapılarak kanuni gereği ifa edilir ve sonucundan valilere bilgi verilir.\n\nG) Vali, lüzumu hâlinde, kolluk amir ve memurlarına suç faillerinin bulunması için gereken emirleri verebilir. Kolluk bu emirleri, mevzuatta belirlenen usule uygun olarak yerine getirir. H) Vali, kamu düzenini ve güvenliğini veya kişilerin can ve mal emniyetini sağlamak amacıyla aldığı tedbir ve kararların uygulanması için adli kuruluşlar ile (D) fıkrası hükmü saklı kalmak kaydıyla askeri kuruluşlar dışında, mahalli idareler dâhil bütün kamu kurum ve kuruluşlarının itfaiye, ambulans, çekici, iş makinesi ve tedbirlerin zorunlu kıldığı diğer araç ve gereçlerinden yararlanabilir, personeline görev verebilir. Kamu kurum ve kuruluşları, valinin bu konudaki emir ve talimatlarını yerine getirmek zorundadır. Aksi takdirde vali, emir ve talimatlarını kolluk aracılığıyla uygular. (...) I) (H) fıkrası ile valiye verilmiş olan yetkiler, ilçede kaymakam tarafından da kullanılabilir.\n\nJ) Genel kolluk kuvvetlerinin imkân ve kabiliyetlerini aşan durumlarda terörle mücadele için gerekli olması veya terör eylemlerinin kamu düzenini ciddi şekilde bozması hâlinde, İçişleri Bakanlığının teklifi üzerine Cumhurbaşkanı kararıyla Türk Silahlı Kuvvetleri görevlendirilebilir. Cumhurbaşkanı kararında; görevin kapsam ve süresi, görev alanı, istihbarat yetkisinin kapsamı, destek silahlarının kullanımına yönelik tahditler, görevlendirilen birliklerin mülki amirler ve genel kolluk kuvvetleri ile ilişkileri (...) gösterilir. (...) Askeri birliklerin belirli görevleri genel kolluk kuvvetleriyle birlikte yapması hâlinde komuta, sevk ve idare askeri birliklerin en kıdemli komutanı tarafından üstlenilir. (...) gecikmesinde sakınca bulunan hallerde güvenlik kuvvetlerinin elinden kaçmakta olan kişilerin izlenirken girdikleri konuta, işyerine veya kamuya açık olmayan kapalı alanlar ile bunların eklentilerine (...) yetkili birlik komutanının yazılı emriyle girilebilir. Birlik komutanının kararı yirmi dört saat içinde hâkim onayına sunulur.",
  "İl İdaresi m.18": "Valiler, vali muavini ile kaymakamların, il idare şube başkanlarının ve il ve bölge muhakemat müdürlerinin, genel ve özel kolluk amirlerinin birinci derecede, diğer memurların ikinci derecede sicil amiridirler.",
  "İl İdaresi m.2": "İl, ilçe ve bucak kurulması, kaldırılması, adlarının, bağlılıklarının, merkez ve sınırlarının belirtilmesi ve değiştirilmesi aşağıda gösterilen şekilde yapılır: A) İl ve ilçe kurulması, kaldırılması, merkezlerinin belirtilmesi, adlarının değiştirilmesi, bir ilçenin başka bir il'e bağlanması kanun ile; B) Bucak kurulması, kaldırılması, merkezinin belirtilmesi, il ilçe ve bucak sınırlarının ve bucak adlarının değiştirilmesi bir köyün veya kasabanın veya bucağın başka bir il ve ilçeye bağlanması, mühim mevki ve tabii arazi adlarının değiştirilmesi Cumhurbaşkanı onayı ile; C) Yeniden köy kurulması veya yerinin değiştirilmesi Bayındırlık ve Sağlık ve Sosyal Yardım Bakanlıklarının mütalaası alınmak suretiyle; Ç) Köy ve kasabaların aynı ilçe içinde bir bucaktan başka bir bucağa bağlanması, köy adlarının değiştirilmesi, köylerin birleştirilmesi ve ayrılması, bir köy, mahalle veya semtin o köyden ayrılıp başka bir köy ile birleştirilmesi İçişleri Bakanlığının tasvibiyle yapılır.",
  "İl İdaresi m.27": "İlçe genel idaresinin başı ve mercii kaymakamdır. Kaymakam, ilçede Cumhurbaşkanının idari yürütme vasıtasıdır. İlçenin genel idaresinden kaymakam sorumludur. Bakanlıkların kuruluş mevzuatına göre ilçede lüzumu kadar teşkilatı bulunur. Bu teşkilat (Dördüncü maddenin son fıkrasında belirtilen adli ve askeri teşkilat hariç) kaymakamın emri altındadır.",
  "İl İdaresi m.31": "A) Kaymakam kanun, Cumhurbaşkanlığı kararnamesi ve diğer mevzuatın neşir ve ilanını, uygulanmasını sağlar ve bunların verdiği yetkileri kullanır ve ödevleri yerine getirir. Kaymakam, valinin talimat ve emirlerini yürütmekle ödevlidir; (...) I) (...) Kaymakam, ilçenin idare şube başkanlariyle ikinci derecedeki memurlarına, genel ve özel kolluk amir ve memurlarına Memurin Kanundaki usulüne göre savunmasını aldıktan sonra uyarma, kınama cezaları verir ve uygular. Daha ağır disiplin cezaları verilmesi için özel kanunu hükümlerine göre teklif ve talepte bulunabilir. Kaymakamlarca re'sen verilen cezalar kesindir. Bu cezalar tebliğ tarihinden itibaren sicile geçer. (...) J) Kaymakam, ilçe idare şube başkanlarına acele hallerde (8 güne kadar) ve tayini kendisine ait memurlara, Memurlar Kanunundaki yıllık izin, süresine mahsup edilmek üzere bir aya kadar izin verebilir.",
  "İl İdaresi m.32": "A) Kaymakam, ilçe sınırları içinde bulunan genel ve özel kolluk kuvvet ve teşkilatının amiridir; B) Suç işlenmesini önlemek, kamu düzen ve güvenini korumak için gereken tedbirleri alır. Bu maksatla Devletin genel ve özel kolluk kuvvetlerini istihdam eder. (...) Bu teşkilat amir ve memurları kaymakam tarafından verilen emirleri derhal yerine getirmekle ödevlidir; (...) D) Kaymakam, valinin tasvibiyle ilçe genel ve özel kolluk kuvvetleri mensuplarının geçici veya sürekli olarak yerlerini değiştirebilir; E) Kaymakam, ilçe çevresinde çıkabilecek olayların emrindeki kolluk kuvvetleriyle önlenmesine olanak bulunmayacağı kanısına varır veya ilçe içindeki kolluk kuvetleriyle önlenemeyecek olağanüstü ve ani olaylar karşısında kalırsa hemen valiye bilgi vererek yardım ister ve en yakın askeri (Kara, Deniz ve Hava) komutanlara da haber verir;",
  "İl İdaresi m.4": "İl genel idaresinin başı ve mercii validir. Bakanlıkların kuruluş mevzuatına göre illerde lüzumu kadar teşkilat bulunur. Bu teşkilatın her birinin başında bulunanlar il idare şube başkanlarıdır. Bunların emri altında çalışanlar ilin ikinci derecede memurlarıdır. Bu teşkilat valinin emri altındadır. Hakimler Kanunu ile İcra ve İflas Kanununda yazılı yargıç, Cumhuriyet savcısı ve yargıç sınıfında bulunanlarla bu kanunlarda yazılı adalet memurları, askeri birlikler, askeri fabrika ve müesseseler, askerlik daire ve şubeleri bu madde hükmünden müstesnadır.",
  "İl İdaresi m.42": "Bucak müdürü, bucakta en büyük Hükümet memuru ve temsilcisidir. Bu sıfatla; A) Bucağın genel idaresinden sorumludur; (...) E) Müdür, 4 üncü maddenin son fıkrasında belirtilen adli ve askeri teşkilat dışında kalan, gözetim ve teftişi altında bulunan bucak teşkilatına dahil daire ve müesseselerin amir ve memurları ile genel ve özel kolluk amir ve memurlarına Memurin Kanunundaki usulüne göre savunmalarını aldıktan sonra uyarma cezası verir ve uygular. Bu ceza kesindir ve tebliğ tarihinden itibaren sicile geçer. Daha ağır disiplin cezaIarı ile takdirname verilmesini gerektiren hallerde vali ve kaymakama tekliflerde bulunur. (...) [m.43] Bucağın güven ve düzeninin korunmasından bucak müdürü sorumludur. Suç işlenmesini önlemek için gereken tedbirleri alır ve uygular. Genel ve özel kolluk kuvvetleri bucak müdürünün emri altındadır. Bunlar müdürden aldıkları emri yerine getirmeye mecburdurlar.",
  "İl İdaresi m.57": "İl idare kurulu, valinin başkanlığı altında hukuk işleri müdürü, defterdar, milli egitim, bayındırlık, sağlık ve sosyal yardım, tarım ve veteriner müdürlerinden teşekkül eder. Vali, idare kuruluna başkanlık etmek üzere vali muavinini görevlendirebilir.",
  "İl İdaresi m.58": "İlçe idare kurulu, kaymakamın başkanlığı altında tahrirat katibi, malmüdürü, Hükümet hekimi, milli eğitim memuriyle tarım memuru ve veterinerden teşekkül eder.\n\nVali; sivil hava meydanları, limanlar ve sınır kapılarında, güvenliğin sağlanması, giriş-çıkışlarla ilgili görev ve hizmetlerin düzenli ve etkili bir biçimde yürütülmesi, görevli kuruluşlar arasında işbirliği ve koordinasyonun gerçekleştirilmesi için gerekli önlemleri almaya ve uygulamaya, kuruluşların çalışmalarını denetlemeye yetkilidir. İçişleri Bakanlığının uygun göreceği bu yerlerde vali tarafından mülki idare amiri görevlendirilir. Vali, yetkilerinin tamamını veya bir kısmını görevlendirdiği mülki idare amirine devredebilir. Bu yerlerde hizmet veren kuruluşlar, görevli mülki idare amirine karşı sorumludur.",
  "İl İdaresi m.66": "İl genel kurulu veya idare kurulları yahut en büyük mülkiye amirleri tarafından kanunların verdiği yetkiye istinaden ittihaz ve usulen tebliğ veya ilan olunan karar ve tedbirlerin tatbik ve icrasına muhalefet eden veya müşkülat gösterenler veya riayet etmeyenler, mahallî mülkî amir tarafından Kabahatler Kanununun 32 nci maddesi hükmü uyarınca cezalandırılır. (Ek cümle: 27/3/2015 - 6638/16 md.) Ancak, kamu düzenini ve güvenliğini veya kişilerin can ve mal emniyetini tehlikeye düşürecek toplumsal olayların baş göstermesi hâlinde vali tarafından kamu düzenini sağlamak amacıyla alınan ve usulüne göre ilan olunan karar ve tedbirlere aykırı davrananlar, üç aydan bir yıla kadar hapis cezasıyla cezalandırılır.",
  "İl İdaresi m.8": "Yetiştirme ve ikmal kaynakları Bakanlıklar veya tüzel kişiliği haiz genel müdürlüklere bağlı olup il genel teşkilatı içinde birden fazla istihdam yerleri bulunan meslek, fen ve uzmanlık kadrolarına dahil görevlerden: A) İlçe idare şube başkanı sıfatını haiz olanlarla il merkezinde Devlet gelir, giderlerinin ve mallarının tahakkuk, tahsil, ödeme ve idaresiyle ilgili ikinci derecedeki müdürler, şube şefleri ve kontrol memurları, nakit muhasipleriyle, lise, orta ve o derecelerdeki okul müdür ve öğretmenleri, hastaneler mütehassıs hekimleri, Bakanlıklar veya tüzelkişiliği haiz genel müdürlükler tarafından tayin edilirler. B) Bunun dışında kalan bütün memurlar Bakanlıklar veya tüzelkişiliği haiz genel müdürlükler tarafından valilik emrine tayin edilerek il idare şube başkanının inhası üzerine valiler tarafından istihdam yerleri tesbit olunur; C) Yukardaki fıkralarda yazılı bütün memurların lüzumu halinde il içinde nakil ve tahvilleri mensup olduğu il idare şube başkanlarının inhası üzerine valiler tarafından icra edilmekle beraber mensup oldukları Bakanlıklar veya genel müdürlüklere sebepleriyle bildirilir. Yukarda (A, B) fıkraları dışında kalan il merkez teşkilatına bağlı memurlar ilgili idare şube başkanının inhası ile valiler tarafından tayin, nakil ve tahvil olunurlar.",
  "İl İdaresi m.9": "Vali, ilde Cumhurbaşkanının temsilcisi ve idari yürütme vasıtasıdır. Bu sıfatla: A) Valiler, ilin genel idaresinden Cumhurbaşkanına karşı sorumludur. Cumhurbaşkanı yardımcıları ve bakanlar, görevlerine ait işleri için valilere re'sen emir ve talimat verirler. (...) Ç) Kanun, Cumhurbaşkanlığı kararnamesi ve diğer mevzuatın verdiği yetkiyi kullanmak ve bunların yüklediği ödevleri yerine getirmek için valiler genel emirler çıkarabilir ve bunları ilan ederler.",
  "İzin Yön m.10": "MADDE 10- (1) (...) a) Hizmet yapamayacak şekilde hastalanan personelin hastalığı geçici ise (...) hastanelerde geçen teşhis ve tedavi süreleri hariç, (...) toplam olarak ve fiilen iki yılı geçmemek üzere, nekahet tedavisi, istirahat ve hava değişimi işlemine tabi tutulur. (...) b) Kanser, her türlü kötü huylu tümör, verem, kronik böbrek yetmezliği ile akıl ve ruh hastalıkları gibi uzun süreli bir tedaviye ihtiyaç gösteren hastalığa yakalananlar, (...) toplam olarak ve fiilen üç yılı geçmemek şartı ile tedavi, istirahat veya hava değişimine tabi tutulabilirler. c) Sağlık durumundan dolayı \"Yurdun alçak veya alçak mutedil bölgelerinde faal görev yapar\" veya \"Muayyen bölgelere gidemez\" şeklinde iklim değiştirme raporları alanlar (...) bu durumlardaki sıhhi izin süreleri dört yıl olarak hesaplanır.\n\nMADDE 10- (1) d) Kadın personele doğum yapmasından önce sekiz hafta ve doğum yaptığı tarihten itibaren sekiz hafta olmak üzere toplam on altı hafta süre ile aylıklı izin verilir. (...) 1) Çoğul gebelik halinde, doğum öncesi sekiz haftalık izin süresine iki hafta süre eklenir. 2) Beklenen doğum tarihinden sekiz hafta öncesinden, sağlık durumunun uygun olduğu doktor raporu ile belgelenen personel, isterse doğumdan önceki üç haftaya kadar iş yerinde çalışabilir. (...) e) Doğum yapan personele çocuklarını emzirmeleri için aylıklı izin süresinin bitim tarihinden itibaren ilk altı ayda günde üç saat, ikinci altı ayda günde bir buçuk saat süt izni verilir. f) Doğum yapan personele, aylıklı izinlerinin bitiminden itibaren başlamak üzere istekleri üzerine on iki aya kadar aylıksız izin verilir.",
  "İzin Yön m.11": "MADDE 11- (1) (...) a) İçişleri Bakanlığınca; 1) Öğrenim için öğrenim süresi kadar, 2) Meslekî bilgi ve görgüsünü artırmak maksadıyla bir yıla kadar, 3) Seminer, müşahede gezisi ve ziyaretler için lüzumlu görülen süre kadar, 4) Mazeret dolayısıyla yıllık izinle birlikte üç aya kadar, 5) Seyahat maksadıyla yurt dışına gidecek personele, yıllık izin süresi kadar, yurt dışı izni verilebilir. (...) c) Yurt dışı izin verme yetkisi İçişleri Bakanlığınca devredilebilir. Yetki devri hâllerinde, verilen yurt dışı izinleri yetki devri yapan makama bildirilir.",
  "İzin Yön m.12": "MADDE 12- (1) (...) öğrenim amacıyla, öğrenim süresi kadar yurt dışı izni verilebilir. Bu iznin verilebilmesi için, öğrenim görülecek kurumun en az üniversite, akademi veya bunların eşiti düzeyde öğrenim/eğitim veren bir kurum olması, alınacak öğrenim/eğitimin lisansüstü düzeyde, personelin mesleği ile ilgili bir konu olması (...) şarttır. (2) (...) a) Müracaat tarihi itibarıyla bulunduğu statüde beşinci hizmet yılını tamamlamış, on ikinci hizmet yılını tamamlamamış olmak. (...) (3) Bu madde gereğince izin verilecek personel miktarı, her statüdeki personel mevcudunun binde birini geçemez.",
  "İzin Yön m.16": "MADDE 16- (1) (...) seyahat maksadı ile izin sıra cetveline tabi olarak yurt dışına izinli gidebilirler. (2) Bu madde gereğince verilecek izin, personelin yıllık izinlerinden sayılır ve otuz günü geçemez. (3) İzne gidecek personele, kullanılan ulaşım vasıtası da dikkate alınarak ayrıca yol izni verilebilir. Yol izni süresi toplam dört günü geçemez. (...) (4) c) Yurt dışı izin müracaatı, asgari alay ve eşiti birimlerin amirlerince izin tarihinden en az otuz gün önce, Jandarma Genel Komutanlığı Personel Başkanlığında hazır bulundurulur. (...) f) Seyahat maksadıyla aynı anda yurt dışında izinli bulunan personel sayısı statülerine göre mevcutlarının yüzde birini geçemez.",
  "İzin Yön m.18": "MADDE 18- (1) Mesleki bilgi ve görgünün artırılması, öğrenim, seminer, müşahede gezisi ve ziyaretler için verilecek yurt dışı izinleri ile yabancı memleketlerde görevlendirilen personelde (...) aşağıdaki şartlar aranır: a) Sicil notu ortalaması, sicil tam notunun yüzde 93'ü ve üzerinde olmak. b) İzinli gidilecek yabancı ülkenin dilinden (...) son iki yıl içerisinde ÖSYM tarafından yapılan yabancı dil sınavı (YDS/E-YDS) (...) yüz tam puan üzerinden en az seksen beş not almış olmak. (...) f) (...) başvuru tarihinden itibaren geriye doğru son beş yıl içinde, toplamda on iki ay veya daha fazla durdurma cezası almamış olmak.",
  "İzin Yön m.20": "MADDE 20- (1) İzinli olarak yurt dışında bulunan subay, sözleşmeli subay, astsubay, sözleşmeli astsubay, uzman jandarma ve uzman erbaşlar; a) Milletimizin ve Jandarma Genel Komutanlığının birer temsilcisi olarak gerek resmî gerekse özel hayatlarını Türk Jandarmasına yaraşır bir şekilde düzenlemek zorundadır. b) Yurt dışındaki Türk Silahlı Kuvvetleri, Sahil Güvenlik Komutanlığı ile yabancı askeri ve kolluk personeline karşı tavır ve hareketlerinde meslekî vakar ve ananeyi muhafaza eder. c) Yabancılarla temasta daha titiz ve dikkatli davranır, resmî ve özel hayatlarında herhangi bir olumsuz olaya sebebiyet vermemek için özen gösterir. ç) Mevzuat ve malî imkânlarına göre uygun bir meskende ve meslekî şerefe uygun bir şekilde yaşamak zorundadır. d) Zorunlu olmadıkça üniforma giyemez. e) Seyahat maksadıyla yurt dışına giden personel şahsi, zati ve miri silahını götüremez. (2) Yurt dışına izinli gidecek personele bağlı bulunduğu birlik, karargâh ve kurum amirlikleri ve komutanlıkları tarafından, yurt dışındaki hareket tarzları hakkında, istihbarata karşı koyma ve koruyucu güvenlik önlemleri konularında uyarıcı bilgiler verilir. (3) İzinli olarak yurt dışında bulunan personel, Jandarma Genel Komutanlığınca belirlenen istihbarata karşı koyma ve koruyucu güvenlik esaslarına uyar.",
  "İzin Yön m.22": "MADDE 20- (1) (...) d) Zorunlu olmadıkça üniforma giyemez. e) Seyahat maksadıyla yurt dışına giden personel şahsi, zati ve miri silahını götüremez. MADDE 22- (1) İzinli olarak yurt dışına gönderilen personelden, aşağıda sayılanlar derhal yurda çağrılırlar. Geri çağırma yetkisi onay veren makama aittir. (...) a) Vatandaşlık ve memurluk şeref ve haysiyetini zedeleyecek hareketlerde bulunanlar. (...) ç) İznin maksadına aykırı hareket edenler. d) Gerçeğe aykırı beyanda bulunarak amirlerini ve izin işlemini yapan makamları aldatanlar.",
  "İzin Yön m.5": "MADDE 5- (1) Personelin izin işlemleri aşağıdaki genel esaslar dâhilinde yürütülür. a) Personele verilecek izinler şunlardır: 1) Yıllık izin. 2) Mazeret izinleri. 3) Sıhhi izinler. 4) Yurt dışı izinleri. (...) g) Savaş ve olağanüstü hallerde 2803 sayılı Kanunun ek 3 üncü maddesi uyarınca izin süreleri kısaltılabilir veya kaldırılabilir. Bu hâllerde, personel izinden geriye çağrılabilir. (...) i) Yurt dışında izinde bulunup, yurda dönme kararı kendisine tebliğ edilen personel, 48 saat içerisinde, en kısa yoldan ve en seri vasıta ile dönüşe geçer. (...) j) Personel görev yaptığı ilin dışına izinsiz çıkamaz.",
  "İzin Yön m.6": "MADDE 6- (1) (...) a) Personelin her yıl otuz gün yıllık izin hakkı vardır. Bu müddete yol dâhil değildir. Ayrıca kısa süreli mazeretlerde kullanılmak üzere on beş güne kadar yıllık mazeret izni verilebilir. (...) ç) Personelin yıllık mazeret izin talebinin izin vermeye yetkili amiri tarafından uygun görülmesi durumunda, yıllık iznini kullanmamış olsa dahi, öncelikli olarak yıllık mazeret izni verilir. (...) i) (...) Aynı yıl içinde kullanılabilecek yıllık izin süresi hiçbir suretle toplam altmış günü geçemez.\n\nMADDE 6- (1) c) Yıllık izinlerin; personelin talebi, birlik görevleri ve personel mevcudu dikkate alınarak, yirmi ve on günlük olarak iki defada kullandırılması esastır. Haziran, Temmuz, Ağustos ve Eylül aylarında kullanılacak yıllık izin süresi en fazla yirmi gün olarak planlanır. Ancak yıllık izinler, uygun olduğu takdirde, izin sıra çizelgesini onaylayan makamın yetkisinde iznin tamamı bir seferde veya birkaç defada verilebilecek şekilde planlanabilir. (...) f) Yıllık izinlerini kullanan personelin gidiş ve dönüşlerinde bir defaya mahsus olmak üzere, (...) iki günden az olmamak kaydıyla dört güne kadar yol izni verilir. (...) ğ) Aynı anda izin kullanacak personel sayısının, birimin genel mevcudunun yüzde 25'ini geçmemesi (...) esastır.",
  "İzin Yön m.8": "MADDE 7- (2) Jandarma Bölge Komutanlığı ve il jandarma komutanlığı personelinin izin sıra çizelgeleri vali tarafından, ilçe jandarma komutanlığı personelinin izin sıra çizelgeleri kaymakam tarafından onaylanır. (4) İzin sıra çizelgesi, her yıl Kasım ayı sonuna kadar onay makamında bulundurulur. (...) 15 Aralık tarihine kadar personele tebliğ edilir. MADDE 8- (1) Yıllık izinler ve yıllık mazeret izinleri; a) Jandarma Genel Komutanı için İçişleri Bakanı, b) Jandarma Genel Komutanı Yardımcıları için Jandarma Genel Komutanı, (...) d) Jandarma bölge komutanları ve il jandarma komutanları için konuşlu bulunduğu ilin valisi, e) İlçe jandarma komutanları için kaymakam, tarafından verilir.",
  "İzin Yön m.9": "MADDE 9- (1) Personele 6 ncı maddede yazılı on beş günlük yıllık mazeret izinleri dışında; a) Eşinin doğum yapması, eşinin ölümü, çocuğunun ölümü, kendisinin veya eşinin ana, baba veya kardeşinin ölümü hallerinin her birinde isteği üzerine on güne kadar; kendisinin veya çocuğunun evlenmesi halinde isteği üzerine yedi güne kadar mazeret izni verilebilir. Bu bentte yazılı izinler ertelenemez veya devredilemez. b) Yangın, deprem, su baskını gibi olağanüstü bir mazeret dolayısıyla bir yıl içinde otuz güne kadar mazeret izni verilebilir. c) Hizmetleri sırasında radyoaktif ışınlarla çalışan personele her yıl, yıllık izinlerinden ayrı olarak, otuz gün izin verilir. Bu izin bölünemez, yıl geçişlerinde üst üste kullanılamaz ve diğer yıla aktarılamaz. (...) (3) Bu madde kapsamında verilen mazeret izinleri yıllık izne mahsup edilmez.\n\nMADDE 9- (1) d) Bakmakla yükümlü olduğu veya refakat etmediği takdirde hayatı tehlikeye girecek anne, baba, eş ve çocukları ile kardeşlerinden birinin ağır bir kaza geçirmesi veya tedavisi uzun süren önemli bir hastalığa tutulmuş olması hâllerinde, bu hâllerin sağlık kurulu raporuyla belgelendirilmesi şartıyla, istekleri üzerine, aylık ve özlük hakları korunarak üç aya kadar izin verilebilir. Gerektiğinde bu süre bir katına kadar uzatılır. Bu sürenin bitimini müteakip istekleri üzerine ayrıca altı aya kadar aylıksız izin verilebilir. (...) 3) Aynı kişi ve aynı vakaya dayalı olarak verilecek refakat izninin aylıklı ve aylıksız toplam süresi on iki ayı geçemez.",
  "Jandarma Kanunu m.12": "Madde 12 – (Değişik: 25/7/2016-KHK-668/12 md.; Aynen kabul: 8/11/2016-6755/12 md.)\nLüzum görüldüğü hallerde İçişleri Bakanı tarafından, Emniyet Genel Müdürlüğü, Sahil Güvenlik Komutanlığı ve Jandarma Genel Komutanlığı arasında her kademedeki personel, geçici olarak görevlendirilebilir. İçişleri Bakanı bu yetkisini il valilerine devredebilir.\nAyrıca, İçişleri Bakanının onayıyla; Emniyet Genel Müdürlüğü, Sahil Güvenlik Komutanlığı ve Jandarma Genel Komutanlığı silah, mühimmat, teçhizat, taşıt ve diğer taşınırları ile taşınmazlarını birbirlerine geçici olarak tahsis edebilirler veya bedelsiz olarak devredebilirler.\nBu maddenin uygulanmasına ilişkin usul ve esaslar İçişleri Bakanlığınca yürürlüğe konulan yönetmelikle belirlenir.",
  "Jandarma Kanunu m.14": "Madde 14 – (Değişik birinci fıkra: 2/7/2018 – KHK/703/128 md.) Jandarma Genel Komutanı, Genel Komutan Yardımcıları, generaller, bölge ve il jandarma komutanları dışında kalanlar İçişleri Bakanınca yapılır.",
  "Jandarma Kanunu m.15": "Madde 15 – Disiplin ve soruşturma usulleri:\n\nMadde 15 – (Değişik: 25/7/2016-KHK-668/15 md.; Aynen kabul: 8/11/2016-6755/15 md.)\nJandarma personeli hakkında disiplin ve soruşturma işlemleri aşağıdaki usullere göre yapılır.\na) Disiplin işleri özel kanun hükümlerine göre yürütülür.\nb) Jandarma personelinin mülki görevlerinden doğan suçlarında; özel kanunların hükümleri saklı kalmak şartıyla 2/12/1999 tarihli ve 4483 sayılı Memurlar ve Diğer Kamu Görevlilerinin Yargılanması Hakkında Kanun hükümlerine göre işlem yapılır.\nc) Adli görevlerinden doğan suçlarda; 4/12/2004 tarihli ve 5271 sayılı Ceza Muhakemesi Kanununun 161 inci maddesinin beşinci fıkrası hükmü uygulanır.\nd) (Değişik: 2/7/2018 – KHK/703/128 md.) Jandarma personeline askeri görev verildiği takdirde bu görevlerden doğan suçların muhakemesi, Jandarma personelinin emrine verildiği askeri birlik personelini muhakeme etmekle görevli ve yetkili olan mahkemede görülür.\ne) Jandarma personelinin kişisel suçlarında genel hükümlere göre işlem yapılır.\n(Ek fıkra: 15/8/2017/KHK-694/55 md.; Aynen kabul: 1/2/2018-7078/52 md.) Ertelenmiş, seçenek yaptırımlara çevrilmiş, hükmün açıklanmasının geri bırakılmasına karar verilmiş, affa uğramış veya 26/9/2004 tarihli ve 5237 sayılı Türk Ceza Kanununun 53 üncü maddesinde belirtilen süreler geçmiş olsa bile; Devletin güvenliğine karşı suçlar, Anayasal düzene ve bu düzenin işleyişine karşı suçlar, milli savunmaya karşı suçlar, Devlet sırlarına karşı suçlar ve casusluk, zimmet, irtikâp, rüşvet, iftira, hırsızlık, dolandırıcılık, sahtecilik, güveni kötüye kullanma, hileli iflas, ihaleye fesat karıştırma, edimin ifasına fesat karıştırma, suçtan kaynaklanan malvarlığı değerlerini aklama veya kaçakçılık suçlarından ya da kasten işlenen bir suçtan dolayı bir yıl veya daha fazla süreyle hapis cezasına mahkûm olan Jandarma Genel Komutanlığında görevli subay, astsubay ve uzman jandarmaların Komutanlıkla ilişikleri İçişleri Bakanının onayı ile kesilir.\n\nMadde 15/A- (Ek: 25/7/2018-7145/6 md.) Erbaş ve erlerin üst ve eşyalarının aranması\nTehlikenin veya suç işlenmesinin önlenmesi amacıyla usulüne göre verilmiş sulh ceza hâkimi kararı veya bu sebeplere bağlı olarak gecikmesinde sakınca bulunan hâllerde yirmi dört saat içinde görevli hâkimin onayına sunulması şartıyla birlik komutanının veya kurum amirinin yazılı emri üzerine, jandarma hizmet binaları ve eklentilerinde, askerlik yükümlülüğünü yerine getiren erbaş ve erlerin üstü, özel kâğıtları ve eşyası aranır, gerekli tedbirler alınır, suç delilleri koruma altına alınarak 5271 sayılı Kanun hükümlerine göre gerekli işlemler yapılır.\nArama talep yazısında, arama için makul sebeplerin oluştuğunun, gerekçeleriyle birlikte gösterilmesi gerekir. Arama kararında veya emrinde; aramanın sebebi, konusu ve kapsamı ile yapılacağı yer, zaman ve geçerli olacağı süre belirtilir.\nAramanın sonucu, arama kararı veya emri veren merci veya makama bir tutanakla bildirilir.\nKonutta ve yerleşim yerinde ve eklentilerinde önleme araması yapılamaz.\nBu maddenin uygulanmasına ilişkin usul ve esaslar İçişleri Bakanlığı tarafından çıkarılan yönetmelikle düzenlenir.",
  "Jandarma Kanunu m.18": "Madde 18 – Jandarma Genel Komutanlığının bütçesi, İçişleri Bakanlığının bünyesinde ve bu Bakanlığın bütçesinden ayrı olarak düzenlenir.",
  "Jandarma Kanunu m.19": "Madde 19 – (Değişik: 25/7/2016-KHK-668/16 md.; Değiştirilerek kabul: 8/11/2016-6755/16 md.) Jandarma Genel Komutanlığı ikmal hizmetleriyle faaliyetlerine ait her türlü ihtiyacını ve silah ve mühimmatını İçişleri Bakanlığınca belirlenecek standartlara uygun olarak kendi bütçesinden karşılar. Ancak Jandarma Genel Komutanlığı, Savunma Sanayi Destekleme Fonundan Türk Silahlı Kuvvetlerinin tabi olduğu usul ve esaslar dahilinde yararlanır. Jandarma Genel Komutanlığının ihtiyaçları, İçişleri Bakanlığı tarafından Savunma Sanayii Müsteşarlığına doğrudan teklif edilir. Bu ihtiyaçlar İçişleri Bakanlığının güvenlik önceliklerine göre değerlendirilir. Seferberlik ve savaş hallerinde Kuvvet Komutanlıkları emrine girecek veya İçişleri Bakanı ya da valilerce askeri görev verilen jandarma birliklerinin her türlü ihtiyacı (sefer stokları dahil) emrine gireceği Kuvvet Komutanlıklarının standartlarına uygun olarak Milli Savunma Bakanlığınca sağlanır. (Ek fıkra: 2/1/2017-KHK-680/45 md.; Aynen kabul: 1/2/2018-7072/44 md.) Jandarma Genel Komutanlığının ihtiyaç fazlası ve standart dışı malzemelerinin bedelli veya bedelsiz devir işlemleri 12/4/2001 tarihli ve 4645 sayılı Emniyet Genel Müdürlüğüne Ait Araç, Gereç, Mal ve Malzemenin Satış, Hibe, Hek ve Hurda Durum ve İşlemleri ile Hizmet Satışına Dair Kanun hükümlerine göre yürütülür. Ayrıca, Jandarma Genel Komutanlığı, 30/5/1985 tarihli ve 3212 sayılı Silahlı Kuvvetler İhtiyaç Fazlası Mal ve Hizmetlerinin Satış, Hibe, Devir ve Elden Çıkarılması; Diğer Devletler Adına Yurt Dışı ve Yurt İçi Alımların Yapılması ve Eğitim Görecek Yabancı Personel Hakkında Kanun kapsamında Türk Silahlı Kuvvetlerinin yararlandığı hak ve imkânlardan aynen yararlanır. (Ek fıkra: 17/4/2017-KHK-690/21 md.; Aynen kabul: 1/2/2018-7077/18 md.) Bütçe kanunları ve diğer kanunlarla Milli Savunma Bakanlığı ile Türk Silahlı Kuvvetlerine tanınan gümrük, her türlü vergi, resim, harç ve ardiye ücretlerine ilişkin muafiyet ve istisna hükümleri Jandarma Genel Komutanlığı hakkında da uygulanır.",
  "Jandarma Kanunu m.20": "Madde 20 – Jandarma Genel Komutanlığı personeli; bu Kanunla getirilen hakların yanısıra, özlük hakları bakımından, 926 sayılı \\\"Türk Silahlı Kuvvetleri Personel Kanunu\\\", 657 sayılı \\\"Devlet Memurları Kanunu\\\" ile genel ve özel düzenleme getiren diğer kanunlarla verilen haklardan da yararlanır.",
  "Jandarma Kanunu m.21": "Madde 21 – (Değişik: 13/7/1993 – KHK – 486/18 md.)\nJandarma Genel Komutanlığı fiili kadrolarına atanmış subay, astsubay ve uzman jandarma ve uzman erbaşlara; 657 sayılı Devlet Memurları Kanununda belirtilen en yüksek Devlet memuru aylığının (ek gösterge dahil);\na) Komando ve sınır birliklerinde % 52,\nb) Diğer karargah, birlik ve kurumlarda % 40,\ntutarını geçmemek üzere İçişleri Bakanlığınca belirlenecek usul ve esaslara göre fazla çalışma karşılığı asayiş tazminatı ödenir. Bu tazminattan damga vergisi hariç herhangi bir vergi ve kesinti yapılmaz.",
  "Jandarma Kanunu m.22": "Madde 22 – Uzman jandarmaların hizmet süreleri, giyim, kuşam, beslenme usulleri ve diğer özlük hakları ile erbaş ve erlerin kaynakları, hizmet süreleri, kıyafetleri özel kanunlarında gösterildiği gibidir.",
  "Jandarma Kanunu m.24": "Madde 24 – (Değişik: 27/5/2016-KHK-668/17 md.; Aynen kabul: 8/11/2016-6755/17 md.) Bu Kanunla münhasıran yönetmelik çıkarılması öngörülen hususların yanısıra jandarmanın teşkilat, görev, yetki ve sorumlulukları, diğer makamlarla ilişkileri, birlikte çalışma ve işbirliği esasları dahil komuta ve kontrol ilişkileri ile Jandarma (…) personelinin terfi işleri, değerlendirme, ödüllendirme, kılık ve kıyafet ve Kanunun uygulanmasına ilişkin diğer hususlar; Cumhurbaşkanınca yürürlüğe konulan yönetmelikle düzenlenir.",
  "Jandarma Kanunu m.26": "Yürürlük:\nMadde 26 – Bu Kanun yayımı tarihinde yürürlüğe girer.",
  "Jandarma Kanunu m.4": "Madde 4 – (Değişik: 25/7/2016-KHK-668/6 md.; Aynen kabul: 8/11/2016-6755/6 md.)\nJandarma Genel Komutanlığı İçişleri Bakanlığına bağlıdır.",
  "Jandarma Kanunu m.5": "Madde 5 – (Değişik: 25/7/2016-KHK-668/7 md. ; Değiştirilerek kabul: 8/11/2016-6755/7 md.)\nJandarma Genel Komutanlığının kuruluş ve kadrolarıyla konuş yerleri, İçişleri Bakanlığınca düzenlenir. Ancak seferberlik ve savaşta Kuvvet Komutanlıkları emrine girecek birliklerin kuruluş ve kadrolarıyla konuş yerlerinin düzenlenmesinde Genelkurmay Başkanlığının görüşü alınır.\nJandarma birliklerinin kuruluş ve konuşlarının düzenlenmesinde mülki taksimat esas alınır. Ancak geçici olarak birden çok ili içine alan bölge teşkilatı da kurulabilir. Bölge komutanı, bölge teşkilatının konuşlu bulunduğu ilin valisine karşı sorumlu olarak görev yapar.",
  "Jandarma Kanunu m.6": "Madde 6 – (Değişik: 25/7/2016-KHK-668/8 md. ; Aynen kabul: 8/11/2016-6755/8 md.)\nJandarma Genel Komutanı tüm Jandarma Teşkilatının komutanıdır. (Mülga ikinci cümle: 2/7/2018 - KHK/703/128 md.)\nJandarma Genel Komutanı, Teşkilatın sevk ve idaresinden, kanun ve nizam hükümlerinin icrasını sağlamaktan, bunlara dayalı olarak verilen emir ve kararların uygulanmasından sorumludur.",
  "Jandarma Kanunu m.7": "Jandarmanın genel olarak görevleri:\nMadde 7 – (Değişik: 25/7/2016-KHK-668/9 md.; Aynen kabul: 8/11/2016-6755/9 md.)\nJandarmanın sorumluluk alanlarında genel olarak görevleri şunlardır.\na) Mülki görevleri;\nEmniyet ve asayiş ile kamu düzenini sağlamak, korumak ve kollamak, kaçakçılığı men, takip ve tahkik etmek, suç işlenmesini önlemek için gerekli tedbirleri almak ve uygulamak, ceza infaz kurumları ve tutukevlerinin dış korunmalarını yapmak, (b) ve (c) bentlerinde belirtilen görevler dışında kalan ve diğer kanun ve nizam hükümlerinin icrası ile bunlara dayalı emir ve kararlarla Jandarmaya verilen görevleri yapmak.\nb) Adli görevleri;\nİşlenmiş suçlarla ilgili olarak kanunlarda belirtilen işlemleri yapmak ve bunlara ilişkin adli hizmetleri yerine getirmek.\nc) Askeri görevleri;\nKanunlarla ve Cumhurbaşkanlığı kararnameleriyle verilen askeri hizmetleri yerine getirmek.",
  "Jandarma Kanunu m.8": "Jandarmanın (…) seferberlik ve savaş halindeki görevleri:\nMadde 8 – (Değişik: 25/7/2016-KHK-668/10 md.; Değiştirilerek kabul: 8/11/2016-6755/10 md.)\nJandarma birlikleri; seferberlik ve savaş hallerinde, Cumhurbaşkanı kararıyla belirlenecek bölümleriyle Kuvvet Komutanlıkları emrine girer, kalan bölümüyle normal görevlerine devam eder.\nAyrıca, Jandarma birlikleri; Genelkurmay Başkanlığının talebi üzerine İçişleri Bakanının, illerde ise garnizon komutanının talep etmesi halinde valinin onayıyla kendilerine verilen askeri görevleri de yaparlar.",
  "Jandarma Kanunu m.9": "Madde 9 – Kanun ve nizamlar ile bunlara dayalı olarak verilen emir ve kararların öngörmediği hiçbir görev jandarmadan istenemez. (Mülga ikinci cümle: 26/3/2002-4748/7 md.)",
  "Jandarma Teşkilat Yön m.1": "MADDE 1- (1) Bu Yönetmeliğin amacı; jandarmanın teşkilat, görev, yetki ve sorumluluklarını, diğer makamlarla ilişkilerini, birlikte çalışma ve işbirliği esasları dahil komuta ve kontrol ilişkilerini düzenlemektir. MADDE 2- (1) Bu Yönetmelik, 10/3/1983 tarihli ve 2803 sayılı Jandarma Teşkilat, Görev ve Yetkileri Kanununun 24 üncü maddesine dayanılarak hazırlanmıştır.",
  "Jandarma Teşkilat Yön m.10": "MADDE 10- (2) (...) il ve ilçelerdeki jandarma ve polis sorumluluk alanlarının sınırları, ilçelerde kaymakam, illerde vali veya görevlendireceği vali yardımcısı başkanlığında jandarma ve emniyet temsilcilerinin katılacağı bir komisyon tarafından belirlenir. (...) Büyükşehir, il veya ilçe belediyesi kurulması, kaldırılması ya da kentleşme veya diğer sebeplerle sınırlarda değişiklik olması halinde, değişikliğin yürürlüğe girdiği tarihten itibaren en geç üç ay içerisinde sorumluluk alanları yeniden düzenlenir. (3) Komisyon tarafından alınan kararlar İçişleri Bakanının onayıyla yürürlüğe girer. (...) (4) Sorumluluk alanlarının sınırlarının belirlenmesinde kolluk birimleri arasındaki anlaşmazlıklar, mülki amir tarafından kesin olarak çözümlenir. (5) Sorumluluk alanını belirleyen karar doğrultusunda devir ve teslim ile ilgili işlemler en geç üç ay içerisinde tamamlanır.",
  "Jandarma Teşkilat Yön m.11": "MADDE 11- (1) Jandarma; a) Halkın can, ırz ve malını korur. b) Suç işlenmesini önlemek ve kamu düzenini sağlamak için gerekli önlemleri alır. c) Asayişi, kamunun ve kişilerin güvenliğini ve konut dokunulmazlığını korur. ç) Anayasada ve kanunlarda düzenlenen hak ve hürriyetlerin güvenli şekilde kullanılması için gerekli önlemleri alır. (...) e) Yardım isteyenlere, korunmaya muhtaç çocuklarla yardım gereken küçüklere, engelli, hasta, yaşlı kimselerle, düşkün ya da kimsesizlere ve yabancılara yardım eder. f) Her türlü kaçakçılığa engel olur. g) Ceza infaz kurumlarının dış korumalarını sağlayıcı önlemleri alır (...). ı) Trafik hizmetlerini yürütür (...).",
  "Jandarma Teşkilat Yön m.24": "MADDE 24- (1) Ceza infaz kurumlarının dış korunması jandarmaya aittir. (...) (2) Jandarma, ceza infaz kurumlarının dışarıdan emniyet ve koruma tedbirlerini almak, tutuklu ve hükümlülerin kaçmalarına engel olmakla görevlidir. Jandarmaların hükümlü ve tutuklularla görüşmeleri ve ilişki kurmaları, ceza infaz kurumlarının içindeki iş ve işlemlere karışmaları yasaktır. (...) (3) Jandarma hiçbir şekilde ceza infaz kurumlarının iç işlerinde ve infaz koruma memurluğu görevlerinde kullanılamaz.",
  "Jandarma Teşkilat Yön m.25": "MADDE 26- (1) Bir ceza infaz kurumundan diğer bir ceza infaz kurumuna gönderilmesi gereken tutuklu ve hükümlüler, kanunen yetkili makamın yazılı istemi üzerine, jandarma kuvvetlerince istenilen yere götürülürler. MADDE 27- (1) Hükümlü ve tutukluların sevk ve nakillerinin bu iş için ayrılmış olan ceza infaz kurumu araçlarıyla yapılması esastır. (...) (3) Jandarmaya ait hizmet araçları sevklerde kullanılmaz. MADDE 29- (1) İştirak halinde suç işlemiş olanlar ile kanunen önemli ilişki sayılacak derecede yakınlığı olanlar dışında; erkek ve kadın tutuklu ya da hükümlüler, birlikte sevk edilemez. (2) Sevk edilen tutuklu ve hükümlünün kadın olması durumunda, kadın ceza infaz koruma görevlisi verilir. MADDE 32- (1) (...) firara teşebbüs etmeleri durumunda firarın başka şekilde önlenmesine imkân bulunmazsa silah kullanılır. MADDE 33- (1) Sevk ve nakillerde, gidilecek yere gündüz varılacak biçimde hareket edilir.",
  "Jandarma Teşkilat Yön m.3": "a) Asayiş: Hukuka uygun ve gerekli önlemlerin alınması sonucu, Devlete, topluma, kişilere, mal ve eşyalara yönelik tehlike, kaza ve sabotajların söz konusu olmadığı bir ortamı, düzensizlik ve karışıklıkların önlendiği, hayatın normal akışının sağlandığı hali, dirlik ve düzenin varlığı konusunda kamuda oluşan yerleşik ve yaygın inancı, (...) d) Emniyet: Devlete, topluma, kişilere, mal ve eşyalara yönelik tehlike, kaza ve sabotajları önlemek için alınan hukuka uygun önlemlerin tümünü ve bu önlemlerin alınmış bulunduğu hali, (...) i) Kamu düzeni: Emniyet ve asayiş, huzur ve sükun, genel sağlık ve genel ahlak unsurlarından oluşan, hak ve hürriyetlerin tam olarak kullanımına elverişli ortamı, (...) ifade eder.\n\ne) Genel kolluk: Kamu düzeninin korunmasını sağlayan, mevzuatla verilen görevleri yerine getiren ve silah kullanma yetkisini haiz Bakanlığa bağlı jandarma, sahil güvenlik ve polisi, (...) j) Kapalı yerler: Konut, işyerleri ve eklentileri ile bunların dışında olsa bile zilyedinin rızası bulunmadıkça girilmemesi gerektiğini belirtir şekilde etrafı çit, parmaklık, duvar ve benzeri engellerle çevrili yerleri (...), l) Mülki amir: İllerde vali, ilçelerde kaymakamı, m) Özel kolluk: Devlet ve yetkili diğer kamu tüzel kişilerince, özel kanunlar çerçevesinde kurulup teşkilatlandırılan, kendi görev alanında güvenliği sağlamak amacı taşıyan ve jandarma, sahil güvenlik ve polis dışındaki kolluk birimlerini, ifade eder.",
  "Jandarma Teşkilat Yön m.39": "MADDE 39- (1) Ceza muhakemesine ilişkin olarak suçların soruşturulması ve kovuşturulmasına ilişkin hususlar, 5271 sayılı Kanunda öngörülen usul ve esaslara göre yürütülür. Adli görevler bakımından ilgili mevzuat ve adli amirlerin talimatlarına göre hareket edilir. MADDE 40- (1) Gözaltına alınan şahısların sadece adli makamlar önüne çıkarılıncaya kadarki yeme, içme ve nakil masrafları ile sevkin Jandarma Genel Komutanlığına ait taşıtlarla gerçekleştirilmesi durumunda, söz konusu taşıta ait yakıt ve benzeri masraflar Jandarma Genel Komutanlığı bütçesinden ödenir.",
  "Jandarma Teşkilat Yön m.4": "MADDE 4- (1) Jandarma Genel Komutanlığı Bakanlığa bağlıdır. Jandarma Genel Komutanı, Bakana karşı sorumludur.",
  "Jandarma Teşkilat Yön m.41": "MADDE 41- (1) Jandarma birlikleri; seferberlik ve savaş hallerinde, Bakanlar Kurulu kararıyla belirlenecek bölümleriyle kuvvet komutanlıkları emrine girer, kalan bölümüyle normal görevlerine devam eder. Jandarma, seferberlik ve savaş halinde, 4/11/1983 tarihli ve 2941 sayılı Seferberlik ve Savaş Hali Kanunu ile verilen görevleri yapar. (2) Jandarma birlikleri; Genelkurmay Başkanlığının talebi üzerine Bakanın, illerde ise garnizon komutanının talep etmesi halinde valinin onayıyla kendilerine verilen askeri görevleri de yapar (...).",
  "Jandarma Teşkilat Yön m.42": "MADDE 42- (1) Jandarma sorumluluk alanında, mülki ve adli görevlerinin ifası sırasında 2803 sayılı Kanun, 4/7/1934 tarihli ve 2559 sayılı Polis Vazife ve Salâhiyet Kanunu ve 5271 sayılı Kanun ile diğer mevzuat hükümlerine göre hareket eder. Jandarma bu görevlerini yerine getirirken polisin sahip olduğu yetki ve sorumluluklara sahiptir. (2) Jandarma amirinden aldığı emri Anayasa, kanun, tüzük ve yönetmelik hükümlerine aykırı görürse yerine getirmez ve bu aykırılığı emri verene bildirir. Ancak, amir emrinde ısrar eder ve bu emrini yazılı olarak tekrar ederse emir yerine getirilir. Bu halde, emri yerine getiren sorumlu olmaz. Konusu suç teşkil eden emir hiçbir suretle yerine getirilmez. Yerine getirenler sorumluluktan kurtulamaz. (...)\n\n(2) (...) Aşağıda yazılı hallerde; a) Can, ırz veya mal emniyetini korumak için, b) Devletin güvenliğine karşı işlenen suçların faillerini yakalamak veya delillerini tespit etmek için, (...) e) Kolluk kuvvetlerinin elinden kaçmakta olan şahısların yakalanması için, f) İşlenmekte olan bir suçun işlenmesine veya devamına mani olmak için, g) 5271 sayılı Kanun ile diğer kanunlar uyarınca kolluk kuvvetleri tarafından suç delillerinin tespiti veya suç faillerinin yakalanması maksadıyla yapılacak aramalar için, ğ) Kanunsuz toplantı veya kanunsuz yürüyüşleri dağıtmak veya failleri yakalamak için, (...) yetkili amir tarafından verilecek sözlü emirler derhal yerine getirilir. Bu emirlerin yazılı olarak verilmesi istenilemez. Bu hallerde emrin yerine getirilmesinden doğabilecek sorumluluk emri verene aittir. (...)",
  "Jandarma Teşkilat Yön m.46": "MADDE 46- (1) Jandarma, kişileri ve araçları; a) Bir suç veya kabahatin işlenmesini önlemek, b) Suç işlendikten sonra kaçan faillerin yakalanmasını sağlamak, işlenen suç veya kabahatlerin faillerinin kimliklerini tespit etmek, c) Hakkında yakalama emri ya da zorla getirme kararı verilmiş olan kişileri tespit etmek, ç) Kişilerin hayatı, vücut bütünlüğü veya malvarlığı bakımından ya da topluma yönelik mevcut veya muhtemel bir tehlikeyi önlemek, amacıyla durdurabilir. (2) Durdurma yetkisinin kullanılabilmesi için jandarmanın tecrübesine ve içinde bulunulan durumdan edindiği izlenime dayanan makul bir sebebin bulunması gerekir. Süreklilik arz edecek, fiili durum ve keyfilik oluşturacak şekilde durdurma işlemi yapılamaz. (...) (6) (...) Bu amaçla kişinin üzerindeki elbisenin çıkarılması veya aracın dışarıdan bakıldığında içerisi görünmeyen bölümlerinin açılması istenemez. Ancak el ile dıştan kontrol hariç, kişinin üstü ve eşyası ile aracının dışarıdan bakıldığında içerisi görünmeyen bölümlerinin aranması, Bakanlık tarafından belirlenen esaslar dahilinde mülki amirin görevlendireceği kolluk amirinin yazılı, acele hallerde sonradan yazıyla teyit edilmek üzere sözlü emriyle yapılabilir. Kolluk amirinin kararı yirmidört saat içinde görevli hakimin onayına sunulur. Bu fıkra kapsamında yapılan araç aramalarına ilişkin olarak kişiye, arama gerekçesini de içeren bir belge verilir. (...)",
  "Jandarma Teşkilat Yön m.47": "MADDE 47- (1) Jandarma, tehlikenin veya suç işlenmesinin önlenmesi amacıyla usulüne göre verilmiş sulh ceza hakiminin kararı veya bu sebeplere bağlı olarak gecikmesinde sakınca bulunan hallerde mülki amirin vereceği yazılı emirle kişilerin üstlerini, araçlarını, özel kağıtlarını ve eşyasını arar (...). (2) Arama talep yazısında, arama için makul sebeplerin oluştuğunun gerekçeleriyle birlikte gösterilmesi gerekir. (3) Arama kararında veya emrinde aşağıdaki hususlar belirtilir. a) Sebebi. b) Konusu ve kapsamı. c) Yapılacağı yer. ç) Yapılacağı zaman ve geçerli olacağı süre. (4) Önleme araması aşağıdaki yerlerde yapılabilir. a) (...) toplantı ve gösteri yürüyüşlerinin yapıldığı yerde veya yakın çevresinde. (...) c) Halkın topluca bulunduğu veya toplanabileceği yerlerde. (...) d) Umumi veya umuma açık yerlerde. e) Her türlü toplu taşıma araçları ile seyir halindeki taşıtlarda. (5) Konutta, yerleşim yerinde ve kamuya açık olmayan işyerlerinde ve eklentilerinde önleme araması yapılamaz. (6) Spor karşılaşması, miting, konser, festival, toplantı ve gösteri yürüyüşünün düzenlendiği veya aniden toplulukların oluştuğu hallerde gecikmesinde sakınca bulunan hal var sayılır.",
  "Jandarma Teşkilat Yön m.48": "MADDE 48- (1) Jandarma; a) İmdat istenmesi veya yangın, su baskını ve boğulma gibi büyük tehlikelerin haber verilmesi veya görülmesi hallerinde bu tehlikelerden kişileri kurtarmak amacıyla, b) Bir suçun işlenmesine veya işlenmekte olan bir suçun devamına engel olmak için, konutlara, işyerlerine ve eklentilerine girebilir.",
  "Jandarma Teşkilat Yön m.5": "MADDE 5- (1) Jandarma teşkilatı aşağıda belirtilen merkez ve taşra teşkilatı ile doğrudan merkeze bağlı birimlerden oluşur. a) Merkez teşkilatı (...) b) Taşra teşkilatı şunlardır: 1) Jandarma bölge komutanlıkları. 2) İl jandarma komutanlıkları. 3) İlçe jandarma komutanlıkları. (...) c) Doğrudan merkeze bağlı birimler (...) MADDE 6- (1) Jandarma birimlerinin konuşlarının düzenlenmesinde, mülki taksimat esas alınır. (...) Her düzeydeki jandarma birlikleri Bakan onayı ile kurulabilir. (...) (4) (...) İlçe jandarma komutanlıklarının sorumluluk alanı bir ya da birden çok karakol sorumluluk bölgesine ayrılabilir. (...) (7) Karakolların sorumluluk bölgeleri il jandarma komutanının önerisi üzerine valinin onayı, karakolların konuş yerleri ise Bakan onayı ile belirlenir. Geçici asayiş karakolları ile jandarma hizmet merkezleri, il jandarma komutanının önerisi üzerine valinin onayıyla teşkil edilir.",
  "Jandarma Teşkilat Yön m.52": "MADDE 52- (1) Jandarma Genel Komutanı, jandarma teşkilatının komutanıdır. (...) (3) Jandarma Genel Komutanı; teşkilatın sevk ve idaresinden (...) Bakana karşı sorumludur. MADDE 54- (1) Jandarma bölge komutanları (...) bölge komutanlığının konuşlu olduğu ilin valisinin onayıyla; terörle mücadele kapsamında operasyonları planlamak (...) görevlidir. (...) (2) (...) bölge komutanı (...) bölge komutanlığının konuşlu olduğu ilin valisine karşı sorumludur. MADDE 55- (1) İl jandarma komutanları, il jandarma teşkilatının komutanıdır. (...) MADDE 56- (1) İlçe jandarma komutanları, ilçe jandarma teşkilatının komutanıdır. (...) MADDE 57- (1) Jandarma karakol komutanları, karakolun komutanıdır.",
  "Jandarma Teşkilat Yön m.58": "MADDE 58- (1) Jandarma Genel Komutanlığı, Bakanlığa bağlıdır. Bakan, jandarma teşkilatının en üst amiridir ve teşkilatı idare eder. (...) (2) Jandarma bölge komutanları konuşlu olduğu ilin valisine, il ve ilçe jandarma komutanları ise mülki amirlere bağlı ve sorumlu olarak görev yapar. (3) Mülki amirler ile adli makamlar mevzuat hükümlerine uygun olarak jandarma komutanlarına ve diğer jandarma personeline doğrudan emir verme yetkisine sahiptir. Diğer makamlar jandarmaya görev olarak verilmesini istedikleri konunun kanuni dayanaklarını belirterek o yerin mülki amirine başvurur (...). (4) Jandarma birimleri, aldıkları görevin yürütülmesi bakımından, kendi amirlerinin emir komutası altında ve silsile esasına göre sevk ve idare edilir. (5) Emniyet ve asayiş görevlerinden doğrudan doğruya sorumlu olan mülki amir, bu görevlerin yürütülmesini jandarmanın sorumluluk alanında, jandarma aracılığıyla sağlar. (6) Jandarma birimlerindeki her kademedeki amir ve personel, görevlerini kanunlara uygun yürütmekten ve yetkilerini amaca uygun bir tarzda kullanmaktan, mülki amirlere karşı sorumludur. (7) Jandarma birimlerinin üstlendikleri görevin yapılmasında kullanacakları araç ve gereçlerin seçimi kendi komutanlarına aittir. Mülki amirler özellik taşıyan ve yetersiz kalınan durumlarda gereken araç ve gereçleri diğer kamu kurum ve kuruluşlarından sağlayarak jandarmanın hizmetine verebilir.",
  "Jandarma Teşkilat Yön m.59": "MADDE 59- (1) Jandarma; bölgelerindeki her türlü suçları ve sonuçlarını, ülkenin emniyet ve asayişini bozan ya da bozacak olan olayları, yangın, su baskını gibi afetleri, haber aldıkları salgın ve bulaşıcı hastalıkları, Devletin ülkesi ve milletiyle bölünmez bütünlüğünü, nitelikleri Anayasada gösterilen Cumhuriyeti yıkmaya, sarsmaya ve bölmeye yönelik propagandalar konusunda edindikleri bilgileri, il veya ilçenin asayiş veya güvenliğini etkileyecek mahiyetteki kovuşturma ve soruşturmaları, vakit geçirmeksizin mülki amire sözlü ya da yazılı olarak bildirir. Suçla ilgili görülen olaylar aynı zamanda Cumhuriyet savcılığına da bildirilir.",
  "Jandarma Teşkilat Yön m.60": "MADDE 60- (1) Jandarma Genel Komutanlığı merkez ve taşra teşkilatları birbirleriyle; mahalli vakalar hakkında malumat istemek ve teknik, muhasebe, lojistik ve özlük konularına dair işlemler haricinde resen muhabere edemez ve yazışma yapamaz. Taşra teşkilatının merkez teşkilatıyla, merkez teşkilatının taşra teşkilatıyla yapacağı yazışmalar Bakanlık ve mülki amirler aracılığı ile yapılır. Hak ve yükümlülük doğuran ve Bakanlık ya da Jandarma Genel Komutanlığı adına irade beyanı niteliği taşıyan yazışmalar, her halükarda valilikler aracılığıyla yapılır. (...) (4) Bakanlığa gönderilecek asayiş raporlarından jandarmanın sorumluluk alanında meydana gelen olaylara ait bulunanlar, il jandarma komutanlığınca hazırlanır ve vali imzasıyla gönderilir.",
  "Jandarma Teşkilat Yön m.61": "MADDE 61- (1) Jandarma, 5271 sayılı Kanun ve diğer mevzuatta yazılı soruşturma işlemlerine ilişkin görevleri yerine getirir, il ve ilçenin emniyet ve asayişini, genel hayatın akışını ilgilendiren olaylarda mülki amire bilgi verir. MADDE 62- (1) Adli kolluk makamları ile işbirliği Adlî Kolluk Yönetmeliğine göre yürütülür. MADDE 63- (1) İcra müdürlüklerinin talebi üzerine kolluk kuvvetleri tarafından yakalanan araçlar, en yakın yediemin otoparkına teslim edilerek en geç üç işgünü içinde en yakın icra müdürlüğüne teslim alınması için bildirimde bulunulur. MADDE 64- (1) Jandarmanın askeri makamlarla ilişkisi 8 inci ve 41 inci maddelerde belirtilen hallerle sınırlıdır.",
  "Jandarma Teşkilat Yön m.65": "MADDE 65- (1) Jandarma sorumluluk alanında herhangi bir suçla karşılaşan sahil güvenlik veya polis, olaya müdahale etmek ve jandarmaya da haber vermek, jandarmanın istemi üzerine gerekli yardımı yapmakla yükümlüdür. Bu gibi durumlarda, sahil güvenlik ve polis, jandarma gelinceye kadar olay yerinde soruşturma yapamaz, durumu olduğu gibi koruyarak delillerin kaybolmaması için gereken önlemleri alır. (...) (2) Zorunlu durumlarda, jandarma da sahil güvenlik veya polis sorumluluk alanında birinci fıkradaki hükümlere uygun olarak hareket eder. (...) (6) Jandarma, sahil güvenlik ve polisin birlikte çalışmalarına gerek duyulan durumlarda, operasyona katılan birimlerin komuta, sevk ve idaresinin hangi kolluk kuvvetine ait olduğu mülki amir tarafından belirlenir.",
  "Jandarma Teşkilat Yön m.7": "MADDE 7- (1) Jandarmanın genel olarak görev ve sorumluluk alanı, polis ve sahil güvenlik teşkilatının görev alanının dışı olup, bu alanlar il ve ilçe belediye sınırları dışında kalan ya da polis ve sahil güvenlik teşkilatı bulunmayan yerlerdir. Ancak, belediye sınırları içinde olmakla birlikte, hizmet gerekleri bakımından uygun görülen yerler, jandarmanın görev ve sorumluluk alanı olarak belirlenebilir. Bakanın kararıyla bir il veya ilçenin tamamı polis ya da jandarma görev ve sorumluluk alanı olarak belirlenebilir.",
  "Jandarma Teşkilat Yön m.70": "MADDE 70- (1) Jandarma birimlerinde, emniyet ve asayişle ilgili görev alan personelin resmi kıyafet ile görev yapmaları esastır. Ancak suç ve suçluların gizli olarak takibi (...) için gerek görüldüğünde mülki amirin veya il jandarma komutanının izni ile görevin icap ettirdiği değişik kılık ve kıyafetle de hizmet yürütülebilir. MADDE 71- (1) (...) jandarma, sahil güvenlik ve emniyet teşkilatı, kendi sorumluluk alanında yetersiz kaldıkları takdirde (...) geçici bir süre için birbirlerinin sorumluluk alanlarında görevlendirilebilirler. Bu görev hiç bir zaman süreklilik taşımaz (...). (2) Bu madde kapsamındaki görevlendirmeler mülki amirin onayı ile yapılır. MADDE 72- (2) Görevlendirilen ekiplerin kolluk yetkilerini kullanması, jandarma sorumluluk alanı ile sınırlı değildir. (...) MADDE 73- (1) Bakanın onayı ile; Jandarma Genel Komutanlığı, Sahil Güvenlik Komutanlığı ve Emniyet Genel Müdürlüğü silah, mühimmat, teçhizat, taşıt ve diğer taşınırları ile taşınmazlarını birbirlerine geçici olarak tahsis edebilirler veya bedelsiz olarak devredebilirler.",
  "Jandarma Teşkilat Yön m.74": "MADDE 74- (1) Yoklama kaçakları ve bakayalar, askerlik ödevlerini yerine getirmek maksadıyla yakalanmaları için Millî Savunma Bakanlığınca Bakanlığa, askerlik şubelerince de mülki amire bildirilirler. Yakalanarak muhafaza altına alınan yükümlüler, vakit geçirmeksizin ve en geç yirmidört saat içerisinde en yakın askerlik şubesine getirilirler. Askerlik şubesince teslim alınamayan yükümlüler, jandarma tarafından hazırlanan tutanağa istinaden derhal serbest bırakılırlar. (2) Firar, izin veya hava değişimi tecavüzünde olan yükümlülerden haklarında adli makamlarca çıkarılmış yakalama kararları olanlar, ele geçirilinceye kadar jandarma tarafından aranır.",
  "Jandarma Teşkilat Yön m.75": "MADDE 75- (1) Jandarma birimleri, emniyet ve asayiş ile kamu düzeninin korunmasını sağlamak ve olaylara etkili biçimde müdahale edebilmek amacıyla suçları önleme ve suçlara müdahale planı, doğal afet ve yardım planı ile koruma ve müdahale harekat planı hazırlar. (3) Planlar, mülki amirin onayı ile yürürlüğe konulur. (4) Planların birer örneği; mülki amirlikler, jandarma, sahil güvenlik ve polisin ilgili birimlerinde saklanır ve Jandarma Genel Komutanlığına gönderilir.",
  "Jandarma Teşkilat Yön m.76": "MADDE 76- (1) Jandarma teşkilatının (...) hedeflerinin belirlenmesi için hazırlanan ve beş yıllık bir dönemi kapsayan Jandarma Genel Komutanlığı stratejik hedef planı Bakan onayı ile yürürlüğe konulur. Bu plan en az iki yılda bir gözden geçirilir.",
  "Jandarma Teşkilat Yön m.80": "MADDE 80- (1) 3/11/1983 tarihli ve 83/7362 sayılı Bakanlar Kurulu Kararı ile yürürlüğe konulan Jandarma Teşkilatı Görev ve Yetkileri Yönetmeliği yürürlükten kaldırılmıştır. (2) (...) İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmeliğin 39 uncu maddesinin birinci fıkrası (...) değiştirilmiştir.",
  "Jandarma Teşkilat Yön m.9": "MADDE 9- (1) Jandarma sorumluluk alanı dışında olmakla birlikte; a) Polis teşkilatı kurulmamış olması nedeniyle, b) Özel kolluk kuruluşlarının sorumluluk alanına giren yerlerde, jandarmayı ilgilendiren ihlal ya da suç işlenmesi nedeniyle, c) Özel kolluk kuruluşlarının sorumluluk alanına giren konularda, bu kuruluş ve kuvvetlerin yokluğundan ötürü meydana gelen ihlal ya da suçlar nedeniyle, jandarmanın görevlendirilmesi ya da kendiliğinden olaya elkoyması mümkündür. Bu gibi durumlarda jandarmanın görev yaptığı o yer, jandarmanın görev alanı sayılır. (2) Kamu ve özel hukuk tüzel kişilerine ait kurum ve kuruluşların, kendi tesis ve yapılarının iç güvenliğinin sağlanması, bu kurum ve kuruluşlarca kendi mevzuatına göre yürütülür. Özel hallerde, geçici olarak koruma ve kollama görevi verilmesi hususunda mülki amirin yetkisi saklıdır.",
  "Kabahatler m.1": "(1) Bu Kanunda; toplum düzenini, genel ahlâkı, genel sağlığı, çevreyi ve ekonomik düzeni korumak amacıyla; a) Kabahatlere ilişkin genel ilkeler, b) Kabahatler karşılığında uygulanabilecek olan idarî yaptırımların türleri ve sonuçları, c) Kabahatler dolayısıyla karar alma süreci, d) İdarî yaptırıma ilişkin kararlara karşı kanun yolu, e) İdarî yaptırım kararlarının yerine getirilmesine ilişkin esaslar, belirlenmiş ve çeşitli kabahatler tanımlanmıştır.",
  "Kabahatler m.11": "(1) Fiili işlediği sırada onbeş yaşını doldurmamış çocuk hakkında idarî para cezası uygulanamaz.\n\n(2) Akıl hastalığı nedeniyle, işlediği fiilin hukukî anlam ve sonuçlarını algılayamayan veya bu fiille ilgili olarak davranışlarını yönlendirme yeteneği önemli derecede azalmış olan kişi hakkında idarî para cezası uygulanmaz.",
  "Kabahatler m.13": "(1) Kabahate teşebbüs cezalandırılmaz. Ancak, teşebbüsün de cezalandırılabileceğine dair ilgili kanunda hüküm bulunan haller saklıdır. Bu durumda, Türk Ceza Kanununun suça teşebbüse ve gönüllü vazgeçmeye ilişkin hükümleri, kabahatler bakımından da uygulanır.",
  "Kabahatler m.14": "(1) Kabahatin işlenişine birden fazla kişinin iştirak etmesi halinde bu kişilerin her biri hakkında, fail olarak idarî para cezası verilir.\n(2) Özel faillik niteliğinin arandığı durumlarda, kabahate iştirak eden ve bu niteliği taşımayan kişi hakkında da fail olarak idarî para cezası verilir.\n(3) Kabahate iştirak için kasten ve hukuka aykırı işlenmiş bir fiilin varlığı yeterlidir...\n(4) Kanunda özel faillik niteliğini taşıyan kişi açısından suç, diğer kişiler açısından kabahat olarak tanımlanan fiilin... ortaklaşa işlenmesi halinde suça iştirake ilişkin hükümler uygulanır.",
  "Kabahatler m.15": "(1) Bir fiil ile birden fazla kabahatin işlenmesi halinde bu kabahatlere ilişkin tanımlarda sadece idarî para cezası öngörülmüşse, en ağır idarî para cezası verilir. Bu kabahatlerle ilgili olarak kanunda idarî para cezasından başka idarî yaptırımlar da öngörülmüş ise, bu yaptırımların her birinin uygulanmasına karar verilir.\n\n(2) Aynı kabahatin birden fazla işlenmesi halinde her bir kabahatle ilgili olarak ayrı ayrı idarî para cezası verilir. Kesintisiz fiille işlenebilen kabahatlerde, bu nedenle idarî yaptırım kararı verilinceye kadar fiil tek sayılır.\n\n(3) Bir fiil hem kabahat hem de suç olarak tanımlanmış ise, sadece suçtan dolayı yaptırım uygulanabilir. Ancak, suçtan dolayı yaptırım uygulanamayan hallerde kabahat dolayısıyla yaptırım uygulanır.",
  "Kabahatler m.16": "(1) Kabahatler karşılığında uygulanacak olan idarî yaptırımlar, idarî para cezası ve idarî tedbirlerden ibarettir.\n(2) İdarî tedbirler, mülkiyetin kamuya geçirilmesi ve ilgili kanunlarda yer alan diğer tedbirlerdir.",
  "Kabahatler m.17": "(1) İdarî para cezası, maktu veya nispi olabilir.\n\n(2) İdarî para cezası, kanunda alt ve üst sınırı gösterilmek suretiyle de belirlenebilir. Bu durumda, idarî para cezasının miktarı belirlenirken işlenen kabahatin haksızlık içeriği ile failin kusuru ve ekonomik durumu birlikte göz önünde bulundurulur.\n\n(3) ... Cumhuriyet başsavcılıkları ve mahkemeler tarafından verilen idarî para cezaları Genel Bütçeye gelir kaydedilir. Sosyal güvenlik kurumları ile mahalli idareler tarafından verilen idarî para cezaları kendi bütçelerine gelir kaydedilir. ... Kişinin ekonomik durumunun müsait olmaması halinde, idarî para cezasının, ilk taksitinin peşin ödenmesi koşuluyla, bir yıl içinde ve dört eşit taksit halinde ödenmesine karar verilebilir. Taksitlerin zamanında ve tam olarak ödenmemesi halinde, idarî para cezasının kalan kısmının tamamı tahsil edilir.\n\n(6) Kabahat dolayısıyla idarî para cezası veren kamu görevlisi, ilgilinin rıza göstermesi halinde bunun tahsilatını derhal kendisi gerçekleştirir. Kanunlarında ödeme süresi düzenlenmemiş olan idari para cezaları, tebliğinden itibaren bir ay içinde ödenir.\n\n(6) ... İdari para cezasının ödeme süresi içinde ödenmesi halinde, cezadan %25 oranında indirim yapılır. Ödeme yapılması, kişinin bu karara karşı kanun yoluna başvurma hakkını etkilemez.\n\n(7) İdarî para cezaları her takvim yılı başından geçerli olmak üzere o yıl için ... yeniden değerleme oranında artırılarak uygulanır. ... Bu fıkra hükmü, nispi nitelikteki idarî para cezaları açısından uygulanmaz.",
  "Kabahatler m.18": "(1) Kabahatin konusunu oluşturan veya işlenmesi suretiyle elde edilen eşyanın mülkiyetinin kamuya geçirilmesine, ancak kanunda açık hüküm bulunan hallerde karar verilebilir.\n(4) Eşyanın mülkiyeti, kanunda açık hüküm bulunan hallerde ilgili kamu kurum ve kuruluşuna, aksi takdirde Devlete geçer.\n(7) Mülkiyeti kamuya geçirilen eşya, başka suretle değerlendirilmesi mümkün olmazsa imha edilir.\n\n(2) Mülkiyetin kamuya geçirilmesine ilişkin karar, eşyanın; a) Kullanılmaz hale getirilmesi, b) Niteliğinin değiştirilmesi, c) Ancak belli bir surette kullanılması koşullarından birinin yerine getirilmesine bağlı olarak belli bir süre geciktirilebilir...\n\n(5) Eşyanın mülkiyetinin kamuya geçirilmesine karar verilebilmesi için fail hakkında idarî para cezası veya başka bir idarî yaptırım kararı verilmiş olması şart değildir.\n\n(6) Kaim değerin mülkiyetinin kamuya geçirilmesine de karar verilebilir.",
  "Kabahatler m.2": "(1) Kabahat deyiminden; kanunun, karşılığında idarî yaptırım uygulanmasını öngördüğü haksızlık anlaşılır.",
  "Kabahatler m.20": "(1) Soruşturma zamanaşımının dolması halinde kabahatten dolayı kişi hakkında idarî para cezasına karar verilemez.\n(2) Soruşturma zamanaşımı süresi; a) Yüzbin Türk Lirası veya daha fazla idarî para cezasını gerektiren kabahatlerde beş, b) Ellibin Türk Lirası veya daha fazla cezayı gerektiren kabahatlerde dört, c) Ellibin Türk Lirasından az cezayı gerektiren kabahatlerde üç yıldır. Ancak, 1111 Askerlik, 2839 Milletvekili Seçimi, 2918 Karayolları Trafik, 2972, 3376, 4925, 5490 ve 6001 sayılı kanunlarda belirtilen ve idari para cezasını gerektiren fiilin işlendiği tarihi takip eden takvim yılının son günü bitimine kadar idari para cezası verilerek tebliğ edilmediği takdirde idari yaptırım kararı verilemez, verilmiş olanlar düşer.\n(3) Nispî idarî para cezasını gerektiren kabahatlerde zamanaşımı süresi sekiz yıldır.\n(4) Zamanaşımı süresi, kabahate ilişkin tanımdaki fiilin işlenmesiyle veya neticenin gerçekleşmesiyle işlemeye başlar.\n(5) Kabahati oluşturan fiilin aynı zamanda suç oluşturması halinde suça ilişkin dava zamanaşımı hükümleri uygulanır.",
  "Kabahatler m.21": "(1) Yerine getirme zamanaşımının dolması halinde idarî para cezasına veya mülkiyetin kamuya geçirilmesine ilişkin karar artık yerine getirilemez.\n(2) Yerine getirme zamanaşımı süresi; a) Ellibin Türk Lirası veya daha fazla cezaya karar verilmesi halinde yedi, b) Yirmibin Türk Lirası veya daha fazla cezada beş, c) Onbin Türk Lirası veya daha fazla cezada dört, d) Onbin Türk Lirasından az cezada üç yıldır.\n(3) Mülkiyetin kamuya geçirilmesine ilişkin zamanaşımı süresi on yıldır.\n(4) Zamanaşımı süresi, kararın kesinleşmesinin rastladığı takvim yılını takip eden takvim yılı başından itibaren işlemeye başlar.\n(5) Kanun hükmü gereği olarak idarî yaptırımın yerine getirilmesine başlanamaması veya yerine getirilememesi halinde zamanaşımı işlemez (durur).",
  "Kabahatler m.22": "(1) Kabahat dolayısıyla idarî yaptırım kararı vermeye ilgili kanunda açıkça gösterilen idarî kurul, makam veya kamu görevlileri yetkilidir.\n(2) Kanunda açık hüküm bulunmayan hallerde ilgili kamu kurum ve kuruluşunun en üst amiri bu konuda yetkilidir.",
  "Kabahatler m.23": "(1) Cumhuriyet savcısı, kanunda açıkça hüküm bulunan hallerde bir kabahat dolayısıyla idarî yaptırım kararı vermeye yetkilidir.\n(2) Bir suç dolayısıyla başlatılan soruşturma kapsamında bir kabahatin işlendiğini öğrenmesi halinde Cumhuriyet savcısı durumu ilgili kamu kurum ve kuruluşuna bildirebileceği gibi, kendisi de idarî yaptırım kararı verebilir.",
  "Kabahatler m.24": "(1) Kovuşturma konusu fiilin kabahat oluşturduğunun anlaşılması halinde mahkeme tarafından idarî yaptırım kararı verilir.",
  "Kabahatler m.25": "(1) İdarî yaptırım kararına ilişkin tutanakta; a) Hakkında idarî yaptırım kararı verilen kişinin kimlik ve adresi, b) İdarî yaptırım kararı verilmesini gerektiren kabahat fiili, c) Bu fiilin işlendiğini ispata yarayacak bütün deliller, d) Karar tarihi ve kararı veren kamu görevlilerinin kimliği, açık bir şekilde yazılır. Tutanakta, ayrıca kabahati oluşturan fiil, işlendiği yer ve zaman gösterilerek açıklanır.\n\n(1) ... (Tuzak kartı — yukarıdaki m.25/1 unsurları üzerinden, listede olmayan bir unsur sorulur.)",
  "Kabahatler m.26": "(1) İdarî yaptırım kararı, 7201 sayılı Tebligat Kanunu hükümlerine göre ilgili kişiye tebliğ edilir...\n(4) İdari yaptırım kararları ... elektronik ortamda tebliğ edilebilir. Elektronik ortamda yapılan tebligat, muhatabın elektronik adresine ulaştığı tarihi izleyen beşinci günün sonunda yapılmış sayılır.",
  "Kabahatler m.27": "(1) İdarî para cezası ve mülkiyetin kamuya geçirilmesine ilişkin idarî yaptırım kararına karşı, kararın tebliği veya tefhimi tarihinden itibaren en geç onbeş gün içinde, sulh ceza mahkemesine başvurulabilir. Bu süre içinde başvurunun yapılmamış olması halinde idarî yaptırım kararı kesinleşir.\n\n(2) Mücbir sebebin varlığı dolayısıyla bu sürenin geçirilmiş olması halinde bu sebebin ortadan kalktığı tarihten itibaren en geç yedi gün içinde karara karşı başvuruda bulunulabilir...\n\n(3) Başvuru, bizzat kanunî temsilci veya avukat tarafından sulh ceza mahkemesine verilecek bir dilekçe ile yapılır. Başvuru dilekçesi, iki nüsha olarak verilir.",
  "Kabahatler m.28": "(1) Başvuru üzerine mahkemece yapılan ön inceleme sonucunda; yetkisizlik halinde dosyanın yetkili mahkemeye gönderilmesine, süresinde yapılmama/incelenebilir karar olmama/hak bulunmama halinde başvurunun reddine, aksi halde başvurunun usulden kabulüne karar verilir.\n\n(3) İlgili kamu kurum ve kuruluşu, başvuru dilekçesinin tebliği tarihinden itibaren en geç onbeş gün içinde mahkemeye cevap verir...\n\n(10) Onbeşbin Türk Lirası dahil idarî para cezalarına karşı başvuru üzerine verilen kararlar kesindir.",
  "Kabahatler m.29": "(1) Mahkemenin verdiği son karara karşı, Ceza Muhakemesi Kanununa göre itiraz edilebilir. Bu itiraz, kararın tebliği tarihten itibaren en geç iki hafta içinde yapılır.\n(2) İtirazla ilgili karar, dosya üzerinden inceleme yapılarak verilir.",
  "Kabahatler m.3": "(1) Bu Kanunun; a) İdarî yaptırım kararlarına karşı kanun yoluna ilişkin hükümleri, diğer kanunlarda aksine hüküm bulunmaması halinde, b) Diğer genel hükümleri, idarî para cezası veya mülkiyetin kamuya geçirilmesi yaptırımını gerektiren bütün fiiller hakkında, uygulanır.",
  "Kabahatler m.30": "(1) Kanun yoluna başvuran kişi, bu konuda karar verilinceye kadar başvurusundan vazgeçebilir. Vazgeçme halinde bir daha aynı konuda başvuruda bulunulamaz.\n(2) İlgili kamu kurum ve kuruluşu da mahkeme tarafından karar verilinceye kadar kanun yolu başvurusunu kabul ederek idarî yaptırım kararını geri alabilir.",
  "Kabahatler m.32": "(1) Yetkili makamlar tarafından adlî işlemler nedeniyle ya da kamu güvenliği, kamu düzeni veya genel sağlığın korunması amacıyla, hukuka uygun olarak verilen emre aykırı hareket eden kişiye yüz Türk Lirası idarî para cezası verilir. Bu cezaya emri veren makam tarafından karar verilir.",
  "Kabahatler m.33": "(1) Dilencilik yapan kişiye, elli Türk Lirası idarî para cezası verilir. Ayrıca, dilencilikten elde edilen gelire elkonularak mülkiyetin kamuya geçirilmesine karar verilir.\n(2) Bu kabahat dolayısıyla idarî para cezasına ve elkoymaya kolluk veya belediye zabıta görevlileri, mülkiyetin kamuya geçirilmesine mülkî amir veya belediye encümeni karar verir.",
  "Kabahatler m.34": "(1) Kumar oynayan kişiye, bin Türk Lirası idarî para cezası verilir. Ayrıca, kumardan elde edilen gelire elkonularak mülkiyetin kamuya geçirilmesine karar verilir.\n(2) Bu kabahat dolayısıyla idarî para cezasına ve elkoymaya kolluk görevlileri, mülkiyetin kamuya geçirilmesine mülkî amir karar verir.",
  "Kabahatler m.35": "(1) Sarhoş olarak başkalarının huzur ve sükununu bozacak şekilde davranışlarda bulunan kişiye, kolluk görevlileri tarafından elli Türk Lirası idarî para cezası verilir. Kişi, ayrıca sarhoşluğun etkisi geçinceye kadar kontrol altında tutulur.",
  "Kabahatler m.36": "(1) Başkalarının huzur ve sükununu bozacak şekilde gürültüye neden olan kişiye, elli Türk Lirası idarî para cezası verilir.\n(2) Bu fiilin bir ticarî işletmenin faaliyeti çerçevesinde işlenmesi halinde işletme sahibi gerçek veya tüzel kişiye bin Türk Lirasından beşbin Türk Lirasına kadar idarî para cezası verilir.\n(3) Bu kabahat dolayısıyla idarî para cezasına kolluk veya belediye zabıta görevlileri karar verir.",
  "Kabahatler m.37": "(1) Mal veya hizmet satmak için başkalarını rahatsız eden kişi, elli Türk Lirası idarî para cezası ile cezalandırılır.\n(2) Bu kabahat dolayısıyla idarî para cezası vermeye kolluk veya belediye zabıta görevlileri yetkilidir.",
  "Kabahatler m.38": "(1) Yetkili makamların açık ve yazılı izni olmaksızın meydan, cadde, sokak veya yayaların gelip geçtiği kaldırımları işgal eden veya buralarda mal satışa arz eden kişiye, belediye zabıta görevlileri tarafından elli Türk Lirası idarî para cezası verilir.\n(2) ... meydan, cadde, sokak veya kaldırımlar üzerine inşaat malzemesi yığan kişiye ... yüz Türk Lirasından beşyüz Türk Lirasına kadar idarî para cezası verilir.",
  "Kabahatler m.39": "(1) Kamu hizmet binalarının kapalı alanlarında tütün mamulü tüketen kişiye, ilgili idarî birim amirinin yetkili kıldığı kamu görevlileri tarafından elli Türk Lirası idarî para cezası verilir...\n(2) Toplu taşıma araçlarında tütün mamulü tüketen kişiye, elli Türk Lirası idarî para cezası verilir...",
  "Kabahatler m.4": "(1) Hangi fiillerin kabahat oluşturduğu, kanunda açıkça tanımlanabileceği gibi; kanunun kapsam ve koşulları bakımından belirlediği çerçeve hükmün içeriği, idarenin genel ve düzenleyici işlemleriyle de doldurulabilir.\n(2) Kabahat karşılığı olan yaptırımların türü, süresi ve miktarı, ancak kanunla belirlenebilir.",
  "Kabahatler m.40": "(1) Görevle bağlantılı olarak sorulması halinde kamu görevlisine kimliği veya adresiyle ilgili bilgi vermekten kaçınan veya gerçeğe aykırı beyanda bulunan kişiye, bu görevli tarafından elli Türk Lirası idarî para cezası verilir.\n(2) ... kimliği belirlenemeyen kişi tutularak durumdan derhal Cumhuriyet savcısı haberdar edilir. Bu kişi, kimliği açık bir şekilde anlaşılıncaya kadar gözaltına alınır ve gerekirse tutuklanır.",
  "Kabahatler m.41": "(1) Evsel atık ve artıkları, bunların toplanmasına veya depolanmasına özgü yerler dışına atan kişiye, yirmi Türk Lirası idarî para cezası verilir...\n(7) Bu kabahatler dolayısıyla idarî para cezasına belediye sınırları içerisinde belediye zabıta görevlileri, belediye sınırları dışında kolluk görevlileri karar verir.\n(8) Bu kabahatler dolayısıyla meydana gelen kirliliğin kişi tarafından derhal giderilmesi halinde idarî para cezasına karar verilmeyebilir.",
  "Kabahatler m.42": "(1) Meydanlara/parklara, cadde-sokak kenarlarındaki kamuya ait duvar/alanlara, rızası olmaksızın özel kişilere ait alanlara afiş ve ilân asan kişiye, yüz Türk Lirasından üçbin Türk Lirasına kadar idarî para cezası verilir. Aynı içerikteki afiş ve ilânlar, tek fiil sayılır.\n(4) ... kolluk veya belediye zabıta görevlileri karar verir.\n\n(1) 112 Acil Çağrı Merkezini meşgul etmek amacıyla arayarak görevlilerle konuşan veya ısrarla çağrı bırakan kişiye, il valileri tarafından binbeşyüz Türk Lirası idari para cezası verilir.\n(2) 112 Acil Çağrı Merkezine yapılan ihbarın asılsız olduğunun olay yerine giden ekiplerce tutanakla tespit edilmesi halinde kişiye, il valileri tarafından onbeşbin Türk Lirası idari para cezası verilir.\n(3) Bu maddede yazılı fiillerin bir yıl içinde tekrarı halinde idari para cezası iki katı olarak uygulanır.",
  "Kabahatler m.43": "(1) Yetkili makamlardan ruhsat almaksızın kanuna göre yasak olmayan silahları park, meydan, cadde veya sokaklarda görünür bir şekilde taşıyan kişiye, kolluk tarafından elli Türk Lirası idarî para cezası verilir.\n\n(1) ... bir tüzel kişinin organ veya temsilcisi ... tarafından dolandırıcılık, uyuşturucu imal-ticareti, ihaleye/edime fesat, rüşvet, suçtan kaynaklanan malvarlığını aklama, zimmet, kaçakçılık, petrol piyasası suçu, terörizmin finansmanı suçunun tüzel kişinin yararına işlenmesi halinde, ayrıca bu tüzel kişiye onbin Türk Lirasından elli milyon Türk Lirasına kadar idarî para cezası verilir. Ancak idari para cezası, işleme veya eyleme konu menfaatin iki katından az olamaz.\n(2) ... yargılama yapmakla görevli mahkeme yetkilidir.\n\n(1) ... bankalara, finansal kuruluşlara ... ibraz edilen paranın sahte olduğunun anlaşılması halinde, ... bildirim yükümlülüğü yerine getirilmediği takdirde, bu tüzel kişilere Cumhuriyet savcısı tarafından bin Türk Lirasından beşbin Türk Lirasına kadar idarî para cezası verilir.",
  "Kabahatler m.5": "(1) 5237 sayılı Türk Ceza Kanununun zaman bakımından uygulamaya ilişkin hükümleri kabahatler bakımından da uygulanır. Ancak, kabahatler karşılığında öngörülen idarî yaptırımlara ilişkin kararların yerine getirilmesi bakımından derhal uygulama kuralı geçerlidir.\n(2) Kabahat, failin icraî veya ihmali davranışı gerçekleştirdiği zaman işlenmiş sayılır. Neticenin oluştuğu zaman, bu bakımdan dikkate alınmaz.",
  "Kabahatler m.7": "(1) Kabahat, icraî veya ihmali davranışla işlenebilir. İhmali davranışla işlenmiş kabahatin varlığı için kişi açısından belli bir icraî davranışta bulunma hususunda hukukî yükümlülüğün varlığı gereklidir.",
  "Kabahatler m.8": "(1) Organ veya temsilcilik görevi yapan ya da organ veya temsilci olmamakla birlikte, tüzel kişinin faaliyeti çerçevesinde görev üstlenen kişinin bu görevi kapsamında işlemiş bulunduğu kabahatten dolayı tüzel kişi hakkında da idarî yaptırım uygulanabilir.\n(2) Temsilci sıfatıyla hareket eden kişinin bu sıfatla bağlantılı olarak işlemiş bulunduğu kabahatten dolayı temsil edilen gerçek kişi hakkında da idarî yaptırım uygulanabilir. Gerçek kişiye ait bir işte çalışan kişinin bu faaliyeti çerçevesinde işlemiş bulunduğu kabahatten dolayı, iş sahibi kişi hakkında da idarî yaptırım uygulanabilir.\n(3) Kanunun, organ veya temsilcide ya da temsil edilen kişide özel nitelikler aradığı hallerde de yukarıdaki fıkralar hükümleri uygulanır.\n(4) Birinci ve ikinci fıkra hükümleri, organ veya temsilcilik ya da hizmet ilişkisinin dayanağını oluşturan işlemin hukuken geçerli olmaması halinde de uygulanır.",
  "Kabahatler m.9": "(1) Kabahatler, kanunda açıkça hüküm bulunmayan hallerde, hem kasten hem de taksirle işlenebilir.",
  "KV Silme Yön m.11": "(1) Kişisel veri saklama ve imha politikası hazırlamış olan veri sorumlusu, (...) yükümlülüğünün ortaya çıktığı tarihi takip eden ilk periyodik imha işleminde, kişisel verileri siler, yok eder veya anonim hale getirir. (2) Periyodik imhanın gerçekleştirileceği zaman aralığı, veri sorumlusu tarafından kişisel veri saklama ve imha politikasında belirlenir. Bu süre her halde altı ayı geçemez. (3) Kişisel veri saklama ve imha politikası hazırlama yükümlülüğü olmayan veri sorumlusu, (...) yükümlülüğünün ortaya çıktığı tarihi takip eden üç ay içinde, kişisel verileri siler, yok eder veya anonim hale getirir.",
  "KV Silme Yön m.12": "(1) İlgili kişi, Kanunun 11 inci ve 13 üncü maddelerine istinaden veri sorumlusuna başvurarak kendisine ait kişisel verilerin silinmesini veya yok edilmesini talep ettiğinde; a) Kişisel verileri işleme şartlarının tamamı ortadan kalkmışsa; veri sorumlusu talebe konu kişisel verileri siler, yok eder veya anonim hale getirir. Veri sorumlusu, ilgili kişinin talebini en geç otuz gün içinde sonuçlandırır ve ilgili kişiye bilgi verir.",
  "KV Silme Yön m.4": "c) İmha: Kişisel verilerin silinmesi, yok edilmesi veya anonim hale getirilmesini, (...) ğ) Periyodik imha: Kanunda yer alan kişisel verilerin işlenme şartlarının tamamının ortadan kalkması durumunda kişisel verileri saklama ve imha politikasında belirtilen ve tekrar eden aralıklarla resen gerçekleştirilecek silme, yok etme veya anonim hale getirme işlemini, (...) i) Veri sorumlusu: Kişisel verilerin işleme amaçlarını ve vasıtalarını belirleyen, veri kayıt sisteminin kurulmasından ve yönetilmesinden sorumlu olan gerçek veya tüzel kişiyi, ifade eder.",
  "KV Silme Yön m.7": "(1) Kanunun 5 inci ve 6 ncı maddelerinde yer alan kişisel verilerin işlenme şartlarının tamamının ortadan kalkması halinde, kişisel verilerin veri sorumlusu tarafından resen veya ilgili kişinin talebi üzerine silinmesi, yok edilmesi veya anonim hâle getirilmesi gerekir. (...) (3) Kişisel verilerin silinmesi, yok edilmesi ve anonim hale getirilmesiyle ilgili yapılan bütün işlemler kayıt altına alınır ve söz konusu kayıtlar, diğer hukuki yükümlülükler hariç olmak üzere en az üç yıl süreyle saklanır.",
  "KVKK m.11": "(1) Herkes, veri sorumlusuna başvurarak kendisiyle ilgili; a) Kişisel veri işlenip işlenmediğini öğrenme, b) Kişisel verileri işlenmişse buna ilişkin bilgi talep etme, c) Kişisel verilerin işlenme amacını ve bunların amacına uygun kullanılıp kullanılmadığını öğrenme, ç) Yurt içinde veya yurt dışında kişisel verilerin aktarıldığı üçüncü kişileri bilme, d) Kişisel verilerin eksik veya yanlış işlenmiş olması hâlinde bunların düzeltilmesini isteme, e) 7 nci maddede öngörülen şartlar çerçevesinde kişisel verilerin silinmesini veya yok edilmesini isteme, f) (d) ve (e) bentleri uyarınca yapılan işlemlerin, kişisel verilerin aktarıldığı üçüncü kişilere bildirilmesini isteme, g) İşlenen verilerin münhasıran otomatik sistemler vasıtasıyla analiz edilmesi suretiyle kişinin kendisi aleyhine bir sonucun ortaya çıkmasına itiraz etme, ğ) Kişisel verilerin kanuna aykırı olarak işlenmesi sebebiyle zarara uğraması hâlinde zararın giderilmesini talep etme, haklarına sahiptir.",
  "KVKK m.12": "(1) Veri sorumlusu; a) Kişisel verilerin hukuka aykırı olarak işlenmesini önlemek, b) Kişisel verilere hukuka aykırı olarak erişilmesini önlemek, c) Kişisel verilerin muhafazasını sağlamak, amacıyla uygun güvenlik düzeyini temin etmeye yönelik gerekli her türlü teknik ve idari tedbirleri almak zorundadır. (...) (4) Veri sorumluları ile veri işleyen kişiler, öğrendikleri kişisel verileri bu Kanun hükümlerine aykırı olarak başkasına açıklayamaz ve işleme amacı dışında kullanamazlar. Bu yükümlülük görevden ayrılmalarından sonra da devam eder. (5) İşlenen kişisel verilerin kanuni olmayan yollarla başkaları tarafından elde edilmesi hâlinde, veri sorumlusu bu durumu en kısa sürede ilgilisine ve Kurula bildirir. (...)",
  "KVKK m.13": "(1) İlgili kişi, bu Kanunun uygulanmasıyla ilgili taleplerini yazılı olarak veya Kurulun belirleyeceği diğer yöntemlerle veri sorumlusuna iletir. (2) Veri sorumlusu başvuruda yer alan talepleri, talebin niteliğine göre en kısa sürede ve en geç otuz gün içinde ücretsiz olarak sonuçlandırır. Ancak, işlemin ayrıca bir maliyeti gerektirmesi hâlinde, Kurulca belirlenen tarifedeki ücret alınabilir. (3) Veri sorumlusu talebi kabul eder veya gerekçesini açıklayarak reddeder ve cevabını ilgili kişiye yazılı olarak veya elektronik ortamda bildirir. (...)",
  "KVKK m.18": "(1) Bu Kanunun; a) 10 uncu maddesinde öngörülen aydınlatma yükümlülüğünü yerine getirmeyenler hakkında 5.000 Türk lirasından 100.000 Türk lirasına kadar, b) 12 nci maddesinde öngörülen veri güvenliğine ilişkin yükümlülükleri yerine getirmeyenler hakkında 15.000 Türk lirasından 1.000.000 Türk lirasına kadar, c) 15 inci maddesi uyarınca Kurul tarafından verilen kararları yerine getirmeyenler hakkında 25.000 Türk lirasından 1.000.000 Türk lirasına kadar, ç) 16 ncı maddesinde öngörülen Veri Sorumluları Siciline kayıt ve bildirim yükümlülüğüne aykırı hareket edenler hakkında 20.000 Türk lirasından 1.000.000 Türk lirasına kadar, d) (Ek:2/3/2024-7499/35 md.) 9 uncu maddenin beşinci fıkrasında öngörülen bildirim yükümlülüğünü yerine getirmeyenler hakkında 50.000 Türk lirasından 1.000.000 Türk lirasına kadar, idari para cezası verilir. (2) (Değişik:2/3/2024-7499/35 md.) Birinci fıkranın (a), (b), (c) ve (ç) bentlerinde öngörülen idari para cezaları veri sorumlusu, (d) bendinde öngörülen idari para cezası veri sorumlusu veya veri işleyen gerçek kişiler ile özel hukuk tüzel kişileri hakkında uygulanır. (3) (Ek:2/3/2024-7499/35 md.) Kurulca verilen idari para cezalarına karşı, idare mahkemelerinde dava açılabilir. (...)",
  "KVKK m.28": "(1) Bu Kanun hükümleri aşağıdaki hâllerde uygulanmaz: a) Kişisel verilerin, üçüncü kişilere verilmemek ve veri güvenliğine ilişkin yükümlülüklere uyulmak kaydıyla gerçek kişiler tarafından tamamen kendisiyle veya aynı konutta yaşayan aile fertleriyle ilgili faaliyetler kapsamında işlenmesi. b) Kişisel verilerin resmi istatistik ile anonim hâle getirilmek suretiyle araştırma, planlama ve istatistik gibi amaçlarla işlenmesi. c) Kişisel verilerin millî savunmayı, millî güvenliği, kamu güvenliğini, kamu düzenini, ekonomik güvenliği, özel hayatın gizliliğini veya kişilik haklarını ihlal etmemek ya da suç teşkil etmemek kaydıyla, sanat, tarih, edebiyat veya bilimsel amaçlarla ya da ifade özgürlüğü kapsamında işlenmesi. ç) Kişisel verilerin millî savunmayı, millî güvenliği, kamu güvenliğini, kamu düzenini veya ekonomik güvenliği sağlamaya yönelik olarak kanunla görev ve yetki verilmiş kamu kurum ve kuruluşları tarafından yürütülen önleyici, koruyucu ve istihbari faaliyetler kapsamında işlenmesi. d) Kişisel verilerin soruşturma, kovuşturma, yargılama veya infaz işlemlerine ilişkin olarak yargı makamları veya infaz mercileri tarafından işlenmesi. (2) Bu Kanunun amacına ve temel ilkelerine uygun ve orantılı olmak kaydıyla veri sorumlusunun aydınlatma yükümlülüğünü düzenleyen 10 uncu, zararın giderilmesini talep etme hakkı hariç, ilgili kişinin haklarını düzenleyen 11 inci ve Veri Sorumluları Siciline kayıt yükümlülüğünü düzenleyen 16 ncı maddeleri aşağıdaki hâllerde uygulanmaz: a) Kişisel veri işlemenin suç işlenmesinin önlenmesi veya suç soruşturması için gerekli olması. b) İlgili kişinin kendisi tarafından alenileştirilmiş kişisel verilerin işlenmesi. c) Kişisel veri işlemenin kanunun verdiği yetkiye dayanılarak görevli ve yetkili kamu kurum ve kuruluşları ile kamu kurumu niteliğindeki meslek kuruluşlarınca, denetleme veya düzenleme görevlerinin yürütülmesi ile disiplin soruşturma veya kovuşturması için gerekli olması. ç) Kişisel veri işlemenin bütçe, vergi ve mali konulara ilişkin olarak Devletin ekonomik ve mali çıkarlarının korunması için gerekli olması.",
  "KVKK m.3": "(1) Bu Kanunun uygulanmasında; a) Açık rıza: Belirli bir konuya ilişkin, bilgilendirilmeye dayanan ve özgür iradeyle açıklanan rızayı, b) Anonim hâle getirme: Kişisel verilerin, başka verilerle eşleştirilerek dahi hiçbir surette kimliği belirli veya belirlenebilir bir gerçek kişiyle ilişkilendirilemeyecek hâle getirilmesini, (...) ç) İlgili kişi: Kişisel verisi işlenen gerçek kişiyi, d) Kişisel veri: Kimliği belirli veya belirlenebilir gerçek kişiye ilişkin her türlü bilgiyi, e) Kişisel verilerin işlenmesi: Kişisel verilerin tamamen veya kısmen otomatik olan ya da herhangi bir veri kayıt sisteminin parçası olmak kaydıyla otomatik olmayan yollarla elde edilmesi, kaydedilmesi, depolanması, (...) gibi veriler üzerinde gerçekleştirilen her türlü işlemi, f) Kurul: Kişisel Verileri Koruma Kurulunu, g) Kurum: Kişisel Verileri Koruma Kurumunu, ğ) Veri işleyen: Veri sorumlusunun verdiği yetkiye dayanarak onun adına kişisel verileri işleyen gerçek veya tüzel kişiyi, (...) ı) Veri sorumlusu: Kişisel verilerin işleme amaçlarını ve vasıtalarını belirleyen, veri kayıt sisteminin kurulmasından ve yönetilmesinden sorumlu olan gerçek veya tüzel kişiyi, ifade eder.",
  "KVKK m.4": "(1) Kişisel veriler, ancak bu Kanunda ve diğer kanunlarda öngörülen usul ve esaslara uygun olarak işlenebilir. (2) Kişisel verilerin işlenmesinde aşağıdaki ilkelere uyulması zorunludur: a) Hukuka ve dürüstlük kurallarına uygun olma. b) Doğru ve gerektiğinde güncel olma. c) Belirli, açık ve meşru amaçlar için işlenme. ç) İşlendikleri amaçla bağlantılı, sınırlı ve ölçülü olma. d) İlgili mevzuatta öngörülen veya işlendikleri amaç için gerekli olan süre kadar muhafaza edilme.",
  "KVKK m.5": "(1) Kişisel veriler ilgili kişinin açık rızası olmaksızın işlenemez. (2) Aşağıdaki şartlardan birinin varlığı hâlinde, ilgili kişinin açık rızası aranmaksızın kişisel verilerinin işlenmesi mümkündür: a) Kanunlarda açıkça öngörülmesi. b) Fiili imkânsızlık nedeniyle rızasını açıklayamayacak durumda bulunan veya rızasına hukuki geçerlilik tanınmayan kişinin kendisinin ya da bir başkasının hayatı veya beden bütünlüğünün korunması için zorunlu olması. c) Bir sözleşmenin kurulması veya ifasıyla doğrudan doğruya ilgili olması kaydıyla, sözleşmenin taraflarına ait kişisel verilerin işlenmesinin gerekli olması. ç) Veri sorumlusunun hukuki yükümlülüğünü yerine getirebilmesi için zorunlu olması. d) İlgili kişinin kendisi tarafından alenileştirilmiş olması. e) Bir hakkın tesisi, kullanılması veya korunması için veri işlemenin zorunlu olması. f) İlgili kişinin temel hak ve özgürlüklerine zarar vermemek kaydıyla, veri sorumlusunun meşru menfaatleri için veri işlenmesinin zorunlu olması.",
  "KVKK m.6": "(1) Kişilerin ırkı, etnik kökeni, siyasi düşüncesi, felsefi inancı, dini, mezhebi veya diğer inançları, kılık ve kıyafeti, dernek, vakıf ya da sendika üyeliği, sağlığı, cinsel hayatı, ceza mahkûmiyeti ve güvenlik tedbirleriyle ilgili verileri ile biyometrik ve genetik verileri özel nitelikli kişisel veridir. (2) (Mülga:2/3/2024-7499/33 md.) (3) (Değişik:2/3/2024-7499/33 md.) Özel nitelikli kişisel verilerin işlenmesi yasaktır. Ancak bu verilerin işlenmesi; a) İlgili kişinin açık rızasının olması, b) Kanunlarda açıkça öngörülmesi, c) Fiili imkânsızlık nedeniyle rızasını açıklayamayacak durumda bulunan (...) kişinin, kendisinin ya da bir başkasının hayatı veya beden bütünlüğünün korunması için zorunlu olması, ç) İlgili kişinin alenileştirdiği kişisel verilere ilişkin ve alenileştirme iradesine uygun olması, d) Bir hakkın tesisi, kullanılması veya korunması için zorunlu olması, e) Sır saklama yükümlülüğü altında bulunan kişiler veya yetkili kurum ve kuruluşlarca, kamu sağlığının korunması, koruyucu hekimlik, tıbbi teşhis, tedavi ve bakım hizmetlerinin yürütülmesi (...) amacıyla gerekli olması, f) İstihdam, iş sağlığı ve güvenliği, sosyal güvenlik, sosyal hizmetler ve sosyal yardım alanlarındaki hukuki yükümlülüklerin yerine getirilmesi için zorunlu olması, g) Siyasi, felsefi, dini veya sendikal amaçlarla kurulan vakıf, dernek ve diğer kâr amacı gütmeyen kuruluş (...) mevcut veya eski üyelerine (...) yönelik olması, halinde mümkündür. (4) Özel nitelikli kişisel verilerin işlenmesinde, ayrıca Kurul tarafından belirlenen yeterli önlemlerin alınması şarttır.",
  "KVKK m.7": "(1) Bu Kanun ve ilgili diğer kanun hükümlerine uygun olarak işlenmiş olmasına rağmen, işlenmesini gerektiren sebeplerin ortadan kalkması hâlinde kişisel veriler resen veya ilgili kişinin talebi üzerine veri sorumlusu tarafından silinir, yok edilir veya anonim hâle getirilir. (2) Kişisel verilerin silinmesi, yok edilmesi veya anonim hâle getirilmesine ilişkin diğer kanunlarda yer alan hükümler saklıdır. (3) Kişisel verilerin silinmesine, yok edilmesine veya anonim hâle getirilmesine ilişkin usul ve esaslar yönetmelikle düzenlenir.",
  "OHAL m.1": "Madde 1 – Bu Kanunun amacı, a) Tabii afet, tehlikeli salgın hastalıklar veya ağır ekonomik bunalım, b) Anayasa ile kurulan hür demokrasi düzenini veya temel hak ve hürriyetleri ortadan kaldırmaya yönelik yaygın şiddet hareketlerine ait ciddi belirtilerin ortaya çıkması veya şiddet olayları sebebiyle kamu düzeninin ciddi şekilde bozulması, Durumlarında olağanüstü hal ilan edilmesi ve usulleriyle olağanüstü hallerde uygulanacak hükümleri belirlemektir.",
  "OHAL m.10": "Madde 10 – Ağır ekonomik bunalım sebebiyle olağanüstü hal ilanı durumunda, ekonominin düzenlenmesi ve iyileştirilmesi amacı ile mal, sermaye ve hizmet piyasalarını yönlendirici; vergi, para, kredi, kira, ücret ve fiyat politikalarını belirleyici ve çalışmaya ilişkin her türlü tedbir ve yükümlülüklerin tespiti, tanzimi ve takibi konularında Cumhurbaşkanlığı kararnamesi çıkarılabilir. (...)",
  "OHAL m.11": "Madde 11 – Bu Kanunun 3 üncü maddesinin birinci fıkrasının (b) bendi gereğince olağanüstü hal ilanında; genel güvenlik, asayiş ve kamu düzenini korumak, şiddet olaylarının yaygınlaşmasını önlemek amacıyla 9 uncu maddede öngörülen tedbirlere ek olarak aşağıdaki tedbirler de alınabilir: a) Sokağa çıkmayı sınırlamak veya yasaklamak, b) Belli yerlerde veya belli saatlerde kişilerin dolaşmalarını ve toplanmalarını, araçların seyirlerini yasaklamak, c) Kişilerin; üstünü, araçlarını, eşyalarını aratmak ve bulunacak suç eşyası ve delil niteliğinde olanlarına el koymak, d) Olağanüstü hal ilan edilen bölge sakinleri ile bu bölgeye hariçten girecek kişiler için kimlik belirleyici belge taşıma mecburiyeti koymak, e) Gazete, dergi, broşür, kitap, el ve duvar ilanı ve benzerlerinin basılmasını, çoğaltılmasını, yayımlanmasını ve dağıtılmasını, bunlardan olağanüstü hal bölgesi dışında basılmış veya çoğaltılmış olanların bölgeye sokulmasını ve dağıtılmasını yasaklamak veya izne bağlamak; basılması ve neşri yasaklanan kitap, dergi, gazete, broşür, afiş ve benzeri matbuayı toplatmak, f) Söz, yazı, resmi, film, plak, ses ve görüntü bantlarını ve sesle yapılan her türlü yayımı denetlemek, gerektiğinde kayıtlamak veya yasaklamak, g) Hassasiyet taşıyan kamuya veya kişilere ait kuruluşlara ve bankalara, kendi iç güvenliklerini sağlamak için özel koruma tedbirleri aldırmak veya bunların artırılmasını istemek, h) Her nevi sahne oyunlarını ve gösterilen filmleri denetlemek, gerektiğinde durdurmak veya yasaklamak, i) Ruhsatlı da olsa her nevi silah ve mermilerin taşınmasını veya naklini yasaklamak, j) Her türlü cephaneler, bombalar, tahrip maddeleri, patlayıcı maddeler, radyoaktif maddeler veya yakıcı, aşındırıcı, yaralayıcı eczalar veya diğer her türlü zehirler ve boğucu gazlar veya benzeri maddelerin bulundurulmasını, hazırlanmasını, yapılmasını veya naklini izne bağlamak veya yasaklamak ve bunlar ile bunların hazırlanmasına veya yapılmasına yarayan eşya, alet veya araçların teslimini istemek veya toplatmak, k) Kamu düzeni veya kamu güvenini bozabileceği kanısını uyandıran kişi ve toplulukların bölgeye girişini yasaklamak, bölge dışına çıkarmak veya bölge içerisinde belirli yerlere girmesini veya yerleşmesini yasaklamak, l) Bölge dahilinde güvenliklerinin sağlanması gerekli görülen tesis veya teşekküllerin bulunduğu alanlara giriş ve çıkışı düzenlemek, kayıtlamak veya yasaklamak, m) Kapalı ve açık yerlerde yapılacak toplantı ve gösteri yürüyüşlerini yasaklamak, ertelemek, izne bağlamak veya toplantı ve gösteri yürüyüşlerinin yapılacağı yer ve zamanı tayin, tespit ve tahsis etmek, izne bağladığı her türlü toplantıyı izletmek, gözetim altında tutmak veya gerekiyorsa dağıtmak, n) (Ek: 14/11/1984 - 3076/1 md.) İşçinin isteği, ahlak ve iyi niyet kurallarına uymayan haller, sağlık sebepleri, normal emeklilik ve belirli süresinin bitişi nedeniyle hizmet aktinin sona ermesi veya feshi dışında kalan hallerde işçi çıkartmalarını işverenin de durumunu dikkate alarak üç aylık bir süreyi aşmamak kaydıyla izne bağlamak veya ertelemek, o) (Ek: 14/11/1984 - 3076/1 md.) Dernek faaliyetlerini; her dernek hakkında ayrı karar almak ve üç ayı geçmemek kaydıyla durdurmak, (ö bendi mülga/Anayasa Mahkemesince iptal); p) (...) valinin talebi üzerine ilgili komutan, eylemcileri ele geçirmek veya tesirsiz hale getirmek maksadı ile, her defasında Genelkurmay Başkanlığı kanalı ile Hükümetin müsaadesi tahtında, ihtiyaca göre, Kara, Hava veya Deniz Kuvvetleri unsurları ile mahdut hedefli sınır ötesi harekat planlayıp icra etmek.",
  "OHAL m.12": "Madde 12 – Olağanüstü hal ilanında koordinasyon, Cumhurbaşkanlığınca veya Cumhurbaşkanının görevlendireceği Cumhurbaşkanı yardımcısı ya da bakanlıkça sağlanır. Bunun için, olağanüstü hal ilanına sebep olan konu ile ilgili bulunan bakanlıklar temsilcilerinden meydana gelen Olağanüstü Hal Koordinasyon Kurulu kurulur. (...) Olağanüstü Hal Koordinasyon Kurulunun kuruluş ve çalışma esasları, çıkarılacak yönetmelikte gösterilir. Ağır ekonomik bunalım sebebiyle olağanüstü hal ilanında 10 uncu madde hükümleri saklıdır. Madde 13 – Bölge valiliği teşkilat ve birimlerinin görevleri saklı kalmak üzere, olağanüstü hal ilan edilen bölgelerde; olağanüstü hal ilanını gerektiren olayları ve tedbirlerin uygulanmasını izlemek, değerlendirmek, bunlarla ilgili önerilerde bulunmak üzere bölge valisinin başkanlığında, görevlendireceği il valileri ile diğer kamu kuruluşları yöneticilerinin, garnizon komutanı veya görevlendireceği bir temsilcinin üye olarak katılacağı bölge olağanüstü hal kurulu kurulur. Bölge valisinin gerek görmesi veya olağanüstü halin bir ilde ilanı halinde, il merkezlerinde ve ilçelerde birer olağanüstü hal bürosu oluşturulur. İl bürolarına il valisi veya görevlendireceği vali muavini, ilçe bürolarına kaymakamlar başkanlık eder. (...) Olağanüstü hal kurul ve bürolarının kuruluş, toplanma, karar alma, çalışma usul ve esasları yönetmelikte belirlenir.",
  "OHAL m.2": "Madde 2 – Bu Kanun; olağanüstü hal ilanına tabii afet, tehlikeli salgın hastalıklar veya ağır ekonomik bunalım hallerinde ilan edilen olağanüstü hallerde vatandaşlar için getirilecek para, mal ve çalışma yükümlülükleri ile olağanüstü hallerin her türü için ayrı ayrı geçerli olmak üzere, temel hak ve hürriyetlerin nasıl sınırlanacağı veya nasıl durdurulacağına, halin gerektirdiği tedbirlerin nasıl ve ne suretle alınacağına, kamu hizmeti görevlilerine ne gibi yetkiler verileceğine, görevlilerin durumlarında ne gibi değişiklikler yapılacağına ve olağanüstü yönetim usullerine ilişkin hükümleri kapsar.",
  "OHAL m.3": "Madde 3 – Cumhurbaşkanı: a) Tabii afet, tehlikeli salgın hastalıklar veya ağır ekonomik bunalım hallerinden birinin veya birden fazlasının görülmesi durumunda, b) Anayasa ile kurulan hür demokrasi düzenini veya temel hak ve hürriyetleri ortadan kaldırmaya yönelik yaygın şiddet hareketlerine ait ciddi belirtilerin ortaya çıkması veya şiddet olayları sebebiyle kamu düzeninin ciddi şekilde bozulması hallerinde, Milli Güvenlik Kurulunun görüşünü de aldıktan sonra; Yurdun bir veya birden fazla bölgesinde veya bütününde altı ayı geçmemek üzere olağanüstü hal ilan edebilir. Olağanüstü hal kararı Resmi Gazete'de yayımlanır ve hemen Türkiye Büyük Millet Meclisinin onayına sunulur. Türkiye Büyük Millet Meclisi tatilde ise derhal toplantıya çağrılır. Meclis, olağanüstü hal süresini değiştirebilir. Cumhurbaşkanının istemi üzerine, her defasında dört ayı geçmemek üzere, süreyi uzatabilir veya olağanüstü hali kaldırabilir. Cumhurbaşkanı, olağanüstü halin bu maddenin birinci fıkrasının (b) bendi gereğince ilanından sonra; süreyi uzatmaya, kapsamını değiştirmeye veya olağanüstü hali kaldırmaya ilişkin hususlarda da karar almadan önce Milli Güvenlik Kurulunun görüşünü alır.",
  "OHAL m.4": "Madde 4 – Olağanüstü hal süresince, Cumhurbaşkanı olağanüstü halin gerekli kıldığı konularda Anayasanın 91 inci maddesindeki kısıtlamalara ve usule bağlı olmaksızın, kanun hükmünde kararnameler çıkarabilir. Bu kararnameler Resmi Gazete'de yayımlanır ve aynı gün Türkiye Büyük Millet Meclisinin onayına sunulur.",
  "OHAL m.5": "Madde 5 – Tabii afet ve tehlikeli salgın hastalıklar sebepleriyle olağanüstü hal ilan edilmesi durumunda; felakete uğrayanların kurtarılması, meydana gelen hasar ve zararın telafisi için ihtiyaç duyulan ve hemen sağlanamayan para ve her türlü taşınır ve taşınmaz mallar ve yapılması gereken işler; para, mal ve çalışma yükümlülüğü yoluyla sağlanır. Madde 6 – Tabii afet ve tehlikeli salgın hastalıklar sebebiyle olağanüstü hal ilan edilmesi durumunda gerekli harcamalar öncelikle kamu kaynakları ile yardımlardan sağlanır. (...) Madde 7 – (...) bölge içindeki kamu kurum ve kuruluşlarıyla tüzel ve gerçek kişiler, kendilerinden istenecek veya yükümlülük konulacak arazi, arsa, bina, tesis, araç, gereç, yiyecek, ilaç ve tıbbi malzeme ile giyecek ve diğer maddeleri vermek zorundadırlar. Bu amaçla; öncelikle o bölgedeki genel ve katma bütçeli dairelere, kamu iktisadi devlet teşekkülleri ve kuruluşları ile bunlara bağlı müesseselere ve mahalli idarelere başvurulur. İhtiyaçların bu kaynaklardan zamanında ve yeterince karşılanmaması halinde, imkan ve kaynakları da dikkate alınarak, bölgedeki özel kuruluşlara ve gerçek kişilere ait olanlara yükümlülük konulur.",
  "OHAL m.8": "Madde 8 – Tabii afet ve tehlikeli salgın hastalıklar sebepleriyle olağanüstü hal ilan edilen bölgelerde bulunan 18 - 60 yaşları arasındaki bütün vatandaşlar, olağanüstü hal sebebiyle kendilerine verilecek işleri yapmakla yükümlüdürler. Görevlendirmelerde; iş mevzuatının çalıştırma yasağı ile ilgili hükümleri çalıştırılacak kişilerin yaş, cinsiyet, sağlık, meslekleri, meşguliyetleri ve sosyal durumları ile aile ve bakıma muhtaç yakınları gözönünde bulundurulur. (...)",
  "OHAL m.9": "Madde 9 – Tabii afet ve tehlikeli salgın hastalıklar sebebiyle olağanüstü hal ilanında, olağanüstü hal ilanını gerektiren hususlar gözönünde bulundurularak aşağıda yazılı tedbirler alınabilir: a) Bölgenin belirli yerlerinde yerleşimi yasaklamak, belirli yerleşim yerlerine girişi ve buralardan çıkışı sınırlamak, belli yerleşim yerlerini boşaltmak veya başka yerlere nakletmek, b) Resmi ve özel her derecedeki öğretim ve eğitim kurumlarında öğrenime ara vermek ve öğrenci yurtlarını süreli veya süresiz olarak kapatmak, c) Gazino, lokanta, birahane, meyhane, lokal, taverna, diskotek, bar, dansing, sinema, tiyatro ve benzeri eğlence yerleri ile kulüp vesair oyun salonlarını, otel, motel, kamping, tatil köyü ve benzeri konaklama tesislerini denetlemek ve bunların açılma ve kapanma zamanını tayin etmek, sınırlamak, gerektiğinde kapatmak ve bu yerleri olağanüstü halin icaplarına göre kullanmak, d) Bölgede olağanüstü hal hizmetlerinin yürütülmesi ile görevli personelin yıllık izinlerini sınırlamak veya kaldırmak, e) Bölge sınırları içerisindeki tüm haberleşme araç ve gereçlerinden yararlanmak ve gerektiğinde bu amaçla geçici olarak bunlara elkoymak, f) Tehlike arz eden binaları yıkmak; sağlığı tehdit ettiği tespit olunan taşınır ve taşınmaz mallar ile sağlığa zararlı gıda maddelerini ve mahsullerini imha etmek, g) Belli gıda maddeleri ile hayvan ve hayvan yemi ve hayvan ürünlerinin bölge dışına çıkarılmasını veya bölgeye sokulmalarını kontrol etmek, sınırlamak veya gerektiğinde yasaklamak, h) Gerekli görülen zaruri ihtiyaç maddelerinin dağıtımını düzenlemek, i) Halkın beslenmesi, ısınması, temizliği ve aydınlanması için gerekli gıda madde ve eşyalarla her türlü yakıtın, sağlığın korunmasında, tedavide ve tıpta kullanılan ilaç, kimyevi madde, alet ve diğer şeylerin, inşaat, sanayi, ulaşım ve tarımda kullanılan eşya ve maddelerin, kamu için gerekli diğer mal, eşya, araç, gereç ve her türlü maddelerin imali, satımı, dağıtımı, depolanması ve ticareti konularında gerekli tedbirleri almak, bu yerlere gerektiğinde elkoymak, kontrol etmek ve bu malları satıştan kaçınan, saklayan, kaçıran, fazla fiyatla satan, imalatını durduran veya yavaşlatanlar hakkında fiilin işleniş şekli veya niteliği de nazara alınarak işyeri bulunduğu mahal için hayati önem taşımadığı takdirde işyerini kapatmak, j) Kara, deniz ve hava trafik düzenine ilişkin tedbirleri almak, ulaştırma araçlarının bölgeye giriş ve çıkışlarını kayıtlamak veya yasaklamak.",
  "Personel Yön m.1": "MADDE 1- (1) Bu Yönetmeliğin amacı; 10/3/1983 tarihli ve 2803 sayılı Jandarma Teşkilat, Görev ve Yetkileri Kanunu, 9/7/1982 tarihli ve 2692 sayılı Sahil Güvenlik Komutanlığı Kanunu ile 14/7/1965 tarihli ve 657 sayılı Devlet Memurları Kanununun; Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı personeliyle ilgili hükümlerinin uygulanmasına dair usul ve esasları belirlemektir. MADDE 2- (1) Bu Yönetmelik; (...) subay, astsubay, sözleşmeli subay ve astsubay, uzman jandarma, uzman erbaş, sözleşmeli erbaş ve erlerin kaynakları, işe alınmaları, mesleki gelişimleri (...) ödev, hak, yükümlülük ile sorumlulukları ve diğer özlük işlerine ilişkin hükümleri kapsar. MADDE 3- (1) Bu Yönetmelik; 2803 sayılı Kanunun 24 üncü maddesi ve 2692 sayılı Kanunun 23 üncü maddesi hükümlerine dayanılarak hazırlanmıştır.",
  "Personel Yön m.10": "(1) Atamalarda hizmet bölgesinin özellikleri esas alınır. (2) Personel, hizmet ihtiyacı esas alınarak (...) meslek hayatları boyunca farklı hizmet bölgeleri arasında zorunlu atama işlemine tabi tutulur. (...) (6) Subay ve astsubayların atandığı hizmet bölgesinde hizmet süresini tamamlamaları esastır. (...) (7) İhtiyaç duyulması halinde subay kadrolarına, liyakat esas alınarak emsalleri arasında temayüz etmiş astsubaylar atanabilir. (...)",
  "Personel Yön m.14": "(2) Genel atamalar, her yılın Mayıs ve Ekim (dâhil) ayları arasında yapılır. Bu atamalar, Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı tarafından önceden duyurulabilir. (3) Genel atamalar, hizmet gerekleri dikkate alınarak Bakanlık tarafından belirlenen diğer zamanlarda da yapılabilir.",
  "Personel Yön m.15": "(1) İlk defa veya yeniden veyahut yer değiştirme suretiyle atamalarda; a) Aynı yerdeki görevlere atananlar atama emirlerinin kendilerine tebliğ gününü, b) Başka yerdeki görevlere atananlar, atama emirlerinin kendilerine tebliğ tarihinden itibaren onbeş gün içerisinde o yere hareket ederek belli yol süresini, izleyen işgünü içinde işe başlamak zorundadırlar. Savaş ve olağanüstü hallerde bu süre Bakanlar Kurulu kararı ile kısaltılabilir. (...) (4) Atama emrinde aksi belirlenmedikçe atama emrinin amire ulaşmasından itibaren en geç on gün içerisinde ilgilisine tebliğ edilir.",
  "Personel Yön m.18": "MADDE 18- (1) Personel, Türkiye Cumhuriyeti Anayasasına ve kanunlarına sadakatle bağlı kalmak (...) zorundadır. MADDE 19- (1) Personel siyasi partiye üye olamaz, herhangi bir siyasi parti, kişi veya zümrenin yararını veya zararını hedef tutan bir davranışta bulunamaz; (...) dil, ırk, cinsiyet, siyasi düşünce, felsefi inanç, din ve mezhep gibi ayırım yapamaz; hiçbir şekilde siyasi ve ideolojik amaçlı beyanda ve eylemde bulunamaz (...). (2) Personel her durumda Devletin menfaatlerini korumak mecburiyetindedir. MADDE 20- (1) Personel, resmi sıfatının gerektirdiği itibar ve güvene layık olduğunu, hizmet içindeki ve dışındaki davranışlarıyla göstermek zorundadır.",
  "Personel Yön m.24": "MADDE 23- (1) Personel, görevlerini dikkat ve itina ile yerine getirmek ve kendilerine teslim edilen Devlet malını korumak (...) zorundadır. (2) Personelin kasıt, kusur, ihmal veya tedbirsizliği sonucu idare zarara uğratılmışsa, bu zararın ilgili personel tarafından rayiç bedeli üzerinden ödenmesi esastır. MADDE 24- (1) Kişiler kamu hukukuna tabi görevlerle ilgili olarak uğradıkları zararlardan dolayı bu görevleri yerine getiren personel aleyhine değil, ilgili kurum aleyhine dava açarlar. (...) Kurumun, genel hükümlere göre sorumlu personele rücu hakkı saklıdır.",
  "Personel Yön m.25": "MADDE 25- (1) Personel, kamu görevleri hakkında basına, haber ajanslarına veya radyo ve televizyon kurumlarına bilgi veya demeç veremez. Bu konuda gerekli bilgi ancak illerde valiler ve Bakanın yetkili kılacağı görevli tarafından verilebilir. MADDE 26- (1) Personel, görevleri ile ilgili resmi belge, araç ve gereçleri, yetki verilen mahaller dışına çıkaramaz, hususi işlerinde kullanamaz ve kullandıramaz. (...) (2) Personel görevleri icabı kendilerine teslim edilen resmi belge, araç ve gereçleri görevleri sona erdiği zaman iade etmek zorundadır. Bu zorunluluk personelin mirasçılarına da şamildir.",
  "Personel Yön m.33": "(1) Personel hakkındaki ihbar ve şikâyetler, garaz veya mücerret hakaret için, uydurma bir suç isnadı suretiyle yapıldığı ve soruşturma veya yargılamanın tabi olduğu kanuni işlem sonucunda bu isnat sabit olmadığı takdirde, merkezde bu personelin en büyük amiri, illerde valiler, isnatta bulunanlar hakkında kamu davası açılmasını Cumhuriyet savcılığından ister.",
  "Personel Yön m.35": "Madde 35- (1) Personelin kamu hizmetlerini aksatacak şekilde görevden kasıtlı olarak birlikte çekilmeleri veya görevlerine gelmemeleri (...) eylem ve hareketlerde bulunmaları yasaktır. MADDE 36- (1) Personelin greve karar vermeleri, grev tertiplemeleri, ilan etmeleri, bu yolda propaganda yapmaları yasaktır. (2) Personel, herhangi bir greve veya grev teşebbüsüne katılamaz (...). MADDE 37- (1) Personel, (...) tacir veya esnaf sayılmalarını gerektirecek bir faaliyette bulunamaz, ticaret ve sanayi müesseselerinde görev alamaz (...). (3) Eşleri, reşit olmayan veya mahcur olan çocukları, yasaklanan faaliyetlerde bulunan personel, bu durumu onbeş gün içinde bağlı oldukları kuruma bildirmekle yükümlüdürler.",
  "Personel Yön m.38": "MADDE 38- (1) Personelin doğrudan doğruya veya aracı eliyle hediye istemeleri ve görevleri sırasında olmasa dahi menfaat sağlama amacı ile hediye kabul etmeleri veya iş sahiplerinden borç para istemeleri ve almaları yasaktır. MADDE 39- (1) Personelin, denetimi altında bulunan veya kendi görevi (...) ile ilgisi olan bir teşebbüsten, (...) bir menfaat sağlaması yasaktır. MADDE 40- (1) Personele; (...) ikinci görev verilemez; bu kurumlardan her ne ad ile olursa olsun ödeme yapılamaz ve yarar sağlanamaz. MADDE 41- (1) Gizli bilgi; doğrudan kanunlarla veya kanun ve düzenleyici işlemlere dayanarak yetkili makamlar tarafından gizli olarak nitelendirilen bilgidir. (2) Personel, kamu hizmetleri ile ilgili gizli bilgileri görevinden ayrılmış olsa bile Bakanın yazılı izni olmadıkça açıklayamaz.",
  "Personel Yön m.4": "a) Amir: Kadro ve kuruluş yönünden bağlı olunan kimse ile amir olarak yetkilendirilmiş olan diğer kişileri, (...) d) Branş: Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı teşkilatlarındaki alt hizmet alanlarını, (...) i) Makam: Her amirin kuruluş ve kadrolarında temsil ettiği mevkii, (...) k) Üst: Makam, rütbe veya kıdem büyüklüğünü, ifade eder.",
  "Personel Yön m.42": "(1) Günün yirmidört saatinde devamlılık gösteren hizmetlerde çalışan personelin çalışma saat ve şekilleri ile nöbet sistemleri kurumlarınca düzenlenir. (2) Nöbet, kurumlarda amirin münasip göreceği zamanda başlar ve yirmidört saati geçemez. Ancak kadın memurlara; tabip raporlarında belirtilmesi halinde hamilelik boyunca ve doğumdan sonraki iki yıl süreyle gece nöbeti ve gece vardiyası görevi verilemez. Engelli memurlara da isteği dışında gece nöbeti ve gece vardiyası görevi verilemez. (...)",
  "Personel Yön m.45": "(1) Yürütülen hizmetlerin özelliklerini gözönünde bulundurarak personelin başarı, verimlilik ve gayretlerini ölçmek üzere değerlendirme sistemi oluşturulur. Bu sistem elektronik ortamda da düzenlenebilir. (...) (3) Değerlendirme sonuçları personelin görevlere seçiminde, atama ve yer değiştirmesinde, mesleki gelişiminde, statüler arası geçişte, terfiinde, (...) ve ödüllendirilmesinde dikkate alınır. (4) Değerlendirme yılda en az bir kez yapılır.",
  "Personel Yön m.46": "MADDE 46- (4) Bu Yönetmelik kapsamında verilen ödüller; başarı belgesi, üstün başarı belgesi, takdir belgesi, şerit rozet, bröve ve madalyadır. MADDE 47- (2) (...) somut olaylara ve verilere dayalı olarak katkı sağladıkları tespit edilen personele, merkezde Bakan, illerde valiler, ilçelerde kaymakamlar tarafından başarı belgesi verilebilir. Üç defa başarı belgesi alanlara üstün başarı belgesi verilir. MADDE 50- (1) Kendisine tevdi edilen görevleri fiilen hayatını tehlikeye atarak üstün bir cesaret ve feragatle yerine getirdiği tespit edilen personele üstün cesaret ve feragat madalyası (...) verilir.",
  "Personel Yön m.5": "(1) Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığının personel ihtiyacı; a) Jandarma ve Sahil Güvenlik Akademisi tarafından, b) Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı bünyesindeki eğitim komutanlıklarındaki eğitimlerini başarıyla tamamlayanlardan, karşılanır. (...) (4) Personel ihtiyacı, (...) Bakanlık tarafından onaylanan insan gücü planına göre karşılanır.",
  "Personel Yön m.51": "MADDE 51- (1) Görevden uzaklaştırma Devlet kamu hizmetlerinin gerektirdiği hallerde, görevi başında kalmasında sakınca görülecek personel hakkında alınan ihtiyati bir tedbirdir. Görevden uzaklaştırma hususunda 657 sayılı Kanunda belirtilen usul ve esaslara uyulur. MADDE 52- (1) Görevden uzaklaştırmaya yetkililer şunlardır: a) Atamaya yetkili amirler. b) Bakanlık müfettişleri. c) İllerde valiler. ç) İlçelerde kaymakamlar. (2) Valiler ve kaymakamlar tarafından alınan görevden uzaklaştırma tedbiri, personelin kurumuna derhal bildirilir.",
  "Personel Yön m.54": "MADDE 54- (1) Personelin görev sırasında, bu Yönetmelikte veya diğer mevzuatta belirtilen istisnalar saklı kalmak kaydıyla resmi üniforma giymesi zorunludur. MADDE 55- (1) (...) c) Resmi üniformalar eskimiş dahi olsa personel dışındaki kişiler tarafından giyilemez ve bu kişilere verilemez. ç) Branş ve rütbe işaretleri sökülmek suretiyle resmi üniformalar sivil kıyafete dönüştürülerek kullanılamaz (...) e) Resmi üniformalı olarak görev yapan kadın personel, hamileliğini belgelediği takdirde resmi kıyafet yerine sivil kıyafet ile görev yapabilir. (3) Personel; emeklilik, çekilme veya herhangi bir nedenle (...) ilişiği kesildiği tarihten itibaren resmi üniformasını çıkarmaya mecburdur.",
  "Personel Yön m.56": "MADDE 56- (1) Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı personeline, genel ve özel düzenleme getiren kanunlarla verilen özlük hakları saklıdır. (2) Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı kadrolarına atanmış personel ayrıca Asayiş Tazminatından yararlanır.",
  "Personel Yön m.60": "(1) Selamlama, rütbe ve makam farkı olmadan her personel tarafından bütün bir ciddiyet ve hürmetle el ve baş, yalnız baş ile kılıç veya çeşitli teçhizat ve bayraklarla yapılır. (2) Selamlama her yerde ve her zaman yapılır. Astlar, üstlerden evvel selam vermeye mecburdurlar. Aynı rütbede olanlar veya birbirinin rütbesini ayırt edemeyenler birbirini beklemeden selamlarlar. Üstler aynı usul ve esaslarla astlarının selamını alırlar. (3) Personel, siviller ile selamlaşmayı mesleki kurallar, örf, adet ve nezaket kuralları çerçevesinde yapar.",
  "Personel Yön m.7": "(1) Jandarma Genel Komutanlığında bulunan branşlar şunlardır: a) Subaylar 1) Jandarma 2) İstihkâm 3) Muhabere 4) Pilot 5) İkmal 6) Bakım 7) Personel 8) Kimyager 9) Veteriner hekim 10) Mühendis 11) Maliye 12) Öğretmen 13) Bando 14) Tabip 15) Eczacı 16) Diş tabibi 17) Sağlık 18) (Ek:RG-28/5/2020) Hukuk 19) (Ek:RG-16/1/2024) İnsansız Hava Aracı b) Astsubaylar 1) Jandarma 2) İstihkâm 3) Muhabere 4) Uçak ve helikopter teknisyeni 5) İkmal 6) Bakım 7) Personel 8) Maliye 9) Bando 10) Sağlık 11) (Ek:RG-16/1/2024) İnsansız Hava Aracı (2) Sahil Güvenlik Komutanlığında bulunan branşlar şunlardır: a) Subaylar 1) Sahil güvenlik 2) İkmal 3) Mühendis 4) (Ek:RG-28/5/2020) Hukuk b) Astsubaylar 1) Güverte 2) Makine 3) İkmal 4) Uçak bakım 5) İdari 6) Bilgi teknolojileri",
  "Resmî Yazışma m.1": "Bu Yönetmeliğin amacı; güvenli elektronik imza kullanılarak elektronik ortamda veya el yazısıyla atılan imza ile fiziksel ortamda yapılan resmî yazışmalara ilişkin kuralları belirlemek, bilgi veya belge alışverişini, hızlı ve güvenli bir biçimde yürütmek ve uygulama birliğini sağlamaktır. (2) Bu Yönetmelik, bütün kamu kurum ve kuruluşlarını kapsar.",
  "Resmî Yazışma m.10": "Başlık (antet), belgeyi gönderen idarenin adının belirtildiği bölümdür. (2) Başlık, belgenin yazı alanının üst kısmına ortalanarak yazılır. İlk satıra \"T.C.\" kısaltması, ikinci satıra idarenin adı büyük harflerle, üçüncü satıra birimin adı ilk harfleri büyük diğerleri küçük harflerle ortalanarak yazılır. (...) (3) İdarelerin il ve ilçe teşkilatlarında kullanılan başlıklar, (...) 5442 sayılı İl İdaresi Kanunu hükümlerine uygun olarak (...) yazılır. (...) (6) Başlığın yazımında DETSİS'te yer alan başlık kayıtları esas alınır.",
  "Resmî Yazışma m.11": "Belgelerde sayı bulunması zorunludur. \"Sayı:\" sırasıyla; belgenin hazırlanma süreçlerini ifade eden elektronik ortam için \"E\", zorunlu hâller için \"Z\" veya olağanüstü durumlar için \"O\" ibarelerinden uygun olanı, DETSİS'te belirtilen Türkiye Cumhuriyeti Devlet Teşkilatı Numarası, standart dosya planı kodu ile kayıt numarasından oluşur ve bunların arasına kısa çizgi işareti (-) konulur (...). (Örnek: E-67915368-903.07.02-4752) (...) Zorunlu hâllerde (...) (Örnek: Z-67915368-804.02-4757) (...) Olağanüstü durumlarda (...) (Örnek: O-67915368-952.02.05-10).",
  "Resmî Yazışma m.12": "Tarih; sayı ile aynı satırda olmak üzere yazı alanının en sağında gün, ay, yıl olarak rakamla ve aralarına nokta işareti \".\" konularak yazılır (...). Gün ve ay iki haneli, yıl ise dört haneli olarak düzenlenir (Örnek: 01.09.2019). Ay adları, harfle de yazılabilir. Bu durumda gün, ay ve yıl arasına herhangi bir işaret konulmaz (Örnek: 10 Ekim 2019). (2) Belgenin en son yetkili tarafından güvenli elektronik imza ile imzalandığı zamanı gösteren zaman damgasındaki tarih bilgisi, belge tarihi olarak esas alınır (...).",
  "Resmî Yazışma m.13": "\"Konu:\" yan başlığı, \"Sayı:\" yan başlığının bir alt satırına yazılır. Belgenin konusu, yazı alanının dikey orta hizasını geçmeyecek biçimde kelimelerin baş harfleri büyük olarak ve sonuna herhangi bir noktalama işareti konulmaksızın yazılır (...). (2) Konu, belgenin içeriği hakkında kısa ve öz bilgi barındırır (...).",
  "Resmî Yazışma m.14": "Muhatap, belgenin gönderildiği idareyi veya kişiyi belirtir. (...) (2) Muhatabın idare veya özel hukuk tüzel kişisi olması durumunda, adı büyük harflerle ve sonuna yönelme hâl eklerinden uygun olanı getirilerek yazılır. Muhatap idarenin adının yazımında DETSİS'te yer alan kayıtlar esas alınır. (...) (3) (...) Muhatap gerçek kişi ise muhatap bölümüne \"Sayın\" ibaresinden sonra muhatabın adı ilk harfi büyük diğerleri küçük harflerle, soyadı ise büyük harflerle yazılır (...). (6) Birden fazla muhataba iletilecek dağıtımlı belgelerin muhatap bölümüne \"DAĞITIM YERLERİNE\" ibaresi yazılır (...).",
  "Resmî Yazışma m.15": "İlgi, belgenin bağlantılı olduğu diğer belge veya belgelerin belirtildiği bölümdür. (...) (5) İlginin birden fazla olması durumunda, belgeler önceki tarihli olandan başlanarak tarih sırasına göre sıralanır. (...) (7) İlgide, \"… tarihli ve … sayılı …\" ibaresi kullanılır ve ilginin sonuna nokta (.) işareti konulur (...). (9) İlgide belirtilen belge, gerçek kişiden geliyorsa ilgi bölümü \"…'ın … tarihli başvurusu/dilekçesi.\" biçiminde yazılır (...).",
  "Resmî Yazışma m.16": "(4) Paragrafa 1,25 cm içeriden başlanır ve metin iki yana hizalanır. (...) (12) Metnin son bölümü: a) Yazışma yapan makamlar arasındaki hiyerarşi yönünden alt makamlara \"… rica ederim.\", üst ve aynı düzeydeki makamlara \"… arz ederim.\" ibaresiyle bitirilir. b) Üst, aynı düzey ve alt makamlara birlikte dağıtımlı olarak yapılan yazışmalar \"… arz ve rica ederim.\" veya \"… arz/rica ederim.\" ibaresiyle bitirilir. c) Muhatap kısmında ikinci satırda parantez içerisinde birim veya idare ismi belirtilen yazışmalar, birinci satırda yer alan muhatap idare dikkate alınarak arz veya rica ibarelerinden uygun olanı ile bitirilir. ç) 1 sayılı Cumhurbaşkanlığı Kararnamesinin 6 ncı maddesi gereğince bakanlıklarla yapılan yazışmalar, Cumhurbaşkanlığı İdari İşler Başkanı tarafından veya adına imzalandığında \"Rica ederim.\" ibaresiyle bitirilir. d) Belge, imza yetkisini devreden makam adına imzalandığında, yetkiyi devreden makamın hiyerarşik durumu dikkate alınarak arz veya rica ibarelerinden uygun olanı ile bitirilir. e) Muhatabı gerçek kişi olan yazışmalar \"Saygılarımla.\", \"İyi dileklerimle.\" veya \"Bilgilerinize sunulur.\" ibareleriyle bitirilebilir.\n\n(1) Metin alanı, \"Muhatap\" veya varsa \"İlgi\" ile \"İmza\" arasındaki kısımdır. (2) \"İlgi\" ile metin başlangıcı arasında bir satır, \"İlgi\" yoksa belgenin muhatabı ile metin başlangıcı arasında iki satır boşluk bulunur. (3) Metindeki kelime aralarında ve noktalama işaretlerinden sonra bir karakter boşluk bırakılır. Noktalama işaretleri kendinden önce gelen harfe bitişik yazılır. (4) Paragrafa 1,25 cm içeriden başlanır ve metin iki yana hizalanır. Paragraflar arasında satır boşluğu bırakılmaz. İhtiyaç duyulması hâlinde paragraflar harf veya rakam ile sıralanabilir. (5) Birden fazla sayfa tutan üst yazılarda sayı, tarih, konu, muhatap ve ilgi bilgilerine sadece ilk sayfada; imza, ek ve dağıtım bilgilerine ise sadece son sayfada yer verilir. İletişim bilgisine ve belge doğrulama bilgilerine her sayfanın en alt kısmında yer verilir. (6) Metin içinde geçen sayılar, rakamla veya harfle yazılabilir. (7) Dört ve dörtten çok haneli sayılar sondan sayılmak üzere üçlü gruplara ayrılarak yazılır ve araya nokta (.) işareti konulur (Örnek: 1.452; 25.126; 326.197). Sayılarda kesirler virgül (,) ile ayrılır (Örnek: 10.545,72). (8) Belge, Türk Dil Kurumu tarafından hazırlanan Yazım Kılavuzu ve Türkçe Sözlük'ün güncel yayımı esas alınarak dil bilgisi kurallarına göre anlamlı ve özlü olarak yazılır. (...) Ancak muhatabı yabancı ülke veya uluslararası kuruluş olan resmî yazışmalarda yabancı dil kullanılabilir. (...) yabancı dille yazılan belgenin Türkçe tercümesi oluşturulur (...). (9) Metin içinde yer alan alıntılar tırnak içinde ve/veya eğik (italik) olarak yazılabilir. (10) Metin içinde harfler kullanılarak maddelendirmeye/numaralandırmaya ihtiyaç duyulduğunda, Türk alfabesinde yer alan bütün küçük harfler kendilerinden sonra kapama parantez işareti \")\" konularak kullanılır. (11) Metin içinde kısaltma kullanılacak ise ifadenin ilk kullanıldığı yerde açık biçimi, sonra parantez içinde kısaltılmış biçimi yazılır (Örnek: Türkiye Büyük Millet Meclisi (TBMM), Kayıtlı Elektronik Posta (KEP)).",
  "Resmî Yazışma m.17": "Metnin bitiminden itibaren iki ilâ dört satır boşluk bırakılarak, belgeyi imzalayacak olan makam sahibinin adına, soyadına ve bunların altında unvanına, yazı alanının en sağında ortalanarak yer verilir (...). (3) Elektronik ortamda (...) yetkili makam belgeyi güvenli elektronik imzası ile imzalar. (...) (6) Zorunlu hâllerde veya olağanüstü durumlarda imza, ad ve soyadın üzerinde bırakılan boşluğa el yazısıyla atılır. El yazısıyla atılan imza, kaybolmayacak ve kâğıda işlemesini sağlayacak mavi renkli kalemle atılır. (...) (9) Belgeyi imza yetkisi devredilen makam imzaladığında, (...) \"Bakan a.\", \"İdari İşler Başkanı a.\", \"Vali a.\", (...) \"Genel Müdür a.\" veya \"Rektör a.\" biçimindeki ibare (...). (10) Belge vekâleten imzalandığında, (...) \"Genel Müdür V.\", \"Başkan V.\", (...) \"Rektör V.\" veya \"Dekan V.\" biçiminde (...) yazılır.",
  "Resmî Yazışma m.18": "Belgede ek olması hâlinde \"Ek:\" başlığı imza bölümünden sonra uygun satır boşluğu bırakılarak ve yazı alanının solundan başlanarak yazılır. (...) (2) (...) Eklerin sayfa, adet, kişi sayısı gibi açıklayıcı ifadeleri parantez içinde belirtilir (...). (5) Belge eklerinin muhataba gönderilmediği durumlarda \"Ek konulmadı\" veya \"Ek-... konulmadı\" ifadesi yazılır (...).",
  "Resmî Yazışma m.19": "Belgenin birden fazla muhataba gönderilmesi durumunda dağıtım bölümüne yer verilir. (...) (2) Belgenin gereğini yerine getirme durumunda olanlar \"Gereği:\" kısmına, belgenin içeriği hakkında bilgi sahibi olması istenenler ise \"Bilgi:\" kısmına yazılır. \"Gereği:\" kısmı \"Dağıtım:\" başlığının altına, \"Bilgi:\" kısmı ise \"Gereği:\" kısmı ile aynı satıra ve yazı alanının ortasına doğru yazılır (...).",
  "Resmî Yazışma m.20": "Makam oluru alınan belgeler, ilgili birimin yöneticisi tarafından güvenli elektronik imza ile teklif edilir ve oluru alınan makam tarafından güvenli elektronik imza ile imzalanır. (...) (2) Belge, olur için makama sunulurken imza bölümünden sonra uygun boş satır bırakılarak yazı alanının ortasına büyük harflerle \"OLUR\" yazılır. (...) (4) Oluru teklif eden birim ile olur alınan makam arasında başka makamlar varsa bunlar olura katılabilir. (...) \"Uygun görüşle arz ederim.\" ibaresi yazılır (...).",
  "Resmî Yazışma m.21": "Paraf bölümünde tarih, unvan, ad ve soyad bilgileri kısaltma kullanılmadan ast-üst ilişkisine uygun olarak belirtilir. Güvenli elektronik imza ile imzalanan belgeye ait paraf bilgileri, belgenin üstverisinde tutulur (...). Belge muhataba iletildiğinde, belgeye ait paraf bilgileri paylaşılmaz. (2) Elektronik ortamda hazırlanan belgelerde paraf, güvenli elektronik imza veya elektronik onay ile atılır. (...) (3) Zorunlu hâllerde veya olağanüstü durumlarda el yazısıyla atılan paraf, kaybolmayacak ve kâğıda işlemesini sağlayacak mavi kalemle atılır. Fiziksel ortamda hazırlanan belgelerde paraflar, belgenin sadece idarede kalacak nüshasında, yazı alanının sonunda ve sol kenarında yer alır (...).",
  "Resmî Yazışma m.23": "Elektronik ortamda güvenli elektronik imza ile imzalanan belgelerde, \"İletişim bilgileri\" alanının üst sınırını belirleyen çizginin üzerinde iki satırlık alanın ilk satırında \"Bu belge, güvenli elektronik imza ile imzalanmıştır.\" ibaresi bulunur. Belge doğrulama bilgilerini içeren \"belge doğrulama kodu\" ikinci satırda, \"karekod\" ise \"İletişim bilgileri\" alanının en sağ kısmında yer alır (...). (2) Belge doğrulama işlemi, doğrulama kodu ve karekod ile Dijital Türkiye (e-Devlet) üzerinden sağlanır.",
  "Resmî Yazışma m.25": "\"Hizmete Özel\" gizlilik derecesi bulunan belgelerin hazırlanması, kaydedilmesi, saklanması, gönderilmesi, alınması ve diğer işlemleri elektronik ortamda gerçekleştirilir. (2) \"Özel\" ve üstü gizlilik dereceli belgelerin hazırlanması, kaydedilmesi, saklanması, gönderilmesi, alınması ve diğer işlemler ilgili mevzuatta belirtilen hükümlere uygun olarak fiziksel ortamda gerçekleştirilir. (3) Belgenin imzacısı olan yetkili makam, belgeye ait gizlilik derecesinin belirlenmesinden sorumludur.",
  "Resmî Yazışma m.26": "Güvenli elektronik imza ile imzalanan süreli belgelerde \"ACELE\" veya \"GÜNLÜDÜR\" ibaresine üstveride ve üst yazı üzerinde yer verilir. (...) (2) \"ACELE\" ibaresi taşıyan belgeye derhâl ve süratle; \"GÜNLÜDÜR\" ibaresi taşıyan belgeye belirtilen süre içinde cevap verilir. (3) (...) süreli belgelerde \"ACELE\" veya \"GÜNLÜDÜR\" ibaresi yazı alanının sağ üst köşesinde kırmızı renkli olarak belirtilir (...). (4) \"KİŞİYE ÖZEL\" ibaresi, belgenin ilgilisine teslim edilmesini ve sonrasında yürütülecek süreci ifade eder. (5) \"KİŞİYE ÖZEL\" ibaresi taşıyan belgenin zarfı açılmadan zarf üzerinde yer alan bilgiler, yetkili birimce (...) kaydedilir ve ilgilisine teslim edilir (...).",
  "Resmî Yazışma m.28": "Güvenli elektronik imza ile imzalanan belgelerde asgari olarak e-Yazışma Teknik Rehberi'nde belirtilen üstveri elemanları kullanılır. (...) (3) Elektronik ortamda güvenli elektronik imza ile imzalanan belgenin üstveri elemanları, belgenin ayrılmaz bir bütünüdür. Tarih ve sayı gibi belge görüntüsü üzerinde yer alan bilgiler ile üstveride yer alan bilgiler arasında fark olamaz.",
  "Resmî Yazışma m.29": "Güvenli elektronik imza ile imzalanan belgenin çoğaltılması, yetkilendirilmiş görevliler tarafından çıktı alınarak gerçekleştirilir. Çoğaltılan güvenli elektronik imzalı belgenin doğrulama işlemi, 23 üncü maddenin ikinci fıkrasında belirtildiği şekilde yapılır. (2) Zorunlu hâllerde veya olağanüstü durumlarda ya da bu Yönetmeliğin yürürlüğe girdiği tarihten önce fiziksel ortamda hazırlanan bir belgeden örnek çıkartılması hâlinde, çoğaltılan belgenin uygun bir yerine \"ASLI GİBİDİR\" ibaresi konulur ve yetkilendirilmiş görevli tarafından ad, soyad, unvan ve tarih belirtilmek suretiyle imzalanır. Bu şekilde çoğaltılan belge, asıl belge gibi kabul edilir.",
  "Resmî Yazışma m.3": "c) Belge: (...) güvenli elektronik imza ya da el yazısıyla imzalanmış ve kayıt altına alınmış her türlü bilgiyi, p) Üstveri: Bir belgeyi tanımlayan gönderici, konu, tarih, sayı ve benzeri tüm bilgileri, r) Üst yazı: Belgenin, varsa ek veya ekleri hariç kısmını, ifade eder.\n\na) Aidiyet zinciri: Belgenin hazırlanmasından tasfiyesine kadar olan sürecini, b) Arşiv imza: Kriptografik metodların zaman içerisinde koruyucu özelliğini yitirmesine karşı, periyodik olarak alınan zaman damgası ile korunan elektronik imzayı, e) Elektronik onay: Güvenli elektronik imza kullanılmayan durumlarda paraf yerine geçecek kaydın elektronik ortamda alınmasını, ifade eder.",
  "Resmî Yazışma m.30": "Güvenli elektronik imza ile imzalanan belgelerin gönderilmesi ve alınması işlemlerinin, elektronik ortamda ilgili mevzuatla yetki verilmiş üçüncü bir taraf aracılığıyla kayıt altına alınarak yapılması esastır. (...) (4) İdare, başka bir idareden kendisine resmî yazışma kapsamında iletilen ve e-Yazışma Teknik Rehberi'nde tanımlanan kurallara uygun şekilde hazırlanmamış bir belgeyi reddetme hakkına sahiptir. Bu durumda, kendisine iletilen belgeyi reddeden idare, gönderen idareye bu durumu sebepleriyle birlikte belgenin kendisine ulaştığı tarihi takip eden ikinci iş gününün sonuna kadar bildirir.",
  "Resmî Yazışma m.31": "(1) Muhatabına elektronik olarak iletiminin mümkün olmadığı durumlarda, yetkilendirilmiş görevliler tarafından çıktısı alınan güvenli elektronik imzalı belge, elektronik ortamdaki aslına erişim amacı ile fiziksel ortamda gönderilir. (...) (5) İdareler, fiziksel ortamda alınan belgeler için gelen belge kaydında kullanacakları etikette/kaşede en az Örnek 23'te belirtilen unsurlara yer verir. Etiket/kaşe, üst yazının ilk sayfasının ön veya arka yüzüne basılır. (6) Birime fiziksel ortamda gelen belgelerle ilgili havale, talimat ve benzeri işlemler, üst yazının ilk sayfasının ön veya arka yüzüne kaşe basılarak belge üzerinde gösterilebilir. Bu kaşenin şekli ilgili birimler tarafından belirlenir. (7) Kişiler tarafından idareye yazılan dilekçelerin; '… arz ederim.' şeklinde bitirilmemesi veya '… rica ederim.' ibaresiyle ya da başka ibarelerle bitirilmesi dilekçenin işleme alınmasına engel değildir.",
  "Resmî Yazışma m.33": "İdare içi ve idare dışı görüş, bilgi ve belge talep yazıları günlü yazılır. İdareler, ilgili mevzuattaki özel hükümler saklı kalmak kaydıyla süre belirtilmeyen belge taleplerini, talebin kendilerine ulaşmasından itibaren en geç beş iş günü; süre belirtilmeyen bilgi ve görüş taleplerini ise talebin kendilerine ulaşmasından itibaren en geç on beş iş günü içinde yerine getirir. (...)",
  "Resmî Yazışma m.38": "MADDE 36- (...) (3) Bu Yönetmelik ile ilgili (...) ortaya çıkabilecek tereddütleri gidermeye ve gerektiğinde uygulamaya yönelik esasları düzenlemeye Cumhurbaşkanlığı İdari İşler Başkanlığı yetkilidir. MADDE 38- (1) Bu Yönetmelik yayımını takip eden ayın birinci günü yürürlüğe girer. MADDE 39- (1) Bu Yönetmelik hükümlerini Cumhurbaşkanı yürütür.",
  "Resmî Yazışma m.4": "Kamu kurum ve kuruluşlarınca resmî yazışmalar, elektronik ortamda e-Yazışma Teknik Rehberi'ne uygun olarak hazırlanan ve güvenli elektronik imza ile imzalanan belgelerle yapılır. Bu belgeler, elektronik ortamda muhatapları ile paylaşılır ve elektronik ortamda saklanır. Ayrıca güvenli elektronik imza ile imzalanan belgeler, çıktısı alınarak el yazısıyla atılan imza ile imzalanmaz ve fiziksel ortamda saklanmaz. (2) Zorunlu hâllerde veya olağanüstü durumlarda resmî yazışmalar, el yazısıyla imzalanan belgelerle yapılır. Bu belgelerin gönderilmesi ve saklanması fiziksel ortam şartlarına göre gerçekleştirilir.",
  "Resmî Yazışma m.5": "Elektronik ortamda güvenli elektronik imza ile imzalanan belgeler tek nüsha olarak hazırlanır. (2) Zorunlu hâllerde veya olağanüstü durumlarda hazırlanacak belgeler, paraflı nüshası hazırlayan idarede kalacak şekilde en az iki nüsha olarak düzenlenir.",
  "Resmî Yazışma m.6": "MADDE 6- (1) Belgeler, A4 (210x297 mm) boyutu dikkate alınarak hazırlanır. (2) Belge ekleri farklı form, format veya ebatlarda hazırlanabilir. (3) Zorunlu hâllerde veya olağanüstü durumlarda hazırlanacak belgelerin üst yazıları için kâğıdın bir yüzü kullanılır. Ancak üst yazının ekleri için kâğıdın her iki yüzü de kullanılabilir. MADDE 7- (1) Hazırlanan belgelerde \"Times New Roman\" veya \"Arial\" yazı tipi normal yazı stilinde kullanılır. Harf büyüklüğünün Times New Roman için 12 punto, Arial için 11 punto olması esastır. Ancak gerekli hâllerde yazı alanında harf büyüklüğü 9 puntoya, iletişim bilgileri kısmında ise 8 puntoya kadar düşürülebilir. Belge eklerinde farklı yazı tipi ve harf büyüklüğü kullanılabilir.",
  "Resmî Yazışma m.8": "Belgenin yazı alanı sayfanın üst, sol ve sağ kenarından 1,5 cm boşluk bırakılarak düzenlenir. İdare, logo kullanmak istediğinde sayfanın üst boşluğu 0,5 cm olarak düzenlenir.",
  "Resmî Yazışma m.9": "İdareler, tercihen kurumsal logo kullanabilir. Logo, tek kullanıldığında belgenin en üst orta kısmında \"T.C.\" ibaresini ortalayacak şekilde veya \"Başlık\" alanını ortalayacak şekilde belgenin üst sol kısmında yer alır (...). Belge üzerinde iki ayrı logo kullanıldığında ise \"Başlık\" alanını ortalayacak şekilde hiyerarşi yönünden üst olan idareye ait logo solda, alt olan idareye ait logo sağda kullanılır. (...) Belge üzerinde en fazla iki logo kullanılabilir (...).",
  "Sözleşmeli Sb/Asb m.10": "(Madde 10) Sözleşmeli astsubay adayları, ön sözleşme yapılarak askerî eğitime alınırlar. Bu eğitimi başarı ile tamamlayanlardan yönetmelikte belirtilen şartları taşıyanlarla sözleşme yapılır ve bu kişiler astsubay çavuş rütbesine nasbedilirler. Sözleşme süreleri; üç yıldan az ve dokuz yıldan fazla olmamak şartıyla, hizmet gerekleri ve yetiştirme maliyetlerine bağlı olarak kuvvet, sınıf ve branşlara göre yönetmelikte belirlenir. Yönetmelikte belirlenen şartları taşıyanların talepleri halinde sözleşmeleri yenilenebilir. Sözleşme süreleri; (...) seferberlik, savaş veya silahlı çatışmayı gerektirecek hal ile savaş hallerinde Kuvvet Komutanları, Jandarma Genel Komutanı ve Sahil Güvenlik Komutanının göstereceği lüzum üzerine, durumun devamı müddetince ilgisine göre Milli Savunma Bakanlığı veya İçişleri Bakanlığının onayı ile talebe bakılmaksızın uzatılabilir. (...) (Madde 11) Sözleşmeli astsubaylardan yönetmelikte belirtilen şartları taşıyanlar, talepleri halinde muvazzaf astsubaylığa geçirilebilirler. Muvazzaf astsubaylığa geçiş için, Türk Silâhlı Kuvvetlerindeki dördüncü fiilî hizmet yılı başından itibaren onikinci fiilî hizmet yılının bitimine kadar başvuru yapılabilir. Bu şekilde muvazzaf astsubaylığa geçirilenler; astsubay nasbedildikleri tarihten başlamak üzere onbeş yıl hizmet etmedikçe istifa edemezler.",
  "Sözleşmeli Sb/Asb m.12": "Sözleşmeli subay ve astsubayların rütbe bekleme süreleri hakkında, 27.7.1967 tarihli ve 926 sayılı Kanunda muvazzaf subay ve astsubaylar için belirlenen süreler uygulanır. (...) Her sözleşme süresinin sona erme tarihinden en az üç ay önce taraflar sözleşmeyi yenileyeceklerine dair yazılı bildirimde bulunmadıkları takdirde, sözleşme kendiliğinden sona erer. Sözleşmeli subay veya astsubaylar, sözleşme süreleri sona ermeden sözleşmelerini tek taraflı olarak fesh edemezler.",
  "Sözleşmeli Sb/Asb m.3": "a) Ön sözleşme: Türk Silâhlı Kuvvetleri birlik, karargâh, kurum ve kuruluşları ile sözleşmeli subay veya sözleşmeli astsubay adayları arasında; askerî eğitime alınmaları konusunda yapılan ve askerî eğitim dönemi başlangıcı ile subaylık veya astsubaylık nasıp onayı tarihine kadar geçecek süreyi kapsayan sözleşmeyi, b) Sözleşme : Türk Silâhlı Kuvvetleri birlik, karargâh, kurum ve kuruluşları ile sözleşmeli subay ve astsubay adaylarından askerî eğitimi başarıyla tamamlayanlar arasında yapılan ve üç yıldan az, dokuz yıldan fazla olmamak üzere hizmet yükümlülüğü getiren, örneğine göre hazırlanmış olan yazılı bir belgeyi, c) Sözleşmeli subay adayı : Sözleşmeli subay yetiştirilmek amacıyla ön sözleşme yapılarak askerî eğitime alınanları, d) Sözleşmeli astsubay adayı : Sözleşmeli astsubay yetiştirilmek amacıyla ön sözleşme yapılarak askerî eğitime alınanları, e) Sözleşmeli subay : Bu Kanunda öngörülen esaslara göre, kendileri ile sözleşme yapılarak subay nasbedilen teğmen, üsteğmen ve yüzbaşı rütbelerini haiz subayları, f) Sözleşmeli astsubay : Bu Kanunda öngörülen esaslara göre, kendileri ile sözleşme yapılarak astsubay nasbedilen; astsubay çavuş, astsubay kıdemli çavuş, astsubay üstçavuş ve astsubay kıdemli üstçavuş rütbelerini haiz astsubayları, g) Askeri eğitim: Sözleşmeli subay ve sözleşmeli astsubay adaylarına okul, kurum, sınıf okulu, kıtalar veya eğitim merkezlerinde yaptırılacak olan temel askerlik ile subaylık veya astsubaylık anlayışı kazandırma eğitimini, h) Emsal: Sözleşmeli subaylar için subaylığa nasbedildikleri yıl harp okullarından mezun olan muvazzaf subayları; sözleşmeli astsubaylar için ise astsubaylığa nasbedildikleri yıl astsubay meslek yüksekokullarından mezun olan muvazzaf astsubayları, ı) Sözleşme yılı: Sözleşmenin yürürlüğe girdiği ay ve günü başlangıç olarak kabul eden ve bu tarihten itibaren geçen her bir yıllık süreyi, ifade eder.",
  "Sözleşmeli Sb/Asb m.4": "Sözleşmeli subay kaynaklarını; en az dört yıllık fakülte veya yüksekokulları bitirenlerden düzeltilmemiş nüfus kaydına göre müracaat yapılan yılın ocak ayının ilk günü itibarıyla yirmiyedi yaşını, lisansüstü eğitimini tamamlamış olanlardan otuziki yaşını bitirmemiş olanlar teşkil eder. Askeri okullardan ve Türk Silahlı Kuvvetlerinden her ne sebeple olursa olsun ilişikleri kesilen personel, Türk Silahlı Kuvvetlerine sözleşmeli subay olarak alınmaz. Ancak, askerlik yükümlülüğünü yerine getirmekte olanlar veya terhis edilenler sözleşmeli subay olabilirler. Sözleşmeli subaylık için genel olarak aşağıdaki nitelikler aranır: a) Türk vatandaşı olmak. b) Bu Kanunda belirtilen öğrenim ile ilgili koşulları taşımak. c) Sağlık ile ilgili Yönetmelikte belirtilen şartları taşımak. d) Kamusal hakları kullanmaktan yoksun bırakılmamış olmak. e) (...) yüz kızartıcı veya şeref ve haysiyet kırıcı suçlar ile (...) suçlardan birisinden (...) mahkum olmamak. f) Güvenlik soruşturması olumlu sonuçlanmış olmak. g) Yapılacak olan sınavlarda başarılı olmak. (...) Askeri hakim sınıfına, sözleşmeli subay statüsünde personel alınmaz.",
  "Sözleşmeli Sb/Asb m.6": "Sözleşmeli subay adayları ön sözleşme yapılarak askerî eğitime alınırlar. Bu eğitimi başarı ile tamamlayanlardan yönetmelikte belirtilen şartları taşıyanlarla sözleşme yapılır ve bu kişiler teğmen rütbesine nasbedilirler. Sözleşme süreleri üç yıldan az ve dokuz yıldan fazla olmamak şartıyla, hizmet gerekleri ve yetiştirme maliyetlerine bağlı olarak kuvvet, sınıf ve branşlara göre yönetmelikte belirlenir. Yönetmelikte belirlenen şartları taşıyanların talepleri halinde sözleşmeleri yenilenebilir. Ancak sözleşmeli subaylardan rütbe yaş haddini dolduranlar hakkında 8.6.1949 tarihli ve 5434 sayılı Kanun hükümleri uygulanır. Sözleşme süreleri; terörle mücadele sırasında veya bu görevlerden dolayı alıkonulma ya da kaybolma hâli ve (...) seferberlik, savaş veya silahlı çatışmayı gerektirecek hal ile savaş hallerinde Kuvvet Komutanları, Jandarma Genel Komutanı ve Sahil Güvenlik Komutanının göstereceği lüzum üzerine, durumun devamı müddetince ilgisine göre Milli Savunma Bakanlığı veya İçişleri Bakanlığının onayı ile talebe bakılmaksızın uzatılabilir.",
  "Sözleşmeli Sb/Asb m.7": "Sözleşmeli subaylardan yönetmelikte belirtilen şartları taşıyanlar, talepleri halinde muvazzaf subaylığa geçirilebilirler. Muvazzaf subaylığa geçiş için, Türk Silâhlı Kuvvetlerindeki yedinci fiilî hizmet yılı başından itibaren onikinci fiilî hizmet yılının bitimine kadar başvuru yapılabilir. Bu şekilde muvazzaf subaylığa geçirilenler; subay nasbedildikleri tarihten başlamak üzere onbeş yıl hizmet etmedikçe istifa edemezler. Muvazzaf subaylığa geçirileceklerde, 27.7.1967 tarihli ve 926 sayılı Kanunun 14 üncü maddesindeki yaş ile ilgili hükümler uygulanmaz. Sözleşmeli subaylardan muvazzaf subaylığa geçirilenler hakkında muvazzaf subayların tâbi olduğu ilgili mevzuat hükümleri uygulanır. Türk Silahlı Kuvvetleri bünyesinde bulunan ve ön lisans, lisans ve lisansüstü düzeyde eğitim ve öğretim yapan kurum ve kuruluşların öğretim üyesi kadrolarında atamalı olarak görev yapanlarda yukarıda belirtilen fiili hizmet yılı şartı aranmaz.",
  "Sözleşmeli Sb/Asb Yön m.12": "Madde 12 - Sözleşme süreleri en az üç yıl olarak düzenlenir. Sözleşme sürelerinin azami sınırı dokuz yıldır. Kuvvet Komutanlıkları, Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı sözleşme sürelerini azami ve asgari sözleşme sınırlarını aşmamak kaydıyla her sınıf ve branşa göre çıkaracakları yönergelerde ayrıca belirleyebilirler.",
  "Sözleşmeli Sb/Asb Yön m.13": "Madde 13 - Sözleşmeli subayların ve astsubayların rütbe bekleme süreleri hakkında, 27/07/1967 tarihli ve 926 sayılı Türk Silahlı Kuvvetleri Personel Kanununda muvazzaf subaylar ve astsubaylar için belirlenen süreler uygulanır. Sözleşmeli subaylardan üst rütbede kadro açığı bulunmadığı için terfi edemeyenler, terfi şartlarını haiz olmak kaydıyla sözleşme süresinin sonuna kadar derece ilerlemesi yaparlar. (...)",
  "Sözleşmeli Sb/Asb Yön m.14": "Madde 14 - (...) a) Sözleşmeli subay ve astsubaylardan, sözleşmesini yenilemek isteyenler sözleşme süresinin sona erme tarihinden 6 ay önceden başlamak suretiyle dilekçe ile ilk amirine müracaat eder. (...) d) Her sözleşme süresinin sona erme tarihinden en az 3 ay önce taraflar sözleşmeyi yenileyeceklerine dair yazılı bildirimde bulunmadıkları taktirde sözleşme kendiliğinden sona erer. (...) c) Sözleşmeli subay ve astsubay nasbedildikten sonra; yabancı memleketlere 6 ay veya daha uzun süreli öğrenim, staj, kurs (...) gidenlerin sözleşme süreleri, gidiş ve dönüş tarihleri arasında geçen sürenin iki katı kadar (...) uzatılır.",
  "Sözleşmeli Sb/Asb Yön m.15": "MADDE 15 – (...) Sözleşmeli subay ve sözleşmeli astsubaylar, sözleşme süreleri sona ermeden sözleşmelerini tek taraflı olarak feshedemezler. Sözleşmeli subay veya sözleşmeli astsubay adaylarının ön sözleşmeleri, aşağıdaki nedenlerle süresinin bitiminden önce feshedilebilir: a) Askerî eğitim esnasında yetkili kurullarca başarısız veya disiplinsiz olduğuna karar verilmek. (...) ç) Askerî eğitimin üçte birine çeşitli nedenlerle katılmamak. Sözleşmeli subay veya sözleşmeli astsubayların sözleşmeleri, aşağıdaki nedenlerle (...) feshedilebilir: (...) b) Disiplinsizlik ve ahlaki durum nedeniyle (...) görev yapamayacağı (...) anlaşılmak. c) Yetersizlik nedeniyle kendisinden istifade edilemeyeceği (...) anlaşılmak. (...)\n\nSözleşmeli subay veya sözleşmeli astsubay adaylarının ön sözleşmeleri, aşağıdaki nedenlerle (...) feshedilebilir: a) Askerî eğitim esnasında yetkili kurullarca başarısız veya disiplinsiz olduğuna karar verilmek. b) Yetkili sağlık kurullarınca askerî eğitime ve/veya göreve devam edemez kararı verilmiş olmak. c) (...) şartlarından herhangi birini taşımadığı sonradan anlaşılmak veya (...) kaybetmek. ç) Askerî eğitimin üçte birine çeşitli nedenlerle katılmamak. (...) Sözleşmeli subay veya sözleşmeli astsubayların sözleşmeleri, aşağıdaki nedenlerle (...) feshedilebilir: a) (...) eğitim ve öğretimde (...) başarısız olmak. b) Disiplinsizlik ve ahlaki durum nedeniyle (...) görev yapamayacağı (...) anlaşılmak. c) Yetersizlik nedeniyle kendisinden istifade edilemeyeceği (...) anlaşılmak. ç) (...) yüz kızartıcı/askerî suçlardan (...) mahkûm olmak. d) Taksirli suçlar hariç (...) bir ay ve daha fazla süreli hürriyeti bağlayıcı bir cezaya mahkûm olmak. e) (...) son bir yıl içinde toplamda otuz gün ve daha fazla oda hapsi veya hizmet yerini terk etmeme cezası (...) veya (...) toplam sekiz defa veya daha fazla disiplin cezası almak. f) Yasadışı siyasi, yıkıcı, bölücü, irticai faaliyetlerde bulunmak (...). g) (...) nitelik ve şartlardan herhangi birini (...) kaybetmek. ğ) Yabancı uyruklu kişilerle (...) evlilikleri (...) uygun görülmemek (...) veya Türk vatandaşlığını kaybetmek (...). h) Yetkili sağlık kurullarınca (...) göreve devamı mümkün olmamak. ı) (...) sınıflarında görev yapamayacaklarına (...) karar verilenlerden (...) istihdamına gerek duyulmamak. i) (...) bir sözleşme yılı içinde alınan hava değişimi, istirahat ve benzeri sıhhi izin süresi toplamı doksan günü geçmek. j) Haklarında yüksek disiplin kurulları tarafından Silahlı Kuvvetlerden ayırma cezası verilmiş olmak.",
  "Sözleşmeli Sb/Asb Yön m.16": "Madde 16 - (...) a) Sözleşmeli subay olarak yetiştirilecekler, 926 sayılı (...) EK-VI sayılı cetvelde asteğmenler için öngörülen dokuzuncu derecenin birinci kademe aylığı (...) yararlandırılırlar. b) Sözleşmeli astsubay olarak yetiştirilecekler, (...) 3269 sayılı Uzman Erbaş Kanununa bağlı (...) uzman onbaşılar gibi, on birinci derecenin birinci kademe aylığı (...) yararlandırılırlar. (...) askerî eğitim süresince iaşe ve ibateleri Devlet tarafından karşılanır. MADDE 17 – Sözleşmeli subay ve sözleşmeli astsubaylar, emsali rütbe ve derecedeki muvazzaf subay ve astsubaylar hakkında uygulanan aylık, tazminat, yan ödeme ve diğer mali ve sosyal haklardan aynen istifade ederler. Sözleşmeli subaylardan on beşinci, sözleşmeli astsubaylardan on sekizinci fiili hizmet yılını tamamlayanlardan (...) rütbe verilmeksizin bir üst dereceye yükseltilirler (...). Madde 18 - (...) ön sözleşme yapılması ile birlikte 5434 sayılı Kanun ile ilgilendirilirler (...). Sözleşmeli subaylar ve astsubaylar aynı zamanda Ordu Yardımlaşma Kurumunun daimi üyesidirler. Madde 19 – (...) a) (...) son olarak aldıkları net maaşın 2 katının hizmet yılıyla çarpımı tutarında tazminat verilir. (...) hizmet yılı olarak en fazla dokuz yıl esas alınır. (...) yabancı memleketlere (...) gitmiş olanlardan (...) Devletçe yapılan masrafların dört katı ayrıca tazminat olarak alınır.",
  "Sözleşmeli Sb/Asb Yön m.22": "MADDE 22 – (...) Sözleşmeli subay ve sözleşmeli astsubaylar ile bunların bakmakla yükümlü oldukları kimselerin, sözleşme süresince, sosyal hakları ve sağlık işlemlerinde (...) 211 sayılı Türk Silahlı Kuvvetleri İç Hizmet Kanununun muvazzaf subay ve astsubaylara ilişkin hükümleri uygulanır. (...) a) Kendi kusurları olmaksızın idare tarafından sözleşmeleri yenilenmeyenler (...) hizmet edilen süre kadar ve en çok on yılı, b) Sözleşme süresi sonunda kendi istekleriyle sözleşmeleri yenilenmeyenler (...) hizmet edilen sürenin yarısı kadar ve en çok beş yılı geçmemek üzere muayene ve tedavi hizmetleri askerî hastanelerde (...) ücretsiz olarak verilmeye devam edilir.",
  "Sözleşmeli Sb/Asb Yön m.23": "MADDE 23 – Giyim, kuşam ve istihkakların verilme usulleri; a) Sözleşmeli subay adayları için yedek subay adaylarında, b) Sözleşmeli astsubay adayları için astsubay naspedilmek üzere temel askerlik eğitimine tabi tutulan adaylarda, c) Sözleşmeli subay ve sözleşmeli astsubaylar için ise muvazzaf subay ve astsubaylarda olduğu gibidir. Madde 24 - Sözleşmeli subaylara askeri eğitimi müteakip (...) 4608 sayılı Kanuna göre, sözleşmeli astsubaylara da (...) 1468 sayılı Kanuna göre bir defaya mahsus olmak üzere zati tabanca verilir. (...) 15 inci maddenin dördüncü fıkrasının (a)-(ğ) bentlerinde sayılan nedenlerden herhangi biriyle (...) ilişiği kesilenler ile dokuzuncu fiili hizmet yılından önce ayrılanların, zati tabancaları geri alınır. (...) Madde 25 - Sözleşmeli subay ve astsubaylar, (...) Milli Savunma Bakanlığı veya İçişleri Bakanlığına (...) ait konutlardan, kiralama sisteminden ve lojman tazminatından emsali muvazzaf subay ve astsubaylar gibi istifade ederler.",
  "Sözleşmeli Sb/Asb Yön m.26": "Madde 26 – (...) Sözleşmeli subay ve sözleşmeli astsubaylar hakkında muvazzaf subay ve astsubaylara uygulanan disiplin ve ceza hükümleri, sözleşmeli subay adayları hakkında yedek subay adaylarına uygulanan disiplin ve ceza hükümleri; sözleşmeli astsubay adayları hakkında ise astsubay naspedilmek üzere temel askerlik eğitimine tabi tutulan adaylara uygulanan disiplin ve ceza hükümleri tatbik edilir. Jandarma Genel Komutanlığına mensup sözleşmeli subay ve sözleşmeli astsubayların mülki hizmete ilişkin suçlarında 10/3/1983 tarihli ve 2803 sayılı Jandarma Teşkilat, Görev ve Yetkileri Kanununun ilgili hükümleri uygulanır.",
  "Sözleşmeli Sb/Asb Yön m.3": "a) (...) Ön sözleşme: Türk Silahlı Kuvvetleri birlik, karargâh, kurum ve kuruluşları ile sözleşmeli subay veya sözleşmeli astsubay adayları arasında; askerî eğitime alınmaları konusunda yapılan ve askerî eğitim dönemi başlangıcı ile subaylık veya astsubaylık nasıp kararnamesinin onay tarihine kadar geçecek süreyi kapsayan sözleşmeyi (...), b) Sözleşme: Türk Silahlı Kuvvetleri birlik, karargah, kurum ve kuruluşları ile sözleşmeli subay veya astsubay adaylarından askeri eğitimi başarı ile tamamlayanlar arasında yapılan ve üç yıldan az, dokuz yıldan fazla olmamak üzere hizmet yükümlülüğü getiren (...) yazılı bir belgeyi, (...) c) Sözleşmeli Subay/Astsubay Aday Adayı: Sözleşmeli subay veya astsubay adayı olmak için müracaat etmiş ancak henüz kendileriyle ön sözleşme yapılmamış olanları, ç) Sözleşmeli Subay Adayı: Sözleşmeli subay yetiştirilmek amacıyla ön sözleşme yapılarak askeri eğitime alınanları, (...)\n\ne) Sözleşmeli Subay: Bu Yönetmelikte öngörülen esaslara göre, kendileri ile sözleşme yapılarak subay nasbedilen teğmen, üsteğmen ve yüzbaşı rütbelerini haiz subayları, f) Sözleşmeli Astsubay: (...) astsubay nasbedilen astsubay çavuş, astsubay kıdemli çavuş, astsubay üstçavuş ve astsubay kıdemli üstçavuş rütbelerini haiz astsubayları, (...) ğ) (...) Emsal: Sözleşmeli subaylar için subaylığa nasbedildikleri yıl harp okullarından mezun olan muvazzaf subayları; sözleşmeli astsubaylar için ise astsubaylığa nasbedildikleri yıl astsubay meslek yüksekokullarından mezun olan muvazzaf astsubayları, (...)",
  "Sözleşmeli Sb/Asb Yön m.30": "Madde 30 - Sözleşmeli subay ve astsubay aday adayları (...) belirleyeceği makamlara, çıkarılacak yönergede belirtilen usullere uygun olarak müracaat ederler. Müracaatları kabul edilenler fiziki yetenek, değerlendirme testi, genel kültür ve meslek bilgisi ile mülakata tabi tutulurlar. (...) Yapılacak değerlendirmeler sonucunda başarılı olanlardan tam teşekküllü askeri hastanelerden sınıfında 'Sözleşmeli Subay veya Astsubay Olur' kararlı sağlık raporu alanlardan ihtiyaç kadarı ile ön sözleşme yapılır, bunlar sözleşmeli subay veya astsubay adayı olurlar.",
  "Sözleşmeli Sb/Asb Yön m.31": "MADDE 31 – (...) Sözleşmeli subay ve astsubay adayları ile sözleşmeli subay ve astsubaylarla (...) ön sözleşme ve ön sözleşmeden sonraki ilk sözleşmeyi yapmaya yetkili makamlar, kuvvet komutanlıkları, Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı Personel Temin Merkezi Komutanı veya eşidi birim amiridir. (...) Müteakip sözleşmeleri yapmaya yetkili makamlar, kuvvet komutanlıkları, Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı Tayin/Atama Daire Başkanı veya eşidi birim amiridir.",
  "Sözleşmeli Sb/Asb Yön m.32": "Madde 32 – (...) Askeri eğitimi başarıyla tamamlayan sözleşmeli subay ve astsubay adayları kendilerinin istemesi ve idarenin uygun görmesi üzerine EK-A ve EK-B'de örneği gösterilen belgeyi imzalayarak subaylığa veya astsubaylığa nasıp (...) onayları çıktıktan sonra subay veya astsubay nasbedilirler. Bu personelin subaylık/astsubaylık nasıpları hangi tarihte olursa olsun, kademe ilerlemesi veya üst rütbeye yükselmelerine esas olacak nasıplarında kararname takvim yılının 30 Ağustos'u itibar olunur. (...) Ancak sözleşme yenileme tarihleri için ilk sözleşme imzaladıkları tarih esas alınır. (...)",
  "Sözleşmeli Sb/Asb Yön m.5": "Sözleşmeli subay kaynaklarını; en az dört yıllık fakülte veya yüksekokulları bitirenlerden (...) müracaat yapılan yılın Ocak ayının ilk günü itibariyle yirmi yedi yaşını, lisansüstü eğitimini tamamlamış olanlardan otuz iki yaşını bitirmemiş olanlar (...) teşkil eder. Sözleşmeli astsubay kaynaklarını; (...) a) Dört yıl veya daha fazla süreli yüksek öğrenimi bitirenler için yirmi yedi yaşını, b) Dört yıldan daha az süreli yüksek öğrenimi bitirenler için yirmi dört yaşını, bitirmemiş olanlardan (...) teşkil eder. Askerî okullardan ve Türk Silahlı Kuvvetlerinden her ne sebeple olursa olsun ilişikleri kesilen personel, Türk Silahlı Kuvvetlerine sözleşmeli subay veya sözleşmeli astsubay olarak alınmaz. (...) Askerî hâkim sınıfına, sözleşmeli subay statüsünde personel alınmaz.",
  "Sözleşmeli Sb/Asb Yön m.8": "b) (...) 1) Muvazzaf subaylığa geçiş sınavları yazılı sınav, fiziki yeterlilik ve değerlendirme testi ile mülakat sınavı olmak üzere üç aşamalı yapılır. (...) 5) (...) Mülakat sınavına katılan adayın asgari yetmiş puan almış olma şartı aranır. 6) Başarı sıralamasına esas değerlendirme notu, yazılı sınav notunun %55'i, fiziki yeterlilik ve değerlendirme testinde alınan notun %15'i ve mülakat sınav notunun %30'unun toplamına, sicil notu ortalaması ile (...) mükâfat puanının eklenmesi (...) ile belirlenir.",
  "TCK m.1": "(1) Ceza Kanununun amacı; kişi hak ve özgürlüklerini, kamu düzen ve güvenliğini, hukuk devletini, kamu sağlığını ve çevreyi, toplum barışını korumak, suç işlenmesini önlemektir. Kanunda, bu amacın gerçekleştirilmesi için ceza sorumluluğunun temel esasları ile suçlar, ceza ve güvenlik tedbirlerinin türleri düzenlenmiştir.",
  "TCK m.2": "(1) Kanunun açıkça suç saymadığı bir fiil için kimseye ceza verilemez ve güvenlik tedbiri uygulanamaz. Kanunda yazılı cezalardan ve güvenlik tedbirlerinden başka bir ceza ve güvenlik tedbirine hükmolunamaz. (2) İdarenin düzenleyici işlemleriyle suç ve ceza konulamaz. (3) Kanunların suç ve ceza içeren hükümlerinin uygulanmasında kıyas yapılamaz. Suç ve ceza içeren hükümler, kıyasa yol açacak biçimde geniş yorumlanamaz.",
  "TCK m.20": "(1) Ceza sorumluluğu şahsidir. Kimse başkasının fiilinden dolayı sorumlu tutulamaz. (2) Tüzel kişiler hakkında ceza yaptırımı uygulanamaz. Ancak, suç dolayısıyla kanunda öngörülen güvenlik tedbiri niteliğindeki yaptırımlar saklıdır.",
  "TCK m.21": "(1) Suçun oluşması kastın varlığına bağlıdır. Kast, suçun kanuni tanımındaki unsurların bilerek ve istenerek gerçekleştirilmesidir. (2) Kişinin, suçun kanuni tanımındaki unsurların gerçekleşebileceğini öngörmesine rağmen, fiili işlemesi halinde olası kast vardır. Bu halde, (...) temel ceza üçte birden yarısına kadar indirilir.",
  "TCK m.22": "(1) Taksirle işlenen fiiller, kanunun açıkça belirttiği hallerde cezalandırılır. (2) Taksir, dikkat ve özen yükümlülüğüne aykırılık dolayısıyla, bir davranışın suçun kanuni tanımında belirtilen neticesi öngörülmeyerek gerçekleştirilmesidir. (3) Kişinin öngördüğü neticeyi istememesine karşın, neticenin meydana gelmesi halinde bilinçli taksir vardır; bu halde taksirli suça ilişkin ceza üçte birden yarısına kadar artırılır.",
  "TCK m.23": "(1) Bir fiilin, kastedilenden daha ağır veya başka bir neticenin oluşumuna sebebiyet vermesi halinde, kişinin bundan dolayı sorumlu tutulabilmesi için bu netice bakımından en azından taksirle hareket etmesi gerekir.",
  "TCK m.247": "(1) Görevi nedeniyle zilyedliği kendisine devredilmiş olan veya koruma ve gözetimiyle yükümlü olduğu malı kendisinin veya başkasının zimmetine geçiren kamu görevlisi, beş yıldan oniki yıla kadar hapis cezası ile cezalandırılır. (2) Suçun, zimmetin açığa çıkmamasını sağlamaya yönelik hileli davranışlarla işlenmesi halinde, verilecek ceza yarı oranında artırılır. (3) Zimmet suçunun, malın geçici bir süre kullanıldıktan sonra iade edilmek üzere işlenmesi halinde, verilecek ceza yarı oranına kadar indirilebilir.",
  "TCK m.248": "(1) Soruşturma başlamadan önce, zimmete geçirilen malın aynen iade edilmesi veya uğranılan zararın tamamen tazmin edilmesi halinde, verilecek cezanın üçte ikisi indirilir. (2) Kovuşturma başlamadan önce, gönüllü olarak, (...) verilecek cezanın yarısı indirilir. Etkin pişmanlığın hükümden önce gerçekleşmesi halinde, verilecek cezanın üçte biri indirilir.",
  "TCK m.249": "(1) Zimmet suçunun konusunu oluşturan malın değerinin azlığı nedeniyle, verilecek ceza üçte birden yarıya kadar indirilir.",
  "TCK m.250": "(1) Görevinin sağladığı nüfuzu kötüye kullanmak suretiyle kendisine veya başkasına yarar sağlanmasına (...) bir kimseyi icbar eden kamu görevlisi, beş yıldan on yıla kadar hapis cezası ile cezalandırılır. (...) (2) Görevinin sağladığı güveni kötüye kullanmak suretiyle gerçekleştirdiği hileli davranışlarla, (...) bir kimseyi ikna eden kamu görevlisi, üç yıldan beş yıla kadar hapis cezası ile cezalandırılır. (3) İkinci fıkrada tanımlanan suçun kişinin hatasından yararlanarak işlenmiş olması halinde, bir yıldan üç yıla kadar hapis cezasına hükmolunur. (...)",
  "TCK m.251": "(1) Zimmet veya irtikap suçunun işlenmesine kasten göz yuman denetimle yükümlü kamu görevlisi, işlenen suçun müşterek faili olarak sorumlu tutulur. (2) Denetim görevini ihmal ederek, zimmet veya irtikap suçunun işlenmesine imkan sağlayan kamu görevlisi, üç aydan üç yıla kadar hapis cezası ile cezalandırılır.",
  "TCK m.252": "(1) Görevinin ifasıyla ilgili bir işi yapması veya yapmaması için, doğrudan veya aracılar vasıtasıyla, bir kamu görevlisine veya göstereceği bir başka kişiye menfaat sağlayan kişi, dört yıldan oniki yıla kadar hapis cezası ile cezalandırılır. (2) (...) menfaat sağlayan kamu görevlisi de birinci fıkrada belirtilen ceza ile cezalandırılır. (3) Rüşvet konusunda anlaşmaya varılması halinde, suç tamamlanmış gibi cezaya hükmolunur. (...)",
  "TCK m.253": "(1) Rüşvet suçunun işlenmesi suretiyle yararına haksız menfaat sağlanan tüzel kişiler hakkında bunlara özgü güvenlik tedbirlerine hükmolunur.",
  "TCK m.254": "(1) Rüşvet alan kişinin, durum resmi makamlarca öğrenilmeden önce, rüşvet konusu şeyi soruşturmaya yetkili makamlara aynen teslim etmesi halinde, hakkında rüşvet suçundan dolayı cezaya hükmolunmaz. (...) (2) Rüşvet veren veya bu konuda kamu görevlisiyle anlaşmaya varan kişinin, durum resmi makamlarca öğrenilmeden önce, pişmanlık duyarak durumdan yetkili makamları haberdar etmesi halinde, hakkında rüşvet suçundan dolayı cezaya hükmolunmaz. (...)",
  "TCK m.255": "(1) Kamu görevlisi üzerinde nüfuz sahibi olduğundan bahisle, haksız bir işin gördürülmesi amacıyla girişimde bulunması için, doğrudan veya aracılar vasıtasıyla, kendisine veya bir başkasına menfaat temin eden kişi, iki yıldan beş yıla kadar hapis ve beşbin güne kadar adli para cezası ile cezalandırılır. (...)",
  "TCK m.256": "(1) Zor kullanma yetkisine sahip kamu görevlisinin, görevini yaptığı sırada, kişilere karşı görevinin gerektirdiği ölçünün dışında kuvvet kullanması halinde, kasten yaralama suçuna ilişkin hükümler uygulanır.",
  "TCK m.257": "(1) Kanunda ayrıca suç olarak tanımlanan haller dışında, görevinin gereklerine aykırı hareket etmek suretiyle, kişilerin mağduriyetine veya kamunun zararına neden olan ya da kişilere haksız bir menfaat sağlayan kamu görevlisi, altı aydan iki yıla kadar hapis cezası ile cezalandırılır. (2) Kanunda ayrıca suç olarak tanımlanan haller dışında, görevinin gereklerini yapmakta ihmal veya gecikme göstererek, (...) üç aydan bir yıla kadar hapis cezası ile cezalandırılır.",
  "TCK m.258": "(1) Görevi nedeniyle kendisine verilen veya aynı nedenle bilgi edindiği ve gizli kalması gereken belgeleri, kararları ve emirleri ve diğer tebligatı açıklayan veya yayınlayan veya ne suretle olursa olsun başkalarının bilgi edinmesini kolaylaştıran kamu görevlisine, bir yıldan dört yıla kadar hapis cezası verilir. (2) Kamu görevlisi sıfatı sona erdikten sonra, birinci fıkrada yazılı fiilleri işleyen kimseye de aynı ceza verilir.",
  "TCK m.259": "(1) Yürüttüğü görevin sağladığı nüfuzdan yararlanarak, bir başkasına mal veya hizmet satmaya çalışan kamu görevlisi, altı aya kadar hapis veya adlî para cezası ile cezalandırılır.",
  "TCK m.260": "(1) Hukuka aykırı olarak ve toplu biçimde, görevlerini terk eden, görevlerine gelmeyen, görevlerini geçici de olsa kısmen veya tamamen yapmayan veya yavaşlatan kamu görevlilerinin her biri hakkında üç aydan bir yıla kadar hapis cezası verilir. Kamu görevlisi sayısının üçten fazla olmaması halinde cezaya hükmolunmaz. (2) (...) hizmeti aksatmayacak biçimde, geçici ve kısa süreli iş bırakmaları (...) halinde, verilecek cezada indirim yapılabileceği gibi, ceza da verilmeyebilir.",
  "TCK m.261": "(1) İlgili kanunlarda belirlenen koşullara aykırı olduğunu bilerek, kişilerin taşınır veya taşınmaz malları üzerinde, karşılık ödenmek suretiyle de olsa, zorla tasarrufta bulunan kamu görevlisi, fiil daha ağır cezayı gerektiren bir suç oluşturmadığı takdirde, altı aydan iki yıla kadar hapis cezası ile cezalandırılır.",
  "TCK m.262": "(1) Bir kamu görevini, kanun ve nizamlara aykırı olarak yerine getirmeye teşebbüs eden veya terk emri kendisine bildirilmiş olduğu halde görevi sürdüren kimseye üç aydan iki yıla kadar hapis cezası verilir.",
  "TCK m.264": "(1) Bir rütbe veya kamu görevinin veya mesleğin, resmi elbisesini yetkisi olmaksızın alenen ve başkalarını yanıltacak şekilde giyen veya hakkı olmayan nişan veya madalyaları takan kimseye üç aydan bir yıla kadar hapis cezası verilir. (2) Elbisenin sağlayacağı kolaylık ve olanaklardan yararlanarak bir suç işlenirse, yalnız bu fiilden ötürü yukarıdaki fıkrada belirtilen cezalar üçte biri oranında artırılarak hükmolunur.",
  "TCK m.265": "(1) Kamu görevlisine karşı görevini yapmasını engellemek amacıyla, cebir veya tehdit kullanan kişi, altı aydan üç yıla kadar hapis cezası ile cezalandırılır. (2) Suçun yargı görevi yapan kişilere karşı işlenmesi halinde, iki yıldan dört yıla kadar hapis cezasına hükmolunur. (...) (4) Suçun, silahla ya da var olan veya var sayılan suç örgütlerinin (...) işlenmesi halinde, (...) ceza yarı oranında artırılır. (...)",
  "TCK m.266": "(1) Görevi gereği olarak elinde bulundurduğu araç ve gereçleri bir suçun işlenmesi sırasında kullanan kamu görevlisi hakkında, ilgili suçun tanımında kamu görevlisi sıfatı esasen göz önünde bulundurulmamış ise, verilecek ceza üçte biri oranında artırılır.",
  "TCK m.3": "(1) Suç işleyen kişi hakkında işlenen fiilin ağırlığıyla orantılı ceza ve güvenlik tedbirine hükmolunur. (2) Ceza Kanununun uygulamasında kişiler arasında ırk, dil, din, mezhep, milliyet, renk, cinsiyet, siyasal veya diğer fikir yahut düşünceleri, felsefi inanç, milli veya sosyal köken, doğum, ekonomik ve diğer toplumsal konumları yönünden ayrım yapılamaz ve hiçbir kimseye ayrıcalık tanınamaz.",
  "TCK m.317": "(1) Kanunen yetkili olmadıkları veya Devlet tarafından memur edilmedikleri halde, bir asker kıtasının veya donanmasının veya savaş gemisinin veya savaş hava filosunun veya bir kale veya müstahkem mevkiin veya bir askerî üssün veya tesisin, bir liman veya şehrin komutasını alanlara müebbet hapis cezası verilir. (2) (...) yetkili makamlarca komutanlığı terk etmeleri için verilen emirlere uymayanlara da aynı ceza verilir.",
  "TCK m.318": "(1) Askerlik hizmetini yapanları firara sevk edecek veya askerlik hizmetine katılacak olanları bu hizmeti yapmaktan vazgeçirecek şekilde teşvik veya telkinde bulunanlara altı aydan iki yıla kadar hapis cezası verilir. (2) Fiil, basın ve yayın yolu ile işlenirse ceza yarısı oranında artırılır.",
  "TCK m.319": "(1) Askerleri veya askerî idareye bağlı olarak görev yapan diğer kişileri kanunlara karşı itaatsizliğe veya yeminlerini bozmaya veya askerî disiplini veya askerlik hizmetine ilişkin görevlerini ihlale yönelten ve tahrik edenler (...) bir yıldan üç yıla kadar hapis cezası verilir. (2) Fiil, aleni olarak işlenmişse iki yıldan beş yıla kadar hapis cezası verilir. (3) Fiil, savaş zamanında işlenmiş ise ceza bir katı oranında artırılır.",
  "TCK m.320": "(1) Hükûmetin izni olmaksızın bir yabancı veya yabancı Devlet hizmetinde veya bunların lehinde çalışmak üzere Ülke içinde vatandaşlardan asker yazan veya vatandaşları silahlandıran kimseye üç yıldan altı yıla kadar hapis cezası verilir. (2) Asker yazılanlar veya silahlandırılanlar arasından asker veya askerlik çağında olanlar varsa ceza üçte biri oranında artırılır. (3) Birinci fıkradaki hizmeti kabul eden kimseye bir yıldan üç yıla kadar hapis cezası verilir.",
  "TCK m.321": "(1) Savaş zamanında Devletin yetkili makam ve mercilerinin emir veya kararlarına bilerek aykırı harekette bulunan kimseye bir yıldan altı yıla kadar hapis cezası verilir.",
  "TCK m.322": "(1) Savaş zamanında, Devletin silahlı kuvvetlerinin veya halkın ihtiyaçları için Devlet veya bir kamu kuruluşu (...) ile iş yapmak veya eşya vermek üzere yaptıkları sözleşmedeki yükümlülükleri kısmen veya tamamen yerine getirmeyen kimseye üç yıldan on yıla kadar hapis ve onbin güne kadar adlî para cezası verilir. (2) Yükümlülüklerin kısmen veya tamamen yerine getirilmemesi taksirden ileri gelmişse, cezanın dörtte üçüne kadarı indirilebilir. (...) (4) Savaş zamanında yükümlülüklerin yerine getirilmesinde hile yapan (...) on yıldan onbeş yıla kadar hapis ve (...)",
  "TCK m.323": "(1) Savaş sırasında kamunun endişe ve heyecan duymasına neden olacak veya halkın maneviyatını sarsacak veya düşman karşısında ülkenin direncini azaltacak şekilde asılsız veya abartılmış veya özel maksada dayalı havadis veya haber yayan veya nakleden veya temel milli yararlara zarar verebilecek herhangi bir faaliyette bulunan kimseye beş yıldan on yıla kadar hapis cezası verilir. (...) (3) Fiil, düşmanla anlaşma neticesi işlenmişse müebbet hapis cezası verilir.",
  "TCK m.324": "(1) Sulh zamanında seferberlikle ilgili görevlerini ihmal eden veya geciktiren kamu görevlisine altı aydan üç yıla kadar hapis cezası verilir.",
  "TCK m.325": "(1) Türkiye ile savaş halinde bulunan bir devletten akademik derece veya şeref, unvan, nişan ve diğer fahri rütbe veya bunlara ait maaş veya başka yararlar kabul eden vatandaşa bir yıldan üç yıla kadar hapis cezası verilir.",
  "TCK m.35": "(1) Kişi, işlemeyi kastettiği bir suçu elverişli hareketlerle doğrudan doğruya icraya başlayıp da elinde olmayan nedenlerle tamamlayamaz ise teşebbüsten dolayı sorumlu tutulur. (2) Suça teşebbüs halinde fail, meydana gelen zarar veya tehlikenin ağırlığına göre, (...) Diğer hallerde verilecek cezanın dörtte birinden dörtte üçüne kadarı indirilir.",
  "TCK m.36": "(1) Fail, suçun icra hareketlerinden gönüllü vazgeçer veya kendi çabalarıyla suçun tamamlanmasını veya neticenin gerçekleşmesini önlerse, teşebbüsten dolayı cezalandırılmaz; fakat tamam olan kısım esasen bir suç oluşturduğu takdirde, sadece o suça ait ceza ile cezalandırılır.",
  "TCK m.37": "(1) Suçun kanuni tanımında yer alan fiili birlikte gerçekleştiren kişilerden her biri, fail olarak sorumlu olur. (2) Suçun işlenmesinde bir başkasını araç olarak kullanan kişi de fail olarak sorumlu tutulur. Kusur yeteneği olmayanları suçun işlenmesinde araç olarak kullanan kişinin cezası, üçte birden yarısına kadar artırılır.",
  "TCK m.38": "(1) Başkasını suç işlemeye azmettiren kişi, işlenen suçun cezası ile cezalandırılır. (2) Üstsoy ve altsoy ilişkisinden doğan nüfuz kullanılmak suretiyle suça azmettirme halinde, azmettirenin cezası üçte birden yarısına kadar artırılır. (...)",
  "TCK m.39": "(1) Suçun işlenmesine yardım eden kişiye, (...) Diğer hallerde cezanın yarısı indirilir. Ancak, bu durumda verilecek ceza sekiz yılı geçemez. (2) Aşağıdaki hallerde kişi işlenen suçtan dolayı yardım eden sıfatıyla sorumlu olur: a) Suç işlemeye teşvik etmek veya suç işleme kararını kuvvetlendirmek veya fiilin işlenmesinden sonra yardımda bulunacağını vaat etmek. b) Suçun nasıl işleneceği hususunda yol göstermek veya fiilin işlenmesinde kullanılan araçları sağlamak. c) Suçun işlenmesinden önce veya işlenmesi sırasında yardımda bulunarak icrasını kolaylaştırmak.",
  "TCK m.4": "(1) Ceza kanunlarını bilmemek mazeret sayılmaz.",
  "TCK m.40": "(1) Suça iştirak için kasten ve hukuka aykırı işlenmiş bir fiilin varlığı yeterlidir. Suçun işlenişine iştirak eden her kişi, (...) kendi kusurlu fiiline göre cezalandırılır. (2) Özgü suçlarda, ancak özel faillik niteliğini taşıyan kişi fail olabilir. Bu suçların işlenişine iştirak eden diğer kişiler ise azmettiren veya yardım eden olarak sorumlu tutulur. (3) Suça iştirakten dolayı sorumlu tutulabilmek için ilgili suçun en azından teşebbüs aşamasına varmış olması gerekir.",
  "TCK m.41": "(1) İştirak halinde işlenen suçlarda, sadece gönüllü vazgeçen suç ortağı, gönüllü vazgeçme hükümlerinden yararlanır. (2) Suçun; a) Gönüllü vazgeçenin gösterdiği gayreti dışında başka bir sebeple işlenmemiş olması, b) Gönüllü vazgeçenin bütün gayretine rağmen işlenmiş olması, hallerinde de gönüllü vazgeçme hükümleri uygulanır.",
  "TCK m.42": "(1) Biri diğerinin unsurunu veya ağırlaştırıcı nedenini oluşturması dolayısıyla tek fiil sayılan suça bileşik suç denir. Bu tür suçlarda içtima hükümleri uygulanmaz.",
  "TCK m.43": "(1) Bir suç işleme kararının icrası kapsamında, değişik zamanlarda bir kişiye karşı aynı suçun birden fazla işlenmesi durumunda, bir cezaya hükmedilir. Ancak bu ceza, dörtte birinden dörtte üçüne kadar artırılır. (...) (2) Aynı suçun birden fazla kişiye karşı tek bir fiille işlenmesi durumunda da, birinci fıkra hükmü uygulanır. (3) Kasten öldürme, kasten yaralama, işkence ve yağma suçlarında bu madde hükümleri uygulanmaz.",
  "TCK m.44": "(1) İşlediği bir fiil ile birden fazla farklı suçun oluşmasına sebebiyet veren kişi, bunlardan en ağır cezayı gerektiren suçtan dolayı cezalandırılır.",
  "TCK m.45": "(1) Suç karşılığında uygulanan yaptırım olarak cezalar, hapis ve adlî para cezalarıdır.",
  "TCK m.5": "(1) Bu Kanunun genel hükümleri, özel ceza kanunları ve ceza içeren kanunlardaki suçlar hakkında da uygulanır.",
  "Tebligat m.2": "Diğer kanunlarda özel hüküm bulunması halinde veya tehirinde zarar umulan işlerde veya aynı yerde bulunan 1 inci maddede yazılı daire ve müesseseler arasında veya bu daire ve müesseselerde bulunan şahıslara yapılacak tebligat, kendi memurları veya mahalli mülkiye amirinin emriyle zabıta vasıtasıyla yaptırılır. Zor kullanılmasını gerektiren veya hazırlık tahkikatına taallük eden vazifelerini zabıta tarafından yapılacağına dair olan hükümlerle bu kanunun ikinci babında yazılı hususi hükümler mahfuzdur.",
  "Tebligat m.21": "Kendisine tebligat yapılacak kimse veya yukarıdaki maddeler mucibince tebligat yapılabilecek kimselerden hiçbiri gösterilen adreste bulunmaz veya tebellüğden imtina ederse, tebliğ memuru tebliğ olunacak evrakı, o yerin muhtar veya ihtiyar heyeti azasından birine veyahut zabıta amir veya memurlarına imza mukabilinde teslim eder ve tesellüm edenin adresini ihtiva eden ihbarnameyi gösterilen adresteki binanın kapısına yapıştırmakla beraber, adreste bulunmama halinde tebliğ olunacak şahsa keyfiyetin haber verilmesini de mümkün oldukça en yakın komşularından birine, varsa yönetici veya kapıcıya da bildirilir. İhbarnamenin kapıya yapıştırıldığı tarih, tebliğ tarihi sayılır.",
  "Tebligat m.22": "Muhatap yerine kendisine tebliğ yapılacak kimsenin görünüşüne nazaran onsekiz yaşından aşağı olmaması ve bariz bir surette ehliyetsiz bulunmaması lazımdır.",
  "Tebligat m.24": "Kendisine tebliğ yapılacak kimse imza edecek kadar yazı bilmez veya imza edemiyecek durumda bulunursa, komşularından bir kişi huzurunda sol elinin baş parmağı bastırılmak suretiyle tebliğ yapılır. Sol elinin baş parmağı bulunmıyan kimsenin, aynı elinin diğer bir parmağı ve sol eli yoksa sağ elinin baş parmağı ve bu da mevcut değilse diğer parmaklarından biri bastırılır. Tebliğ yapılacak kimsenin iki eli de yoksa tebliğ evrakı kendisine verilir. Yukardaki fıkralarda yazılı hallerde keyfiyet, tebliğ mazbatasında tasrih edilir ve hazır bulunan şahsa da imza ettirilir. Okur yazar bir komşu bulunmaz veya bulunan komşu imzadan imtina ederse, tebliğ memuru o mahalle veya köyün muhtar veya ihtiyar heyeti azasından birini veyahut bir zabıta memurunu, tebliğ sırasında hazır bulunmak üzere davet eder ve tebligat bunların huzurunda yapılır.",
  "Tebligat m.3": "Posta ve Telgraf Teşkilatı Genel Müdürlüğünün bu Kanuna göre yapacağı işlerden dolayı alacağı ücretler, bu işletme tarafından ayrı bir tarife ile tespit ve tayin edilir.",
  "Terörle Mücadele m.1": "Terör; cebir ve şiddet kullanarak; baskı, korkutma, yıldırma, sindirme veya tehdit yöntemlerinden biriyle, Anayasada belirtilen Cumhuriyetin niteliklerini, siyasî, hukukî, sosyal, laik, ekonomik düzeni değiştirmek, Devletin ülkesi ve milletiyle bölünmez bütünlüğünü bozmak, Türk Devletinin ve Cumhuriyetin varlığını tehlikeye düşürmek, Devlet otoritesini zaafa uğratmak veya yıkmak veya ele geçirmek, temel hak ve hürriyetleri yok etmek, Devletin iç ve dış güvenliğini, kamu düzenini veya genel sağlığı bozmak amacıyla bir örgüte mensup kişi veya kişiler tarafından girişilecek her türlü suç teşkil eden eylemlerdir.",
  "Terörle Mücadele m.2": "Birinci maddede belirlenen amaçlara ulaşmak için meydana getirilmiş örgütlerin mensubu olup da, bu amaçlar doğrultusunda diğerleri ile beraber veya tek başına suç işleyen veya amaçlanan suçu işlemese dahi örgütlerin mensubu olan kişi terör suçlusudur. Terör örgütüne mensup olmasa dahi örgüt adına suç işleyenler de terör suçlusu sayılır (…).",
  "Terörle Mücadele m.3": "26/9/2004 tarihli ve 5237 sayılı Türk Ceza Kanununun 302, 307, 309, 311, 312, 313, 314, 315 ve 320 nci maddeleri ile 310 uncu maddesinin birinci fıkrasında yazılı suçlar, terör suçlarıdır.",
  "Terörle Mücadele m.4": "Aşağıdaki suçlar 1 inci maddede belirtilen amaçlar doğrultusunda suç işlemek üzere kurulmuş bir terör örgütünün faaliyeti çerçevesinde işlendiği takdirde, terör suçu sayılır: a) Türk Ceza Kanununun 79, 80, 81, 82, 84, 86, 87, 96, 106, 107, 108, 109, 112, 113, 114, 115, 116, 117, 118, 142, 148, 149, 151, 152, 170, 172, 173, 174, 185, 188, 199, 200, 202, 204, 210, 213, 214, 215, 223, 224, 243, 244, 265, 294, 300, 316, 317, 318 ve 319 uncu maddeleri ile 310 uncu maddesinin ikinci fıkrasında yer alan suçlar. b) (…) 6136 sayılı Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Kanunda tanımlanan suçlar. c) (…) 6831 sayılı Orman Kanununun 110 uncu maddesinin dördüncü ve beşinci fıkralarında tanımlanan kasten orman yakma suçları. ç) (…) 4926 sayılı Kaçakçılıkla Mücadele Kanununda tanımlanan ve hapis cezasını gerektiren suçlar. d) Anayasanın 120 nci maddesi gereğince olağanüstü hal ilan edilen bölgelerde, olağanüstü halin ilanına neden olan olaylara ilişkin suçlar. e) (…) 2863 sayılı Kültür ve Tabiat Varlıklarını Koruma Kanununun 68 inci maddesinde tanımlanan suç.",
  "Terörle Mücadele m.5": "3 ve 4 üncü maddelerde yazılı suçları işleyenler hakkında ilgili kanunlara göre tayin edilecek hapis cezaları veya adlî para cezaları yarı oranında artırılarak hükmolunur. Bu suretle tayin olunacak cezalarda, gerek o fiil için, gerek her nevi ceza için muayyen olan cezanın yukarı sınırı aşılabilir. Ancak, müebbet hapis cezası yerine, ağırlaştırılmış müebbet hapis cezasına hükmolunur. Suçun, örgütün faaliyeti çerçevesinde işlenmiş olması dolayısıyla ilgili maddesinde cezasının artırılması öngörülmüşse; sadece bu madde hükmüne göre cezada artırım yapılır. Ancak, yapılacak artırım, cezanın üçte ikisinden az olamaz. Bu madde hükümleri çocuklar hakkında uygulanmaz.",
  "Terörle Mücadele m.6": "İsim ve kimlik belirterek veya belirtmeyerek kime yönelik olduğunun anlaşılmasını sağlayacak surette kişilere karşı terör örgütleri tarafından suç işleneceğini veya terörle mücadelede görev almış kamu görevlilerinin hüviyetlerini açıklayanlar veya yayınlayanlar veya bu yolla kişileri hedef gösterenler bir yıldan üç yıla kadar hapis cezası ile cezalandırılır. Terör örgütlerinin; cebir, şiddet veya tehdit içeren yöntemlerini meşru gösteren veya öven ya da bu yöntemlere başvurmayı teşvik eden bildiri veya açıklamalarını basanlar veya yayınlayanlar bir yıldan üç yıla kadar hapis cezası ile cezalandırılır. Bu Kanunun 14 üncü maddesine aykırı olarak muhbirlerin hüviyetlerini açıklayanlar veya yayınlayanlar bir yıldan üç yıla kadar hapis cezası ile cezalandırılır. Yukarıdaki fıkralarda belirtilen fiillerin basın ve yayın yoluyla işlenmesi hâlinde, basın ve yayın organlarının suçun işlenişine iştirak etmemiş olan (…) yayın sorumluları hakkında da bin günden beşbin güne kadar adlî para cezasına hükmolunur.",
  "Terörle Mücadele m.7": "Cebir ve şiddet kullanılarak; baskı, korkutma, yıldırma, sindirme veya tehdit yöntemleriyle, 1 inci maddede belirtilen amaçlara yönelik olarak suç işlemek üzere, terör örgütü kuranlar, yönetenler ile bu örgüte üye olanlar Türk Ceza Kanununun 314 üncü maddesi hükümlerine göre cezalandırılır. Örgütün faaliyetini düzenleyenler de örgütün yöneticisi olarak cezalandırılır. Terör örgütünün; cebir, şiddet veya tehdit içeren yöntemlerini meşru gösterecek veya övecek ya da bu yöntemlere başvurmayı teşvik edecek şekilde propagandasını yapan kişi, bir yıldan beş yıla kadar hapis cezası ile cezalandırılır. Bu suçun basın ve yayın yolu ile işlenmesi hâlinde, verilecek ceza yarı oranında artırılır. (…) Haber verme sınırlarını aşmayan veya eleştiri amacıyla yapılan düşünce açıklamaları suç oluşturmaz. Aşağıdaki fiil ve davranışlar da bu fıkra hükümlerine göre cezalandırılır: a) (Mülga) b) Toplantı ve gösteri yürüyüşü sırasında gerçekleşmese dahi, terör örgütünün üyesi veya destekçisi olduğunu belli edecek şekilde; 1. Örgüte ait amblem, resim veya işaretlerin asılması ya da taşınması, 2. Slogan atılması, 3. Ses cihazları ile yayın yapılması, 4. Terör örgütüne ait amblem, resim veya işaretlerin üzerinde bulunduğu üniformanın giyilmesi. Terör örgütünün propagandasına dönüştürülen toplantı ve gösteri yürüyüşlerinde, kimliklerini gizlemek amacıyla yüzünü tamamen veya kısmen kapatanlar üç yıldan beş yıla kadar hapis cezasıyla cezalandırılır. Bu suçu işleyenlerin cebir ve şiddete başvurmaları ya da her türlü silah, molotof ve benzeri patlayıcı, yakıcı ya da yaralayıcı maddeler bulundurmaları veya kullanmaları hâlinde verilecek cezanın alt sınırı dört yıldan az olamaz.",
  "Türk Bayrağı m.2": "Madde 1 – Bu Kanunun amacı Türk Bayrağının şekli, yapımı ve korunması ile ilgili esas ve usulleri belirlemektir. Madde 2 – Türk Bayrağı, bu Kanuna ekli cetvelde gösterilen şekil ve oranlarda olmak kaydıyla beyaz ay - yıldızlı albayraktır. Bayrak ile özel bayrakların (sembolik bayrak, özel işaret, flama, flandra ve fors) standartları, hangi kumaş ve maddelerden yapılacağı yönetmelikte gösterilir.",
  "Türk Bayrağı m.3": "Madde 3 – Bayrak, kamu kurum ve kuruluşlarıyla yurt dışı temsilciliklerine ve kamu kuruluşlarıyla gerçek ve tüzelkişilerin deniz vasıtalarına çekilir. Yurt içinde ve yurt dışında yetkililerin araçlarına takılır. Bayrak çekilirken ve indirilirken tören yapılır. Bayrak törenlerinin gereken biçimde yapılmasından o mahaldeki yetkili amirler sorumludur. (Değişik: 14/7/1999 - 4409/1 md.) Kamu kurum ve kuruluşlarında Türk Bayrağı sürekli çekili kalır. (...)",
  "Türk Bayrağı m.4": "Madde 4 – Türk Bayrağı, yas alameti olarak 10 KASIM'da yarıya çekilir. Yas alameti olmak üzere Bayrağın yarıya çekileceği diğer haller ve zamanı Cumhurbaşkanlığınca ilan edilir.",
  "Türk Bayrağı m.5": "Madde 5 – Çekilmesi ve indirilmesi esnasında veya tören geçişlerinde Bayrak, cephe alınarak selamlanır.",
  "Türk Bayrağı m.6": "Madde 6 – Türk Bayrağı, Cumhurbaşkanlığı yapmış kişilerin, şehitlerin ve yönetmelikte belirlenecek asker ve sivil kişilerin cenaze törenlerinde bunların tabutlarına, açılış törenlerinde ATATÜRK heykellerine veya resmi yemin törenlerinde masalara örtülebilir. Ayrıca milli orf ve adetler göz önünde tutularak Bayrağın diğer kullanılma şekil ve yeri yönetmelikte gösterilir.",
  "Türk Bayrağı m.7": "Madde 7 – Türk Bayrağı, yırtık, sökük, yamalı, delik, kirli, soluk, buruşuk veya layık olduğu manevi değeri zedeleyecek herhangi bir şekilde kullanılamaz. Resmi yemin törenleri dışında her ne maksatla olursa olsun, masalara kürsülere, örtü olarak serilemez. Oturulan veya ayakla basılan yerlere konulamaz. Bu yerlere ve benzeri eşyaya Bayrağın şekli yapılamaz. Elbise veya uniforma şeklinde giyilemez. (...) Türk Bayrağına sözle, yazı veya hareketle veya herhangi bir şekilde hakaret edilemez, saygısızlıkta bulunulamaz. Bayrak yırtılamaz, yakılamaz, yere atılamaz, gerekli özen gösterilmeden kullanılamaz. (...)",
  "Türk Bayrağı m.8": "Madde 8 – (Değişik: 23/1/2008-5728/421 md.) Bu Kanuna ve çıkarılacak yönetmeliğe aykırı olarak Bayrak yapmak, satmak ve kullanmak yasaktır. Bu yasağa aykırı olarak yapılan Bayraklar o mahallin yetkili amirlerince toplatılır. Bu Kanun hükümlerine aykırı davranışta bulunanlara, fiilleri suç oluşturmadığı takdirde mahalli mülki amir tarafından Kabahatler Kanununun 32 nci maddesi uyarınca idarî para ceza verilir.",
};
